-- 1
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يرغب مدير مخاطر تم تكليفه بإدارة فعالية رياضية، في نشر وثيقة لتوجيه الاتحادات الرياضية التابعة للدول المشاركة بشأن الإجراءات الواجب اتباعها لتحديد أي مخاطر قد تؤثر في المشاركة الناجحة لفرقهم، وتقييمها والتواصل بشأنها. ما الوثيقة التي ينبغي على مدير المخاطر نشرها؟', 'A risk manager who has been assigned to manage a sporting event wants to publish a document that guides the national sports federations of the participating countries on the procedures to follow for identifying, assessing, and communicating any risks that could affect the successful participation of their teams. Which document should the risk manager publish?', 'خطة إدارة المخاطر هي الوثيقة التي تشرح إجراءات تحديد المخاطر وتقييمها وتحليلها والاستجابة لها والتواصل بشأنها. وتحدد عادةً الأدوار والمسؤوليات، وفئات المخاطر ومعايير التقييم، وطرق إعداد التقارير والتواصل، وحدود المخاطر وإجراءات التصعيد. أما سجل المخاطر فيوثق المخاطر الفردية ولا يحدد الإجراءات الكاملة لإدارتها.', 'The risk management plan is the document that describes the procedures for identifying, assessing, analyzing, responding to, and communicating risks. It typically defines roles and responsibilities, risk categories and assessment criteria, reporting and communication methods, risk thresholds, and escalation procedures. The risk register, by contrast, documents individual risks; it does not define the complete procedures for managing them.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'نموذج سجل المخاطر.', 'Risk register template.', false),
      (1, 'خطة التأهيل النوعي للمخاطر.', 'Qualitative risk analysis plan.', false),
      (2, 'نموذج تقرير المخاطر.', 'Risk report template.', false),
      (3, 'خطة إدارة المخاطر.', 'Risk management plan.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 0, id FROM question;

-- 2
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تطلق شركة تكنولوجيا مشروعًا يهدف في النهاية إلى تقديم تطبيق جديد للهواتف المحمولة. وبسبب وجود مشروعات داخلية أخرى متنافسة، فإن موارد التطوير الوحيدة المتاحة موزعة في مواقع جغرافية مختلفة. وقد وثّق مدير المشروع هذا الأمر باعتباره خطرًا في محضر اجتماع المشروع، وطلب من مدير المخاطر تحديد حلول محتملة مع الحفاظ على ميزانية المشروع وجدوله الزمني الحاليين. ما الذي ينبغي على مدير المخاطر فعله لتلبية طلب مدير المشروع؟', 'A technology company is launching a project that will ultimately deliver a new mobile application. Because of other competing internal projects, the only development resources available are distributed across different geographic locations. The project manager documented this as a risk in the project meeting minutes and asked the risk manager to identify possible solutions while keeping the project''s current budget and schedule. What should the risk manager do to satisfy the project manager''s request?', 'توزيع فريق التطوير بين مواقع جغرافية مختلفة قد يؤدي إلى ضعف التواصل وعدم وضوح المسؤوليات وصعوبة التنسيق. يساعد الاجتماع الرسمي لبدء المشروع على توحيد فهم أهداف المشروع وأولوياته، وتوضيح الأدوار والمسؤوليات، والاتفاق على وسائل التواصل وأدوات التعاون وآلية العمل بين المواقع والمناطق الزمنية، دون زيادة الميزانية أو تمديد الجدول الزمني.', 'Distributing the development team across different geographic locations can lead to weak communication, unclear responsibilities, and coordination difficulties. A formal project kickoff meeting helps to build a shared understanding of project objectives and priorities, clarify roles and responsibilities, and agree on communication channels, collaboration tools, and working arrangements across locations and time zones, without increasing the budget or extending the schedule.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التوصية بإضافة وقت احتياطي لاستيعاب التأخيرات المحتملة في التواصل.', 'Recommend adding buffer time to absorb potential communication delays.', false),
      (1, 'التوصية بعقد اجتماع رسمي لبدء المشروع لضمان التوافق بين أعضاء فريق التطوير.', 'Recommend holding a formal project kickoff meeting to ensure alignment among the development team members.', true),
      (2, 'التوصية بتخصيص احتياطيات المشروع للسفر حتى يعمل فريق التطوير في موقع واحد خلال أيام العمل.', 'Recommend allocating project reserves to travel so that the development team works in a single location during working days.', false),
      (3, 'التوصية بقبول الخطر لأن الشركة لديها مشروعات أخرى متنافسة قيد التنفيذ.', 'Recommend accepting the risk because the company has other competing projects in progress.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 1, id FROM question;

-- 3
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يخطط فريق مشروع لتنفيذ مشروع للطاقة المتجددة في منطقة تتسم بأنماط طقس غير متوقعة ومتطلبات تنظيمية مختلفة. ولضمان الإدارة الفعالة للمخاطر يجب على الفريق توثيق محفزات المخاطر وحدودها بما يتوافق مع السياق الفريد للمشروع، مع مراعاة معايير المنظمة والبيانات التاريخية للمشروعات المشابهة. ما النهج الذي يوضح التوثيق الفعال لهذه العناصر؟', 'A project team is planning to deliver a renewable energy project in a region characterized by unpredictable weather patterns and varying regulatory requirements. To ensure effective risk management, the team must document risk triggers and thresholds that fit the project''s unique context, while taking into account organizational standards and historical data from similar projects. Which approach demonstrates effective documentation of these elements?', 'يجب تخصيص محفزات المخاطر وحدودها وفقًا لظروف المشروع، ومنها تقلبات الطقس غير المتوقعة، واختلاف المتطلبات التنظيمية واحتمال تغيرها، وتوقعات المعنيين وشهيتهم للمخاطر، ومعايير المنظمة وسجلات المشروعات المشابهة. البيانات التاريخية مصدر مفيد، لكنها لا تُطبَّق كما هي دون تكييفها مع طبيعة المشروع.', 'Risk triggers and thresholds must be tailored to the project''s circumstances, including unpredictable weather variability, differing regulatory requirements and the possibility that they will change, stakeholder expectations and risk appetite, organizational standards, and records of similar projects. Historical data is a useful source, but it should not be applied as-is without adapting it to the nature of the project.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'استخدام البيانات التاريخية للمشروعات السابقة مع إجراء تعديلات محدودة عليها لتحديد محفزات وحدود المشروع الحالي.', 'Use historical data from previous projects with limited adjustments to define the triggers and thresholds for the current project.', false),
      (1, 'تحديد محفزات وحدود للمخاطر خاصة بالمشروع، مع مراعاة سياقه وبيئته والمعنيين به.', 'Define project-specific risk triggers and thresholds that take into account the project''s context, environment, and stakeholders.', true),
      (2, 'الاعتماد فقط على التقييمات النوعية للمخاطر المحتملة لتحديد المحفزات والحدود المناسبة.', 'Rely solely on qualitative assessments of potential risks to define the appropriate triggers and thresholds.', false),
      (3, 'وضع محفزات وحدود عامة للمخاطر يمكن تطبيقها على جميع مشروعات المنظمة لضمان الاتساق.', 'Establish generic risk triggers and thresholds that can be applied to all of the organization''s projects to ensure consistency.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 2, id FROM question;

-- 4
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يعمل فريق مشروع على تنفيذ نظام جديد لإحدى شركات التجزئة الكبرى. وقد تم تكليف مدير المخاطر بالتأكد من تحديد جميع المخاطر المحتملة. ويريد مدير المشروع التأكد من توثيق معايير ترتيب أولويات المخاطر بشكل مناسب ضمن خطة إدارة المخاطر. ما المعيار الذي ينبغي لمدير المخاطر تحديده عند توثيق خطة إدارة المخاطر لترتيب أولويات المخاطر؟', 'A project team is implementing a new system for a major retail company. The risk manager has been assigned to ensure that all potential risks are identified. The project manager wants to ensure that the risk prioritization criteria are properly documented in the risk management plan. Which criterion should the risk manager define when documenting the risk management plan for prioritizing risks?', 'معايير ترتيب أولويات المخاطر تحدد كيفية تقييم المخاطر وترتيبها، ومن أهمها مقدار تأثير الخطر المحتمل في أهداف المشروع مثل التكلفة والجدول الزمني والنطاق والجودة. لذلك يُعد تأثير الخطر في ميزانية المشروع معيارًا واضحًا وقابلًا للقياس؛ وكلما زاد التأثير المالي للخطر ارتفعت أولويته عادةً.', 'Risk prioritization criteria define how risks are assessed and ranked. One of the most important criteria is the magnitude of a potential risk''s impact on project objectives such as cost, schedule, scope, and quality. A risk''s impact on the project budget is therefore a clear and measurable criterion; the greater the financial impact of a risk, the higher its priority usually is.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تأثير التكلفة في ميزانية المشروع.', 'Cost impact on the project budget.', true),
      (1, 'مستوى تأثير المعنيين.', 'Level of stakeholder influence.', false),
      (2, 'درجة تعقيد سيناريو الخطر.', 'Degree of complexity of the risk scenario.', false),
      (3, 'البيانات التاريخية للمشروعات المشابهة.', 'Historical data from similar projects.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
