-- 5
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'متى ينبغي الموازنة بين فوائد التحليل الكمي للمخاطر والجهد المطلوب لتنفيذه، للتأكد من أن المعلومات والقيمة الإضافية التي يقدمها تبرران هذا الجهد؟', 'When should the benefits of quantitative risk analysis be weighed against the effort required to perform it, to ensure that the additional information and value it provides justify that effort?', 'يمكن للتحليل الكمي للمخاطر تقديم معلومات رقمية مهمة، مثل احتمالية إكمال المشروع ضمن الميزانية والجدول الزمني، وحجم التعرض الكلي لمخاطر المشروع، واحتياطيات الطوارئ المطلوبة، والمخاطر الأكثر تأثيرًا في النتائج. لكنه يحتاج إلى وقت وتكلفة وبيانات موثوقة وأدوات وخبرات متخصصة. لذلك يجب خلال تخطيط إدارة المخاطر تحديد ما إذا كانت القيمة الإضافية للتحليل الكمي تبرر الجهد المطلوب لتنفيذه.', 'Quantitative risk analysis can provide important numerical information, such as the probability of completing the project within budget and on schedule, the overall project risk exposure, the contingency reserves required, and the risks with the greatest influence on outcomes. However, it requires time, cost, reliable data, tools, and specialized expertise. Therefore, during risk management planning, it must be determined whether the added value of quantitative analysis justifies the effort required to perform it.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'أثناء عملية تخطيط إدارة المخاطر.', 'During the Plan Risk Management process.', true),
      (1, 'بعد تقييم جميع المخاطر الفردية ومنحها درجات.', 'After all individual risks have been assessed and scored.', false),
      (2, 'بعد تحديد المخاطر بواسطة المعنيين.', 'After risks have been identified by the stakeholders.', false),
      (3, 'بعد تقدير مستوى المخاطر الكلي للمشروع.', 'After the overall project risk level has been estimated.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
