-- 6
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقود فريق مشروعًا متعدد التخصصات لإطلاق منتج جديد. وخلال اجتماع الفريق، تم تحديد مخاطر مثل تأخيرات التصنيع والعقبات التنظيمية، بالإضافة إلى فرص مثل توفير التكاليف والتوسع في السوق. اقترح بعض أعضاء الفريق التعامل مع جميع المخاطر بالطريقة نفسها، بينما أراد آخرون التركيز فقط على التهديدات. ما الذي ينبغي على مدير المخاطر فعله؟', 'A team is leading a multidisciplinary project to launch a new product. During a team meeting, risks such as manufacturing delays and regulatory obstacles were identified, along with opportunities such as cost savings and market expansion. Some team members suggested handling all risks in the same way, while others wanted to focus only on threats. What should the risk manager do?', 'تشمل مخاطر المشروع التهديدات، مثل تأخير التصنيع والعقبات التنظيمية، والفرص، مثل توفير التكاليف والتوسع في السوق. ينبغي تصنيف كل خطر وتحليله ثم اختيار الاستجابة التي تناسب نوعه: للتهديدات التجنب أو التخفيف أو النقل أو القبول أو التصعيد، وللفرص الاستغلال أو التعزيز أو المشاركة أو القبول أو التصعيد. لا توجد استجابة واحدة تناسب جميع المخاطر.', 'Project risks include threats, such as manufacturing delays and regulatory obstacles, and opportunities, such as cost savings and market expansion. Each risk should be categorized and analyzed, and then a response appropriate to its type should be selected: for threats, avoid, mitigate, transfer, accept, or escalate; for opportunities, exploit, enhance, share, accept, or escalate. No single response fits all risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'توزيع المسؤوليات بين أعضاء الفريق للتعامل مع المخاطر والفرص بصورة منفصلة.', 'Divide responsibilities among team members so that risks and opportunities are handled separately.', false),
      (1, 'توجيه الفريق لتصنيف المخاطر وتنفيذ استراتيجيات تتناسب مع كل فئة.', 'Direct the team to categorize the risks and implement strategies appropriate to each category.', true),
      (2, 'التركيز بصورة أساسية على التهديدات لتجنب تأخيرات المشروع وتعطله.', 'Focus primarily on threats to avoid project delays and disruptions.', false),
      (3, 'التعامل مع جميع المخاطر بالطريقة نفسها لتبسيط عملية إدارة المخاطر.', 'Handle all risks in the same way to simplify the risk management process.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 5, id FROM question;

-- 7
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يتولى مدير المخاطر الإشراف على مشروع حكومي للبنية التحتية للنقل، وطُلب منه تقييم التجاوزات المحتملة في التكلفة والتأخيرات في الجدول الزمني. بالاعتماد على تطورات المشروع الأخيرة وبيانات المشروعات السابقة المشابهة، والهدف هو التنبؤ بالمخاطر بفعالية. ما الأسلوب الذي ينبغي أن يستخدمه مدير المخاطر؟', 'A risk manager is overseeing a government transportation infrastructure project and has been asked to assess potential cost overruns and schedule delays. The assessment is to be based on recent project developments and data from similar past projects, and the objective is to forecast risks effectively. Which technique should the risk manager use?', 'محاكاة مونت كارلو إحدى تقنيات التحليل الكمي للمخاطر وتُستخدم للتنبؤ بنطاق النتائج المحتملة للمشروع. يمكن إدخال بيانات التكلفة والجدول الزمني الحالية، وبيانات المشروعات السابقة المشابهة، وتقديرات المشروع الحالية وحالات عدم اليقين وتأثيرات المخاطر المحددة. ثم تنفذ المحاكاة آلاف السيناريوهات المحتملة لتقدير احتمالية إكمال المشروع ضمن الميزانية والموعد المحددين، ونطاق التجاوزات والتأخيرات المحتملة، والاحتياطي المطلوب.', 'Monte Carlo simulation is a quantitative risk analysis technique used to forecast the range of possible project outcomes. Current cost and schedule data, data from similar past projects, current project estimates, uncertainties, and the impacts of identified risks can all be entered as inputs. The simulation then runs thousands of possible scenarios to estimate the probability of completing the project within the defined budget and deadline, the range of potential overruns and delays, and the reserve required.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'أسلوب دلفي لجمع آراء الخبراء حول احتمالية المخاطر.', 'The Delphi technique to gather expert opinions on risk probability.', false),
      (1, 'تحليل بيرت PERT لتحديد الجداول الزمنية المستقبلية للمشروع.', 'PERT analysis to determine future project schedules.', false),
      (2, 'تحليل السبب الجذري للمخاطر التي تم تحديدها سابقًا.', 'Root cause analysis of previously identified risks.', false),
      (3, 'محاكاة مونت كارلو لنمذجة نطاقات تأثير المخاطر.', 'Monte Carlo simulation to model the ranges of risk impact.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
