WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يعاني أحد المشاريع منذ عدة أشهر من انخفاض في مؤشر أداء التكلفة ومؤشر أداء الجدول الزمني. وأدرك مدير المخاطر أن بعض الأنشطة تستغرق وقتًا أطول من المتوقع، وأنها تحتاج إلى موارد إضافية. ما وثيقة المشروع التي ينبغي على مدير المخاطر تحليلها للحد من خطر استمرار تجاوز المشروع للتكلفة والجدول الزمني؟', 'A project has been experiencing a decline in its cost performance index (CPI) and schedule performance index (SPI) for several months. The risk manager has realized that some activities are taking longer than expected and require additional resources. Which project document should the risk manager analyze to reduce the risk that the project continues to exceed its cost and schedule?', 'انخفاض مؤشري أداء التكلفة والجدول الزمني يدل على استمرار تجاوز التكلفة والتأخر عن الجدول الزمني. وبما أن الأنشطة تستغرق وقتًا أطول من المتوقع وتحتاج إلى موارد أكثر من المتوقع، فيجب مراجعة الافتراضات التي بُنيت عليها تقديرات مدة الأنشطة وإنتاجية الموارد وتوافرها وقدرتها. يساعد ذلك على اكتشاف الافتراضات غير الواقعية ومعالجة أسباب الانحراف قبل حدوث مزيد من التجاوزات.', 'A decline in both the cost performance index and the schedule performance index indicates continuing cost overruns and schedule slippage. Since activities are taking longer than expected and require more resources than planned, the assumptions on which the activity duration estimates and the resource productivity, availability, and capacity were based must be reviewed. This helps to uncover unrealistic assumptions and address the causes of the variance before further overruns occur.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'هيكل تجزئة العمل (WBS).', 'Work breakdown structure (WBS).', false),
      (1, 'احتياطيات الطوارئ.', 'Contingency reserves.', false),
      (2, 'مصفوفة تأثير المخاطر.', 'Risk impact matrix.', false),
      (3, 'افتراضات الجدول الزمني والموارد.', 'Schedule and resource assumptions.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 7, id FROM question;

-- 9
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تستعد شركة تكنولوجيا متعددة الجنسيات لإطلاق منتج يعتمد على الذكاء الاصطناعي في الأسواق العالمية، وتتضمن المبادرة تطويرًا معقدًا للمنتج، ومتطلبات تنظيمية صارمة في دول مختلفة، واهتمامًا كبيرًا من المعنيين، بالإضافة إلى استثمارات ضخمة. وقد تم تكليف مدير المخاطر بوضع مؤشرات لمتابعة مستوى التعرض للمخاطر. ما المقياسان اللذان ينبغي على مدير المخاطر أخذهما في الاعتبار؟ (اختر إجابتين)', 'A multinational technology company is preparing to launch an artificial intelligence (AI)-based product in global markets. The initiative involves complex product development, strict regulatory requirements in different countries, high stakeholder interest, and substantial investment. The risk manager has been assigned to establish indicators for monitoring the level of risk exposure. Which two metrics should the risk manager consider? (Choose two)', 'معدل تكرار حدوث الخطر بمرور الوقت مؤشر مباشر على التعرض للمخاطر؛ فكلما زادت وتيرة حدوث المخاطر زاد مستوى التعرض. ويساعد المقياس على اكتشاف اتجاهات المخاطر ومعرفة ما إذا كانت تتزايد أو تتناقص. أما النسبة المئوية لإجراءات الاستجابة التي أُنجزت في موعدها فتقيس مدى فاعلية تنفيذ خطط الاستجابة؛ وتأخرها قد يترك المشروع معرضًا للمخاطر مدة أطول.', 'The frequency of risk occurrence over time is a direct indicator of risk exposure; the more frequently risks occur, the higher the level of exposure. This metric helps to detect risk trends and determine whether exposure is increasing or decreasing. The percentage of response actions completed on time measures how effectively response plans are being implemented; delays in these actions can leave the project exposed to risk for a longer period.', 2)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'معدل تكرار حدوث الخطر بمرور الوقت.', 'The frequency of risk occurrence over time.', true),
      (1, 'النسبة المئوية لإجراءات الاستجابة للمخاطر التي تم إنجازها في موعدها.', 'The percentage of risk response actions completed on time.', true),
      (2, 'النسبة المئوية للمخاطر التي تم تصعيدها إلى الإدارة التنفيذية.', 'The percentage of risks escalated to executive management.', false),
      (3, 'عدد جلسات إدارة المخاطر التي تم عقدها.', 'The number of risk management sessions held.', false),
      (4, 'عدد مخاطر المشروع المسجلة خلال فترة التنفيذ.', 'The number of project risks logged during the execution period.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 8, id FROM question;

-- 10
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تقوم شركة متعددة الجنسيات بمشروع تحول رقمي واسع النطاق في قطاعاتها المختلفة. أثناء مراجعة بيانات القياس التي تم الحصول عليها من أنظمة تكنولوجيا المعلومات، لاحظ مدير المخاطر اختلاف معدلات استخدام النظام ومؤشرات الأداء بين المناطق. كما أظهرت التسجيلات النصية الصوتية لاجتماعات الفرق وجود مخاوف تتعلق بالالتزام باللوائح المحلية وتحديات البنية التحتية لتكنولوجيا المعلومات. ما الذي يجب على مدير المخاطر فعله؟', 'A multinational company is undertaking a large-scale digital transformation project across its various business units. While reviewing measurement data obtained from the IT systems, the risk manager noticed that system usage rates and performance indicators differ between regions. Transcripts of team meetings also revealed concerns about compliance with local regulations and IT infrastructure challenges. What should the risk manager do?', 'توضح بيانات أنظمة تكنولوجيا المعلومات وجود اختلاف في معدلات استخدام النظام ومستويات الأداء بين المناطق، كما تكشف تسجيلات الاجتماعات عن مخاوف تتعلق باللوائح والبنية التحتية. لذلك ينبغي تحليل الاتجاهات في المناطق ذات معدلات الاستخدام المنخفضة لمعرفة ما إذا كان الاستخدام يتحسن أو يتراجع، وما إذا كانت مشكلات البنية التحتية أو المتطلبات المحلية تؤثر في أداء النظام، وما إذا كانت المخاطر تنتقل إلى مناطق أخرى أو تستدعي تحديث الاستجابات.', 'The IT system data shows differences in system usage rates and performance levels between regions, and the meeting transcripts reveal concerns about regulations and infrastructure. The risk manager should therefore analyze trends in the regions with low usage rates to determine whether usage is improving or declining, whether infrastructure issues or local requirements are affecting system performance, and whether risks are spreading to other regions or require the responses to be updated.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'توحيد مقاييس استخدام النظام في جميع قطاعات الشركة.', 'Standardize the system usage metrics across all of the company''s business units.', false),
      (1, 'تطبيق استراتيجية واحدة للالتزام باللوائح في جميع قطاعات الشركة.', 'Apply a single regulatory compliance strategy across all of the company''s business units.', false),
      (2, 'التأكد من اتساق المتطلبات التنظيمية في جميع المناطق.', 'Ensure that regulatory requirements are consistent across all regions.', false),
      (3, 'تحليل الاتجاهات في المناطق التي لديها أقل معدلات استخدام للنظام.', 'Analyze trends in the regions with the lowest system usage rates.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 9, id FROM question;

-- 11
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يواجه مشروع إنشائي عدة تأخيرات. يحتاج مدير المخاطر إلى تحديد التأثير المتوقع لهذه التأخيرات على الجدول الزمني العام باستخدام البيانات التاريخية من مشروعات مشابهة والتوقعات الجديدة. ما الأسلوب الذي يجب على مدير المخاطر استخدامه؟', 'A construction project is facing several delays. The risk manager needs to determine the expected impact of these delays on the overall schedule, using historical data from similar projects and new forecasts. Which technique should the risk manager use?', 'يستخدم تحليل PERT ثلاثة تقديرات للمدة: المتفائلة (O)، والأكثر احتمالًا (M)، والمتشائمة (P). وتُحسب المدة المتوقعة بالصيغة: (O + 4M + P) ÷ 6. تساعد البيانات التاريخية والتوقعات الجديدة على إعداد تقديرات واقعية لمدة المشروع.', 'PERT analysis uses three duration estimates: optimistic (O), most likely (M), and pessimistic (P). The expected duration is calculated using the formula (O + 4M + P) ÷ 6. Historical data and new forecasts help to prepare realistic estimates of the project duration.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل شجرة الأعطال لتتبع التأخيرات والرجوع إلى أسبابها.', 'Fault tree analysis to trace the delays back to their causes.', false),
      (1, 'تحليل شجرة القرار لتقييم السيناريوهات المحتملة.', 'Decision tree analysis to evaluate possible scenarios.', false),
      (2, 'مخطط عظمة السمكة لعرض الأسباب الجذرية المحتملة بصريًا.', 'Fishbone diagram to visually display potential root causes.', false),
      (3, 'تحليل PERT لتقدير مدة المشروع.', 'PERT analysis to estimate the project duration.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 10, id FROM question;

-- 12
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'كجزء من مشروع قادم، يعمل مدير المخاطر مع فريق المشروع لتحديد المخاطر المحتملة. وبعد ذلك، يريد مدير المخاطر تحديد كيفية استجابة فريق المشروع للمخاطر التي تم تحديدها. لكن إدارة الشركة تطلب معلومات إضافية عن الموارد المطلوبة لتنفيذ الاستجابات والحفاظ على سير المشروع وفقًا للخطة. ما الذي يجب على مدير المخاطر فعله لتلبية طلب الإدارة؟', 'As part of an upcoming project, the risk manager is working with the project team to identify potential risks. Next, the risk manager wants to determine how the project team will respond to the identified risks. However, company management is requesting additional information about the resources required to implement the responses and keep the project on plan. What should the risk manager do to satisfy management''s request?', 'تريد الإدارة معلومات إضافية عن الموارد اللازمة للاستجابة للمخاطر. ينبغي إعداد استراتيجية استجابة مناسبة بالاستفادة من أصول عمليات المؤسسة، مثل الدروس المستفادة وسجلات المخاطر السابقة ونماذج الاستجابة وبيانات الموارد والتكلفة، إلى جانب مدخلات فريق المشروع والخبراء. ثم توضح الاستراتيجية الموارد المطلوبة والمسؤولين والتكلفة المتوقعة وتوقيت التنفيذ والمحفزات وخطط الطوارئ.', 'Management wants additional information about the resources needed to respond to the risks. An appropriate response strategy should be prepared by drawing on organizational process assets, such as lessons learned, previous risk registers, response templates, and resource and cost data, together with input from the project team and subject matter experts. The strategy then sets out the required resources, the responsible owners, the expected cost, the timing of implementation, the triggers, and the contingency plans.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'نقل جميع المخاطر عالية التأثير إلى إدارات داخل الشركة للاستفادة من الموارد الموجودة.', 'Transfer all high-impact risks to departments within the company to take advantage of existing resources.', false),
      (1, 'قبول جميع المخاطر منخفضة التأثير للحفاظ على موارد الاستجابة للمخاطر الأعلى أولوية.', 'Accept all low-impact risks to preserve response resources for higher-priority risks.', false),
      (2, 'تخفيف جميع المخاطر عالية التأثير لضمان استمرار المشروع وفقًا للخطة.', 'Mitigate all high-impact risks to ensure the project continues according to plan.', false),
      (3, 'وضع استراتيجية للاستجابة بناءً على أصول عمليات المؤسسة ومدخلات الفريق.', 'Develop a response strategy based on organizational process assets and team input.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 11, id FROM question;

-- 13
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء ورشة لتقييم المخاطر في مشروع هندسي، حدد الفريق عدة مخاطر محتملة قد تؤثر على الجدول الزمني وتكاليف المشروع. ما الذي يجب على فريق إدارة المخاطر فعله؟', 'During a risk assessment workshop for an engineering project, the team identified several potential risks that could affect the project schedule and costs. What should the risk management team do?', 'حدد الفريق مخاطر محتملة، لكنه لم يحللها أو يرتب أولوياتها بعد. الخطوة التالية هي إجراء التحليل النوعي للمخاطر لتقييم احتمالية وقوع كل خطر وتأثيره المحتمل على أهداف المشروع ودرجة إلحاحه وأولويته. يساعد ذلك على توجيه الوقت والميزانية والموارد إلى المخاطر الأكثر أهمية.', 'The team has identified potential risks but has not yet analyzed or prioritized them. The next step is to perform qualitative risk analysis to assess the probability of each risk occurring, its potential impact on project objectives, its urgency, and its priority. This helps to direct time, budget, and resources toward the most significant risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديث سجل المخاطر ليشمل المخاطر المحددة وإجراءات التخفيف.', 'Update the risk register to include the identified risks and mitigation actions.', false),
      (1, 'وضع استراتيجيات للاستجابة بهدف معالجة المخاطر ذات الأولوية العالية بفعالية.', 'Develop response strategies to address the high-priority risks effectively.', false),
      (2, 'مراقبة المخاطر والتحكم فيها لمتابعة التقدم المستمر في إجراءات التخفيف بفعالية.', 'Monitor and control the risks to effectively track ongoing progress on the mitigation actions.', false),
      (3, 'إجراء تحليل نوعي للمخاطر لتقييم احتمالية وتأثير كل خطر.', 'Perform qualitative risk analysis to assess the probability and impact of each risk.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 12, id FROM question;

-- 14
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يوجد مشروع مؤسسي بارز في مرحلته النهائية. أكمل مدير المخاطر تقييمًا شاملًا للمخاطر وعمل مع مالكي المخاطر لتنفيذ استراتيجيات الاستجابة الخاصة بالمشروع. ما الذي ينبغي على مدير المخاطر فعله بعد ذلك؟', 'A high-profile enterprise project is in its final phase. The risk manager has completed a comprehensive risk assessment and has worked with the risk owners to implement the project''s response strategies. What should the risk manager do NEXT?', 'بعد تنفيذ استجابات المخاطر، ينتقل مدير المخاطر إلى مراقبة المخاطر وقياس مدى فاعلية الاستجابات. لذلك يجب التنسيق مع مالكي المخاطر للحصول على أحدث المعلومات عن المخاطر المعينة لهم، ثم تحديث حالتها في سجل المخاطر.', 'After the risk responses have been implemented, the risk manager moves on to monitoring the risks and measuring the effectiveness of the responses. The risk manager must therefore coordinate with the risk owners to obtain the latest information on the risks assigned to them, and then update their status in the risk register.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديث الجدول الزمني للمشروع وفقًا للمخاطر المتوقعة والمخاطر التي تحققت.', 'Update the project schedule to reflect the forecasted risks and the risks that have materialized.', false),
      (1, 'التنسيق مع مالكي المخاطر وتحديث خطة إدارة المشروع.', 'Coordinate with the risk owners and update the project management plan.', false),
      (2, 'تحديث سجل المخاطر ومشاركة الحالة مع المعنيين.', 'Update the risk register and share the status with stakeholders.', false),
      (3, 'التنسيق مع مالكي المخاطر لتحديث حالة المخاطر في سجل المخاطر.', 'Coordinate with the risk owners to update the status of the risks in the risk register.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 13, id FROM question;

-- 15
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'نجح فريق المشروع في تنفيذ خطة الاستجابة لحدث خطر رئيسي. وتم تقييم المخاطر المتبقية، واتُخذت الإجراءات اللازمة لإبقائها تحت السيطرة. ولم تنتج أي مخاطر ثانوية بعد تنفيذ الاستجابة. ما الذي ينبغي على مدير المخاطر فعله؟', 'The project team has successfully implemented the response plan for a major risk event. The residual risks have been assessed, and the necessary actions have been taken to keep them under control. No secondary risks arose after the response was implemented. What should the risk manager do?', 'تم تنفيذ الاستجابة بنجاح، وأصبحت المخاطر المتبقية تحت السيطرة، ولم تظهر مخاطر ثانوية. لذلك لم يعد الخطر الأصلي بحاجة إلى متابعة نشطة؛ ويجب إغلاقه رسميًا وتحديث سجل المخاطر ووثائق المشروع ذات الصلة، بما فيها سجل الدروس المستفادة.', 'The response was implemented successfully, the residual risks are under control, and no secondary risks have emerged. The original risk therefore no longer requires active follow-up; it should be formally closed, and the risk register and the relevant project documents, including the lessons learned register, should be updated.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إغلاق الخطر المنتهي وتحديث وثائق المشروع ذات الصلة.', 'Close the completed risk and update the relevant project documents.', true),
      (1, 'الاستمرار في مراقبة خطة الاستجابة الحرجة الخاصة بالمنتج الذي تم تسليمه.', 'Continue monitoring the critical response plan for the deliverable that was handed over.', false),
      (2, 'دراسة سجلات التغيير لتنفيذ طلبات التغيير المعتمدة.', 'Review the change logs to implement the approved change requests.', false),
      (3, 'الحصول على موافقة المعنيين قبل توثيق الدروس المستفادة.', 'Obtain stakeholder approval before documenting lessons learned.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 14, id FROM question;

-- 16
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أعلن راعي المشروع عن الحاجة إلى تغيير متطلبات المواصفات، ويرغب قائد المشروع في تنفيذ هذا التغيير. ما الذي ينبغي على مالك الخطر أن ينصح قائد المشروع بفعله أولًا؟', 'The project sponsor has announced the need to change the specification requirements, and the project leader wants to implement this change. What should the risk owner advise the project leader to do FIRST?', 'قبل تنفيذ التغيير المقترح في المواصفات، يجب تقييم تأثيره المحتمل على المشروع. لذلك ينبغي تحديد جميع التهديدات والفرص التي قد تنتج عن التغيير، ثم تحليلها وتوثيقها والتخطيط للتعامل معها قبل استكمال إجراءات التغيير الرسمية.', 'Before the proposed change to the specifications is implemented, its potential impact on the project must be assessed. All threats and opportunities that could result from the change should therefore be identified, and then analyzed, documented, and planned for before the formal change procedures are completed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديد الافتراضات المرتبطة بالتغيير.', 'Identify the assumptions associated with the change.', false),
      (1, 'التوصية بالإبقاء على متطلبات المواصفات السابقة.', 'Recommend keeping the previous specification requirements.', false),
      (2, 'إشراك المعنيين بالمشروع لمقاومة الإعلان عن التغيير.', 'Engage the project stakeholders to resist the announced change.', false),
      (3, 'تحديد التهديدات والفرص المحتملة الناتجة عن التغيير.', 'Identify the potential threats and opportunities resulting from the change.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 15, id FROM question;

-- 17
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء مراجعة وثائق التخطيط لمشروع بنية تحتية، اكتشف مدير المخاطر وجود عدم توافق في اعتماديات الأنشطة وتسلسلها. تسببت هذه المشكلات في تأخير معلم رئيسي مهم، وقد تؤدي إلى مزيد من الاضطرابات في الجدول الزمني. كما تؤثر قيود الموارد المشتركة مع مشروع آخر على ترتيب أولويات الأنشطة. ما الذي يجب على مدير المخاطر فعله؟', 'While reviewing the planning documents for an infrastructure project, the risk manager discovered inconsistencies in the activity dependencies and sequencing. These issues have caused a delay to a key milestone and could lead to further schedule disruptions. Constraints on resources shared with another project are also affecting the prioritization of activities. What should the risk manager do?', 'تكمن المشكلة في عدم توافق اعتماديات الأنشطة وتسلسلها، وقد أدى ذلك بالفعل إلى تأخير معلم رئيسي مهم. يساعد تحليل المسار الحرج على تحديد الأنشطة التي تتحكم مباشرة في تاريخ انتهاء المشروع، والاعتماديات غير المرتبة بطريقة صحيحة، والأنشطة التي لا تمتلك مرونة زمنية كافية، وتأثير قيود الموارد المشتركة على الأنشطة الحرجة.', 'The problem lies in the inconsistent activity dependencies and sequencing, which have already delayed a key milestone. Critical path analysis helps to identify the activities that directly control the project finish date, the dependencies that are not sequenced correctly, the activities that lack sufficient schedule flexibility (float), and the effect of the shared resource constraints on the critical activities.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تقييم الموارد المشتركة لحل التعارضات بين الأنشطة وتقليل التأثير على الجدول الزمني.', 'Assess the shared resources to resolve conflicts between activities and reduce the impact on the schedule.', false),
      (1, 'التحقق من صحة افتراضات الجدول الزمني عن طريق مقارنة المدد المخططة بالمدد الفعلية.', 'Validate the schedule assumptions by comparing planned durations with actual durations.', false),
      (2, 'تحليل المسار الحرج لمعالجة اعتماديات الأنشطة غير المتوافقة ومنع التأخيرات.', 'Analyze the critical path to address the inconsistent activity dependencies and prevent delays.', true),
      (3, 'تحسين تسلسل الأنشطة ليتوافق بصورة أفضل مع المعالم الرئيسية المهمة ومنع التأخيرات.', 'Improve the activity sequencing to better align with the key milestones and prevent delays.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 16, id FROM question;

-- 18
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يستخدم مشروع لتطوير البرمجيات إطار عمل رشيقًا لتحسين قدرته على التسليم. ولاحظ الفريق مؤخرًا تزايد عدد عيوب التطبيق التي لم تتم معالجتها. وقد تؤثر هذه العيوب في أداء التطبيق خلال التكرار القادم، مما قد يؤدي إلى عدم الالتزام بمواعيد تسليم الخصائص الرئيسية. كيف يجب على مدير المخاطر تقييم مستوى الخطر؟', 'A software development project is using an agile framework to improve its delivery capability. The team has recently noticed an increasing number of unresolved application defects. These defects could affect the application''s performance during the upcoming iteration, which could result in missed delivery dates for key features. How should the risk manager assess the level of risk?', 'يحتاج مدير المخاطر إلى تقييم ما إذا كان تزايد عدد العيوب غير المحلولة يؤدي إلى زيادة التعرض لمشكلات الأداء وتأخير التسليم. يساعد تحليل الاتجاهات على تقييم عدد العيوب المتراكمة ومعدل اكتشاف العيوب الجديدة ومعدل معالجة العيوب والتغير في شدتها وتأثيرها في سرعة الفريق ومواعيد تسليم الخصائص.', 'The risk manager needs to assess whether the growing number of unresolved defects is increasing the exposure to performance problems and delivery delays. Trend analysis helps to evaluate the size of the defect backlog, the rate at which new defects are discovered, the rate at which defects are resolved, changes in their severity, and their effect on the team''s velocity and the feature delivery dates.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التوصية بتقليل النطاق وحذف الخصائص التي تعتمد على الأجزاء التي تحتوي على عيوب.', 'Recommend reducing the scope and removing the features that depend on the defective components.', false),
      (1, 'إسناد العيوب إلى مالكي المنتج وترك إطار العمل الرشيق يعالجها دون تحليل إضافي.', 'Assign the defects to the product owners and let the agile framework handle them without further analysis.', false),
      (2, 'زيادة تكرار اجتماعات التنسيق اليومية لتحسين التواصل وتقليل شدة الخطر.', 'Increase the frequency of the daily coordination meetings to improve communication and reduce the severity of the risk.', false),
      (3, 'إجراء تحليل لاتجاهات العيوب وربطها بسرعة الفريق ومواعيد التسليم.', 'Perform a trend analysis of the defects and correlate it with the team''s velocity and the delivery dates.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 17, id FROM question;

-- 19
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تعمل شركة مقاولات في مشروع لتوسعة طريق سريع. يريد مدير المخاطر استخدام البيانات الجديدة والتاريخية لتقدير التأثير المحتمل للمخاطر المتوقعة على الجدول الزمني وميزانية المشروع. يواجه فريق المشروع تقلبات في أسعار مواد البناء وظروفًا جوية غير متوقعة، وقد أثرت هذه العوامل سابقًا على الجداول الزمنية للمشروعات. وتمتلك الشركة سجلات لمشروعات سابقة واجهت مخاطر مشابهة. ما الإجراء الذي يجب على مدير المخاطر اتخاذه؟', 'A contracting company is working on a highway expansion project. The risk manager wants to use new and historical data to estimate the potential impact of the anticipated risks on the project schedule and budget. The project team is facing fluctuations in construction material prices and unexpected weather conditions, and these factors have previously affected project schedules. The company holds records of past projects that faced similar risks. What action should the risk manager take?', 'يريد مدير المخاطر قياس تأثير عوامل غير مؤكدة، مثل تغير أسعار مواد البناء والظروف الجوية، على مدة المشروع وميزانيته. تعد محاكاة مونت كارلو من أدوات التحليل الكمي للمخاطر، حيث تستخدم البيانات التاريخية والحالية لإعداد توزيعات احتمالية وتشغيل آلاف السيناريوهات المحتملة، ثم تقدير نطاق النتائج المحتملة بدلًا من الاعتماد على تقدير واحد ثابت.', 'The risk manager wants to measure the effect of uncertain factors, such as changes in construction material prices and weather conditions, on the project''s duration and budget. Monte Carlo simulation is a quantitative risk analysis tool that uses historical and current data to build probability distributions and run thousands of possible scenarios, and then estimates the range of possible outcomes instead of relying on a single fixed estimate.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'استخدام محاكاة مونت كارلو لتحليل النتائج المحتملة للمشروع.', 'Use Monte Carlo simulation to analyze the possible project outcomes.', true),
      (1, 'إعداد هيكل تجزئة المخاطر لإجراء مزيد من التحليل النوعي.', 'Prepare a risk breakdown structure (RBS) to perform further qualitative analysis.', false),
      (2, 'مراجعة المعايير المرجعية للصناعة لوضع استراتيجية استجابة موحدة.', 'Review industry benchmarks to develop a standardized response strategy.', false),
      (3, 'إجراء تحليل نوعي للمخاطر لترتيب المخاطر وفقًا للاحتمالية والتأثير.', 'Perform qualitative risk analysis to rank the risks by probability and impact.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 18, id FROM question;

-- 20
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مدير المخاطر في مشروع كبير لإنشاء مبنى تجاري بجمع وتحليل بيانات الأداء من عدة فرق تابعة لمقاولي الباطن. أظهرت عدة فرق تأخيرات في تنفيذ الأعمال الإنشائية. وبدأت هذه التأخيرات تؤثر على الجدول الزمني العام للمشروع. ما الذي يجب على مدير المخاطر فعله؟', 'The risk manager of a large commercial building construction project is collecting and analyzing performance data from several subcontractor teams. Several teams have shown delays in executing the construction work, and these delays have begun to affect the overall project schedule. What should the risk manager do?', 'المشروع يواجه بالفعل مشكلة محددة: عدة فرق من مقاولي الباطن تتأخر في تنفيذ الأعمال الإنشائية، وهذا التأخير يؤثر على الجدول الزمني العام. لذلك يجب إجراء تحليل السبب الجذري لمعرفة الأسباب الحقيقية وراء التأخيرات، مثل نقص العمالة أو مواد البناء، أو ضعف التنسيق بين مقاولي الباطن، أو وجود أخطاء في الرسومات أو المتطلبات الفنية، أو تأخر الاعتمادات أو عمليات التفتيش، أو ضعف الإنتاجية أو توزيع الموارد بطريقة غير مناسبة.', 'The project is already facing a specific problem: several subcontractor teams are behind in executing the construction work, and this delay is affecting the overall schedule. Root cause analysis should therefore be performed to determine the real causes behind the delays, such as shortages of labor or construction materials, poor coordination among subcontractors, errors in drawings or technical requirements, delayed approvals or inspections, low productivity, or inappropriate allocation of resources.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إجراء تحليل السبب الجذري.', 'Perform root cause analysis.', true),
      (1, 'إجراء تحليل مونت كارلو.', 'Perform Monte Carlo analysis.', false),
      (2, 'إجراء تحليل الاتجاهات.', 'Perform trend analysis.', false),
      (3, 'إجراء تحليل الانحرافات.', 'Perform variance analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 19, id FROM question;

-- 21
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقترب مشروع لتطوير برنامج في مؤسسة مالية من مراجعة منتصف المشروع. يضم المشروع عددًا من المعنيين، من بينهم الإدارة التنفيذية وأعضاء الفريق والجهات الحكومية والعملاء الرئيسيون. وتختلف خبراتهم ومدى اهتمامهم بالتفاصيل المتعلقة بالمخاطر. طلب راعي المشروع من مدير المخاطر إعداد تقرير عن حالة المخاطر لمراجعة منتصف المشروع. ما الذي يجب على مدير المخاطر فعله؟', 'A software development project at a financial institution is approaching its mid-project review. The project involves a number of stakeholders, including executive management, team members, government agencies, and key customers, whose expertise and interest in risk-related detail vary. The project sponsor has asked the risk manager to prepare a risk status report for the mid-project review. What should the risk manager do?', 'تضم بيئة المشروع مجموعات مختلفة من المعنيين، ولكل مجموعة مستوى مختلف من السلطة والخبرة والاهتمام والاحتياجات المعلوماتية. لذلك يجب تخصيص تقرير المخاطر بما يناسب كل مجموعة؛ فالإدارة التنفيذية تحتاج إلى ملخص عن المخاطر الرئيسية والتعرض العام، بينما يحتاج أعضاء الفريق إلى تفاصيل المحفزات وإجراءات الاستجابة والمسؤوليات.', 'The project environment includes different stakeholder groups, each with a different level of authority, expertise, interest, and information needs. The risk report must therefore be tailored to suit each group: executive management needs a summary of the key risks and the overall exposure, while team members need details of the triggers, response actions, and responsibilities.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إعداد تقرير تفصيلي للحفاظ على الاتساق بين جميع المعنيين.', 'Prepare a detailed report to maintain consistency across all stakeholders.', false),
      (1, 'تخصيص مستوى التفاصيل ومحتوى التقرير وفقًا لاحتياجات المعنيين.', 'Tailor the level of detail and the content of the report to the needs of the stakeholders.', true),
      (2, 'التركيز على المخاطر ذات الأولوية العالية وتقليل الاهتمام بالمخاطر المنخفضة لتبسيط التقرير.', 'Focus on the high-priority risks and give less attention to the low-priority risks to simplify the report.', false),
      (3, 'التعاون مع فريق المشروع للتأكد من إدراج جميع المخاطر في التقرير.', 'Collaborate with the project team to ensure that all risks are included in the report.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 20, id FROM question;

-- 22
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم تعيين مدير مخاطر في مشروع يهدف إلى توحيد تقنيات مؤسستين في مرحلة اندماج. لدى المعنيين من المؤسستين آراء مختلفة حول العوامل التي قد تؤثر على المشروع، مما يؤدي إلى إبطاء عملية تحديد المخاطر. ما الذي يجب على مدير المخاطر فعله لإعادة تركيز المعنيين على تحديد المخاطر؟', 'A risk manager has been appointed to a project that aims to unify the technologies of two organizations that are in the process of merging. Stakeholders from the two organizations hold different views about the factors that could affect the project, which is slowing down the risk identification process. What should the risk manager do to refocus the stakeholders on identifying risks?', 'لدى المعنيين من المؤسستين وجهات نظر مختلفة حول العوامل التي قد تؤثر على المشروع. لذلك يجب جمعهم في جلسة عصف ذهني منظمة لتوضيح افتراضات المشروع وقيوده وتوثيقها. تساعد الجلسة على مشاركة وجهات النظر المختلفة، وتكوين فهم مشترك لبيئة المشروع، وتحديد الافتراضات غير المؤكدة والقيود التي قد ينشأ عنها تهديد أو فرصة.', 'Stakeholders from the two organizations hold different perspectives on the factors that could affect the project. They should therefore be brought together in a structured brainstorming session to clarify and document the project''s assumptions and constraints. The session helps to share the different perspectives, build a common understanding of the project environment, and identify the uncertain assumptions and the constraints that could give rise to a threat or an opportunity.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إبلاغ الراعي التنفيذي للمشروع ومطالبته باستخدام نفوذه لتحقيق التوافق.', 'Inform the executive sponsor of the project and ask them to use their influence to achieve alignment.', false),
      (1, 'مطالبة مدير المشروع بالتفاوض مع مجموعتي المعنيين لتحقيق اتفاق بشأن التركيز على المخاطر.', 'Ask the project manager to negotiate with the two stakeholder groups to reach agreement on which risks to focus on.', false),
      (2, 'عقد جلسة عصف ذهني مع جميع المعنيين لتحديد الافتراضات والقيود وتوثيقها.', 'Hold a brainstorming session with all stakeholders to identify and document the assumptions and constraints.', true),
      (3, 'تحديد اجتماع متكرر مع جميع المعنيين لمراجعة سجل المخاطر وإجراء التعديلات عند الحاجة.', 'Schedule a recurring meeting with all stakeholders to review the risk register and make adjustments when needed.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 21, id FROM question;

-- 23
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء تطوير مشروع إنشائي كبير، حدد مدير المخاطر خطرًا متعلقًا بالظروف الجوية القاسية التي قد تؤدي إلى تأخير أعمال الحفر. قام الفريق بتخفيف هذا الخطر من خلال إنشاء غطاء مؤقت مقاوم للعوامل الجوية فوق موقع الحفر. أثناء التنفيذ، انهار الغطاء المؤقت بسبب رياح شديدة غير متوقعة، مما تسبب في تلف معدات البناء. ما الخطر الثانوي في هذا السيناريو؟', 'During the development of a large construction project, the risk manager identified a risk related to severe weather conditions that could delay the excavation work. The team mitigated this risk by erecting a temporary weather-resistant cover over the excavation site. During execution, the temporary cover collapsed because of unexpectedly strong winds, causing damage to construction equipment. What is the secondary risk in this scenario?', 'الخطر الثانوي هو خطر جديد ينشأ كنتيجة مباشرة لتنفيذ استجابة لخطر آخر. الخطر الأصلي هو تأخير الحفر بسبب الطقس القاسي، والاستجابة هي إنشاء الغطاء المؤقت. أما احتمال انهيار هذا الغطاء بسبب الرياح الشديدة فهو الخطر الثانوي؛ وتلف معدات البناء أثر لهذا الخطر.', 'A secondary risk is a new risk that arises as a direct result of implementing a response to another risk. The original risk is the delay to excavation caused by severe weather, and the response is the erection of the temporary cover. The possibility that this cover collapses because of strong winds is the secondary risk; the damage to the construction equipment is an impact of that risk.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'الظروف الجوية القاسية التي تؤدي إلى تأخير أعمال الحفر.', 'The severe weather conditions that delay the excavation work.', false),
      (1, 'انهيار الغطاء المؤقت بسبب الرياح الشديدة غير المتوقعة.', 'The collapse of the temporary cover because of the unexpectedly strong winds.', true),
      (2, 'قرار إنشاء غطاء مؤقت فوق موقع الحفر.', 'The decision to erect a temporary cover over the excavation site.', false),
      (3, 'تلف معدات البناء الناتج عن انهيار الغطاء.', 'The damage to the construction equipment caused by the collapse of the cover.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
