-- 24
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مدير المخاطر بإعداد استراتيجية لإدارة المخاطر لخط إنتاج جديد في شركة تصنيع. يشارك في المشروع فرق من تخصصات مختلفة، كما توجد ارتباطات واعتماديات مع سلسلة التوريد. أكدت الإدارة العليا ضرورة وضع مقاييس فعالة للمخاطر لدعم التواصل عن المخاطر ومراقبتها. ما الخطوتان اللتان يجب على مدير المخاطر اتخاذهما؟ (اختر إجابتين)', 'A risk manager is preparing a risk management strategy for a new production line at a manufacturing company. Teams from different disciplines are involved in the project, and there are linkages and dependencies with the supply chain. Senior management has emphasized the need to establish effective risk metrics to support risk communication and monitoring. Which two steps should the risk manager take? (Choose two)', 'لكي تدعم مقاييس المخاطر اتخاذ القرارات داخل المؤسسة والتواصل الفعال مع المعنيين، يجب مواءمتها مع أهداف المؤسسة ومؤشرات الأداء الرئيسية، وإشراك المعنيين الرئيسيين في تحديد حدود المخاطر ومستويات تحملها. تساعد المواءمة على ربط المخاطر بأهداف الأعمال، ويساعد إشراك المعنيين على الاتفاق على مستويات التعرض المقبولة وحدود التصعيد.', 'For risk metrics to support decision-making within the organization and effective communication with stakeholders, they must be aligned with the organization''s objectives and key performance indicators, and key stakeholders must be involved in defining the risk thresholds and tolerance levels. Alignment helps to connect risks to business objectives, and stakeholder involvement helps to reach agreement on acceptable exposure levels and escalation thresholds.', 2)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تطوير نماذج كمية للتنبؤ بمخاطر التصنيع المعتادة.', 'Develop quantitative models to forecast typical manufacturing risks.', false),
      (1, 'مواءمة مقاييس المخاطر مع أهداف المؤسسة ومؤشرات الأداء الرئيسية.', 'Align the risk metrics with the organization''s objectives and key performance indicators (KPIs).', true),
      (2, 'وضع مقاييس مخاطر التصنيع بعد الانتهاء من خطة الاستجابة للمخاطر.', 'Define the manufacturing risk metrics after the risk response plan has been completed.', false),
      (3, 'إشراك المعنيين الرئيسيين في تحديد حدود المخاطر ومستويات تحملها.', 'Involve key stakeholders in defining the risk thresholds and tolerance levels.', true),
      (4, 'الاستعانة بخبراء خارجيين لتحديد مقاييس المخاطر بهدف تجنب تحيز المعنيين.', 'Engage external experts to define the risk metrics in order to avoid stakeholder bias.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 23, id FROM question;

-- 25
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أكمل فريق المشروع أنشطة تخطيط الاستجابة للمخاطر وحدد ثلاث خطط استجابة مهمة لأحداث مخاطر رئيسية. تمت مراقبة الاستجابات وتنفيذها، وقد نتج عن إحدى هذه الاستجابات ظهور خطرين ثانويين. ما الذي يجب على مدير المخاطر فعله بعد ذلك؟', 'The project team has completed the risk response planning activities and has defined three important response plans for major risk events. The responses were monitored and implemented, and one of these responses resulted in the emergence of two secondary risks. What should the risk manager do NEXT?', 'بعد تنفيذ الاستجابات، ينبغي تقييم أثر المخاطر الثانوية التي نشأت عنها، وأي مخاطر متبقية بعد تنفيذ الاستجابات، على أهداف المشروع مثل التكلفة والجدول الزمني والنطاق والجودة. وبعد التقييم، تُوثق هذه المخاطر في سجل المخاطر وتُحدد أولوياتها وتُخطط استجابات إضافية عند الحاجة.', 'After the responses have been implemented, the impact on project objectives such as cost, schedule, scope, and quality should be assessed for the secondary risks that arose from them and for any risks that remain after the responses were implemented. After the assessment, these risks are documented in the risk register, prioritized, and additional responses are planned where needed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تقييم سجل المعنيين لتحديد تأثير المخاطر الأصلية.', 'Assess the stakeholder register to determine the impact of the original risks.', false),
      (1, 'تقييم تأثير المخاطر المتبقية والثانوية على أهداف المشروع.', 'Assess the impact of the residual and secondary risks on the project objectives.', true),
      (2, 'تقييم سجل التغييرات للتأكد من تنفيذ التغييرات.', 'Assess the change log to confirm that the changes have been implemented.', false),
      (3, 'تقييم سجل المخاطر للتأكد من أن المخاطر الثانوية واقعية.', 'Assess the risk register to confirm that the secondary risks are realistic.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 24, id FROM question;

-- 26
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء إعداد سجل مخاطر المشروع، لاحظ مدير المشروع أن الفريق لا يمتلك الخبرة الفنية اللازمة لتحديد المخاطر الخاصة بإحدى المهام بسبب طبيعتها الفنية المتخصصة. بماذا يجب على مدير المخاطر أن ينصح مدير المشروع عند تحديد مخاطر هذا الجزء من نطاق العمل؟', 'While preparing the project risk register, the project manager noticed that the team lacks the technical expertise needed to identify the risks of one task because of its highly specialized technical nature. What should the risk manager advise the project manager to do when identifying risks for this part of the scope of work?', 'لا يمتلك فريق المشروع المعرفة الفنية المتخصصة المطلوبة لتحديد مخاطر جزء معين من نطاق العمل. لذلك ينبغي الاستعانة بخبراء متخصصين داخليين يمتلكون المعرفة الفنية المطلوبة. يساعد حكم الخبراء على فهم العمل المتخصص واعتمادياته، وتحديد حالات الفشل المحتملة والأسباب والمحفزات والتأثيرات، وتقييم الاحتمالية والتأثير بدقة.', 'The project team does not have the specialized technical knowledge required to identify the risks of a particular part of the scope of work. Internal subject matter experts who possess the required technical knowledge should therefore be engaged. Expert judgment helps the team to understand the specialized work and its dependencies, identify potential failure modes, causes, triggers, and impacts, and assess probability and impact accurately.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'طلب الدعم من الخبراء المتخصصين الداخليين لتقديم حكم الخبراء في تحديد المخاطر.', 'Request support from internal subject matter experts to provide expert judgment in identifying the risks.', true),
      (1, 'الاستعانة بمقاول فرعي يمتلك الخبرة المناسبة لتيسير تحديد المخاطر وتحليلها.', 'Engage a subcontractor with the appropriate expertise to facilitate risk identification and analysis.', false),
      (2, 'مطالبة العميل بتخفيض مستوى الخبرة المطلوبة لتحديد المخاطر وتحليلها.', 'Ask the customer to lower the level of expertise required to identify and analyze the risks.', false),
      (3, 'إجراء جلسات عصف ذهني مع مدير المخاطر لإعداد قائمة بالمخاطر والتأثيرات المحتملة.', 'Hold brainstorming sessions with the risk manager to prepare a list of the risks and their potential impacts.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 25, id FROM question;

-- 27
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يدير فريق مشروع مشروعًا دوليًا يضم عددًا كبيرًا من المعنيين في عدة مناطق تختلف أولوياتهم. وخلال تقييم البيئة، حدد الفريق تأخر توافر الموارد باعتباره تهديدًا محتملًا، كما حدد التبني السريع للتقنيات الجديدة باعتباره فرصة. واختلف المعنيون حول إعطاء الأولوية للتعامل مع المخاطر العاجلة أو دراسة الفرص المحتملة، مما أدى إلى عدم وضوح الخطوة التالية. ما الذي يجب على مدير المخاطر فعله؟', 'A project team is managing an international project that involves a large number of stakeholders across several regions with differing priorities. During the environmental assessment, the team identified delayed resource availability as a potential threat and the rapid adoption of new technologies as an opportunity. The stakeholders disagreed on whether to prioritize addressing the urgent risks or examining the potential opportunities, leaving the next step unclear. What should the risk manager do?', 'يختلف المعنيون لأن لديهم أولويات إقليمية مختلفة، وقد ينظر كل طرف إلى التهديدات والفرص بطريقة مختلفة. لذلك ينبغي الاتفاق مع المشاركين الرئيسيين على معايير موضوعية لتقييم الجانبين، مثل احتمالية الحدوث، والتأثير في الأهداف، والإلحاح، والقيمة الاستراتيجية، والتكلفة والموارد المطلوبة، ومدى المواءمة مع شهية المنظمة للمخاطر وحدودها.', 'The stakeholders disagree because they have different regional priorities, and each party may view threats and opportunities differently. Objective criteria for evaluating both should therefore be agreed with the key participants, such as probability of occurrence, impact on objectives, urgency, strategic value, required cost and resources, and alignment with the organization''s risk appetite and thresholds.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إعطاء الأولوية للمنافع المحتملة مع دراسة الجدوى والقيمة بعناية.', 'Prioritize the potential benefits while carefully examining their feasibility and value.', false),
      (1, 'العمل مع المشاركين الرئيسيين لتحديد معايير تقييم التهديدات والمنافع.', 'Work with the key participants to define the criteria for evaluating threats and benefits.', true),
      (2, 'التركيز على معالجة التهديدات الفورية لتجنب تأخير الجدول الزمني للمشروع.', 'Focus on addressing the immediate threats to avoid delaying the project schedule.', false),
      (3, 'الاعتماد على البيانات التاريخية لإعداد منهج تقييم متسق مع المشروعات المشابهة.', 'Rely on historical data to prepare an assessment approach consistent with similar projects.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 26, id FROM question;

-- 28
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يتولى برنامج على مستوى المؤسسة تنفيذ تحول رقمي شامل، ويتضمن عدة مشروعات فرعية لكل منها مجموعة مختلفة من المخاطر. واستلم مدير المخاطر تقريرًا يوضح زيادة كبيرة في تهديدات الأمن السيبراني، والتي قد تؤثر في سلامة بيانات المنظمة بالكامل. وتشعر القيادة التنفيذية بالقلق، وتريد فهم كيفية تأثير هذه المخاطر في المؤسسة بصورة عامة. على ماذا يجب أن يركز مدير المخاطر لتوضيح التأثير المحتمل؟', 'An enterprise-level program is delivering a comprehensive digital transformation and includes several sub-projects, each with a different set of risks. The risk manager has received a report showing a significant increase in cybersecurity threats that could affect the integrity of the organization''s data as a whole. Executive leadership is concerned and wants to understand how these risks could affect the enterprise overall. What should the risk manager focus on to clarify the potential impact?', 'تريد القيادة التنفيذية فهم التعرض لمخاطر الأمن السيبراني على مستوى المؤسسة، وليس داخل كل مشروع فرعي بصورة منفصلة. لذلك ينبغي جمع معلومات المخاطر من جميع المشروعات الفرعية وتجميعها وتحليلها، بما في ذلك احتمالية وتأثير كل خطر، والاعتماديات المشتركة، والتأثيرات التراكمية والمتسلسلة المحتملة، والتعرض لفقدان البيانات أو تلفها أو الوصول غير المصرح إليها.', 'Executive leadership wants to understand the cybersecurity risk exposure at the enterprise level, not within each sub-project separately. Risk information should therefore be collected from all sub-projects, aggregated, and analyzed, including the probability and impact of each risk, the shared dependencies, the potential cumulative and cascading effects, and the exposure to data loss, data corruption, or unauthorized access.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل احتمالية كل خطر محدد في جميع المشروعات الفرعية وإعداد تقرير للقيادة التنفيذية.', 'Analyze the probability of each identified risk across all sub-projects and prepare a report for executive leadership.', true),
      (1, 'إعداد خطة استجابة تفصيلية لتخفيف كل تهديد من تهديدات الأمن السيبراني، وتقديم تقرير عنها.', 'Prepare a detailed response plan to mitigate each cybersecurity threat and report on it.', false),
      (2, 'تيسير ورشة عمل للمخاطر لإجراء عصف ذهني حول استراتيجيات التخفيف المحتملة مع قادة الفرق.', 'Facilitate a risk workshop to brainstorm potential mitigation strategies with the team leaders.', false),
      (3, 'مراجعة خطط إدارة المخاطر الخاصة بالمشروعات الفرعية للتحقق من توافقها مع أولويات المخاطر في الشركة.', 'Review the sub-projects'' risk management plans to verify their alignment with the company''s risk priorities.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 27, id FROM question;

-- 29
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال مرحلة التخطيط لمشروع تسويق دولي، تم تكليف مدير المخاطر بتحديد المخاطر التي قد يكون لها أكبر تأثير في ربحية المشروع. ويشمل المشروع عدة مناطق، لكل منها ظروف اقتصادية وسياسية مختلفة. ما الأداة التي يجب على مدير المخاطر استخدامها؟', 'During the planning phase of an international marketing project, the risk manager was assigned to identify the risks that could have the greatest impact on the project''s profitability. The project spans several regions, each with different economic and political conditions. Which tool should the risk manager use?', 'يحوّل أسلوب القيمة النقدية المتوقعة (EMV) احتمال كل خطر وتأثيره المالي إلى قيمة مالية متوقعة باستخدام العلاقة: القيمة النقدية المتوقعة = الاحتمالية × التأثير المالي. تكون القيمة عادةً سالبة للتهديدات وموجبة للفرص. يتيح ذلك مقارنة مخاطر المناطق المختلفة بمقياس مالي موحد وتحديد المخاطر ذات التأثير المتوقع الأكبر في الربحية.', 'The expected monetary value (EMV) technique converts the probability of each risk and its financial impact into an expected monetary value using the relationship EMV = probability × financial impact. The value is usually negative for threats and positive for opportunities. This allows the risks of different regions to be compared using a single financial measure and the risks with the greatest expected impact on profitability to be identified.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل شجرة القرار.', 'Decision tree analysis.', false),
      (1, 'أسلوب القيمة النقدية المتوقعة.', 'Expected monetary value (EMV) technique.', true),
      (2, 'أسلوب دلفي.', 'Delphi technique.', false),
      (3, 'تحليل شجرة الأعطال.', 'Fault tree analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 28, id FROM question;

-- 30
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم إعداد محفزات مخاطر المشروع بناءً على مدخلات المعنيين الرئيسيين، الذين حددوا عدة مجالات رئيسية للقلق، من بينها الهندسة الجيوتقنية، والتقييمات الزلزالية، وتكنولوجيا المعلومات والأمن السيبراني. ويشمل نطاق العمل تقييم استقرار المنحدرات، والحفريات العميقة، والوصول عن بعد إلى أجهزة الكمبيوتر التي تتحكم في بوابات السدود، وهي أعمال ترتبط بالمجالات المحددة. ما المعلومات الإضافية التي يجب على مدير المخاطر جمعها لتحديد حدود المخاطر ومحفزاتها في المشروع؟', 'The project''s risk triggers were prepared based on input from key stakeholders, who identified several key areas of concern, including geotechnical engineering, seismic assessments, and information technology and cybersecurity. The scope of work includes slope stability assessment, deep excavations, and remote access to the computers that control the dam gates, all of which relate to the identified areas. What additional information should the risk manager gather to define the project''s risk thresholds and triggers?', 'حدد المعنيون المجالات الرئيسية للمخاطر وأنشطة العمل المرتبطة بها. ويحتاج مدير المخاطر إلى معايير قابلة للقياس تحدد متى يصبح الخطر مهمًا بما يكفي لتسجيله ومتابعته رسميًا، وكيف تُعرّف مستويات التعرض وتصنيفاتها، ومتى يجب على فريق المشروع اتخاذ إجراء، ومتى يتجاوز الخطر صلاحيات المشروع ويحتاج إلى التصعيد.', 'The stakeholders have identified the key risk areas and the work activities associated with them. The risk manager needs measurable criteria that define when a risk becomes significant enough to be formally logged and tracked, how exposure levels and their classifications are defined, when the project team must take action, and when a risk exceeds the project''s authority and needs to be escalated.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التقييمات النوعية والكمية لكل خطر والتي تُستخدم لتحديد المخاطر الأعلى أولوية وتأثيرًا.', 'The qualitative and quantitative assessments of each risk, which are used to identify the highest-priority and highest-impact risks.', false),
      (1, 'الحد الأدنى لمستوى التعرض للمخاطر الذي يستوجب إضافتها إلى سجل المخاطر، وتعريفات تصنيفات المخاطر، والحد الأقصى للتعرض قبل التصعيد.', 'The minimum level of risk exposure that requires a risk to be added to the risk register, the definitions of the risk classifications, and the maximum exposure before escalation.', true),
      (2, 'أسماء الأشخاص الذين تم تعيينهم كمالكين للمخاطر والمسؤولين عن مراقبتها والتحكم فيها والتأكد من تنفيذ خطط الاستجابة عند حدوث المحفزات.', 'The names of the people assigned as risk owners who are responsible for monitoring and controlling the risks and ensuring that the response plans are implemented when the triggers occur.', false),
      (3, 'تصنيف المخاطر لكل نوع من أنواع العمل، بما يشمل نطاق العمل والجدول الزمني والموارد المطلوبة.', 'The risk classification for each type of work, including the scope of work, the schedule, and the required resources.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
