-- 31
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تستعد إحدى شركات الطاقة لبدء مشروع جديد لإنشاء مزرعة للطاقة الشمسية، وستكون الأولى من نوعها في المنطقة. وسيصوت المشرعون المحليون خلال عدة أسابيع على الموافقة على المشروع أو رفضه. ويجمع مدير المشروع حاليًا عدة وثائق لعرضها على المشرعين في اجتماع قادم. لكن وثائق مخاطر المشروع ما زالت محدودة بسبب وجود المشروع في مراحله الأولى. وتم تكليف مدير المخاطر بتوفير وثائق تثبت أن الشركة قامت بالدراسة والعناية الواجبة. في ظل عدم وجود وثائق قوية للمشروع، ما الذي يجب على مدير المخاطر فعله لإعداد وثائق كافية للاجتماع القادم؟', 'An energy company is preparing to start a new project to build a solar farm, which will be the first of its kind in the region. Local legislators will vote within several weeks on whether to approve or reject the project. The project manager is currently assembling several documents to present to the legislators at an upcoming meeting. However, the project''s risk documentation is still limited because the project is in its early stages. The risk manager has been assigned to provide documentation demonstrating that the company has performed its due diligence. In the absence of robust project documents, what should the risk manager do to prepare adequate documentation for the upcoming meeting?', 'ما زال المشروع في مرحلة مبكرة، ولذلك لا تتوفر وثائق تفصيلية كافية عن المشروع ومخاطره. ولإثبات قيام الشركة بالعناية الواجبة، يجب على مدير المخاطر التعاون مع المعنيين والخبراء المناسبين لتحديد الافتراضات والقيود الحالية وتوثيقها. وقد تشمل افتراضات الموافقة التشريعية، وقيود استخدام الأرض والتصاريح، والمتطلبات البيئية والمجتمعية، وافتراضات الربط بشبكة الكهرباء، وافتراضات التكنولوجيا الشمسية ومستوى أدائها.', 'The project is still at an early stage, so sufficient detailed documentation about the project and its risks is not yet available. To demonstrate that the company has performed its due diligence, the risk manager must work with the appropriate stakeholders and experts to identify and document the current assumptions and constraints. These may include assumptions about legislative approval, land-use and permitting constraints, environmental and community requirements, grid connection assumptions, and assumptions about the solar technology and its performance level.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'دراسة خطة المشروع الحالية وتحديد ما إذا كان قد تم تخصيص وقت كافٍ للمرحلة النهائية في الجدول الزمني.', 'Study the current project plan and determine whether sufficient time has been allocated to the final phase in the schedule.', false),
      (1, 'التشاور مع المعنيين لتحديد الافتراضات والقيود وتوثيقها، حتى يتم تحويلها لاحقًا إلى وثائق للمشروع.', 'Consult with stakeholders to identify and document the assumptions and constraints so that they can later be converted into project documents.', true),
      (2, 'الرجوع إلى الأوراق والتقارير المتخصصة في صناعة مزارع الطاقة الشمسية لفهم التحديات التي واجهتها الشركات الأخرى في مشروعات سابقة.', 'Refer to specialized papers and reports on the solar farm industry to understand the challenges other companies have faced in previous projects.', false),
      (3, 'دراسة أصول عمليات المنظمة لمعرفة ما إذا كانت المشروعات السابقة قد التزمت داخل الميزانيات المخصصة.', 'Study the organizational process assets to determine whether previous projects stayed within their allocated budgets.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 30, id FROM question;

-- 32
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال مرحلة التخطيط لمشروع بنية تحتية ضخم، تم تكليف مدير المخاطر بتحديد الأشخاص الذين سيتولون التعامل مع مخاطر معينة مرتفعة التأثير. وقررت المنظمة استخدام مصفوفة توزيع المسؤوليات لتوضيح الأدوار المرتبطة باستجابات المخاطر. ويشمل المعنيون عدة إدارات تمتلك خبرات مختلفة. كيف يجب على مدير المخاطر توزيع المسؤوليات؟', 'During the planning phase of a major infrastructure project, the risk manager was assigned to identify the people who will handle specific high-impact risks. The organization has decided to use a responsibility assignment matrix (RAM) to clarify the roles associated with the risk responses. The stakeholders include several departments with different areas of expertise. How should the risk manager assign the responsibilities?', 'عند توزيع المسؤوليات عن المخاطر مرتفعة التأثير يجب مراعاة الخبرة الفنية والوظيفية، وصلاحية اتخاذ القرارات، والقدرة على التأثير في نتائج الخطر، وإمكانية الوصول إلى الموارد المطلوبة، والقدرة على مراقبة المحفزات وتنفيذ الاستجابات. توضح مصفوفة توزيع المسؤوليات الفرق بين مالك الخطر المسؤول عن إدارته ومراقبته، ومسؤول إجراء الاستجابة المكلف بتنفيذ إجراء محدد.', 'When assigning responsibility for high-impact risks, the following should be considered: technical and functional expertise, decision-making authority, the ability to influence the outcome of the risk, access to the required resources, and the ability to monitor triggers and implement responses. The responsibility assignment matrix clarifies the difference between the risk owner, who is responsible for managing and monitoring the risk, and the risk action owner, who is assigned to carry out a specific action.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تقييم خبرات المعنيين وتوزيع المسؤوليات بما يتوافق معها.', 'Assess the stakeholders'' expertise and assign responsibilities accordingly.', true),
      (1, 'تحديد اجتماع مشترك للمعنيين لاتخاذ القرار والتصويت على مسؤوليات المخاطر.', 'Schedule a joint meeting of the stakeholders to decide and vote on the risk responsibilities.', false),
      (2, 'استخدام أداة مصفوفة اتخاذ القرار لضمان توافق المسؤوليات مع ملفات المخاطر بفعالية.', 'Use a decision matrix tool to ensure that responsibilities are effectively aligned with the risk profiles.', false),
      (3, 'توزيع المخاطر على الإدارات الأقرب من حيث الموقع الجغرافي.', 'Assign the risks to the departments that are closest in terms of geographic location.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 31, id FROM question;

-- 33
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'طبقت إحدى شركات الخدمات المالية نظامًا جديدًا لإدارة المخاطر. وتم تكليف مدير المخاطر بالتأكد من توافق النظام الجديد مع معايير الالتزام التنظيمي، وتقييم محفزات المخاطر وحدودها بناءً على بيانات السوق المحدثة. ونظرًا لتقلب السوق، يشعر فريق المشروع بالقلق بشأن كيفية تسجيل هذه المخاطر المتغيرة وتوثيقها بفعالية لدعم اتخاذ القرار. ما الذي يجب على مدير المخاطر إعطاؤه الأولوية للحفاظ على الالتزام؟', 'A financial services company has implemented a new risk management system. The risk manager has been assigned to ensure that the new system complies with regulatory compliance standards and to assess the risk triggers and thresholds based on updated market data. Given the market volatility, the project team is concerned about how to effectively record and document these changing risks to support decision-making. What should the risk manager prioritize in order to maintain compliance?', 'يتسم السوق بالتقلب، ولذلك قد تتغير محفزات المخاطر وحدودها ومؤشراتها مع ظهور معلومات جديدة عن السوق والمتطلبات التنظيمية. وللحفاظ على الالتزام ودعم القرارات، يجب على مدير المخاطر مراجعة مؤشرات المخاطر المرتبطة وتوثيقها بصورة منتظمة، مع تحديث سجل المخاطر وتقارير المخاطر ووثائق المشروع ذات الصلة.', 'The market is volatile, so risk triggers, thresholds, and indicators may change as new information about the market and regulatory requirements emerges. To maintain compliance and support decisions, the risk manager must regularly review and document the related risk indicators, and update the risk register, the risk reports, and the relevant project documents.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تنفيذ استراتيجية تخفيف المخاطر الأقل تكلفة.', 'Implement the least costly risk mitigation strategy.', false),
      (1, 'مواءمة جميع أهداف المشروع مع بيان المخاطر الاستراتيجية للشركة.', 'Align all project objectives with the company''s strategic risk statement.', false),
      (2, 'مراجعة مؤشرات المخاطر المتأثرة بظروف السوق وتوثيقها.', 'Review and document the risk indicators affected by market conditions.', true),
      (3, 'التأكد من تحديث مخاطر السوق فقط داخل سجل المخاطر.', 'Ensure that only the market risks are updated in the risk register.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 32, id FROM question;

-- 34
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يعمل فريق المشروع في مشروع بنية تحتية حكومي يتطلب التزامًا صارمًا بحدود الامتثال التنظيمي. وقد استلم مدير المخاطر إرشادات محدثة من الجهة التنظيمية، ويحتاج إلى التأكد من تصنيف جميع المخاطر المرتبطة بصورة صحيحة والتزامها ببيانات المخاطر الجديدة. ما الذي يجب على مدير المخاطر فعله؟', 'The project team is working on a government infrastructure project that requires strict adherence to regulatory compliance thresholds. The risk manager has received updated guidelines from the regulatory authority and needs to ensure that all related risks are correctly classified and comply with the new risk statements. What should the risk manager do?', 'أصدرت الجهة التنظيمية إرشادات محدثة؛ ولذلك قد لا تكون معلومات المخاطر المرتبطة بالامتثال صالحة في صورتها الحالية. يجب إعادة تقييم محفزات المخاطر وعلامات الإنذار، وحدود الالتزام، وفئات المخاطر، وتقييمات الاحتمالية والتأثير، وتوقيت المتطلبات وتواريخ بدء سريانها، ومعايير التصعيد، والاستجابات والضوابط الحالية. بعد ذلك تُحدَّث وثائق المخاطر وفقًا للبيانات التنظيمية الجديدة.', 'The regulatory authority has issued updated guidelines; therefore, the compliance-related risk information may no longer be valid in its current form. The risk triggers and warning signs, compliance thresholds, risk categories, probability and impact assessments, timing of the requirements and their effective dates, escalation criteria, and current responses and controls must be reassessed. The risk documentation is then updated in line with the new regulatory statements.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديد اجتماع مع الجهة التنظيمية للحصول على توضيحات إضافية.', 'Schedule a meeting with the regulatory authority to obtain further clarification.', false),
      (1, 'إعادة تقييم محفزات المخاطر الحالية والتركيز على الالتزام بالقواعد والمعايير.', 'Reassess the current risk triggers and focus on compliance with the rules and standards.', true),
      (2, 'تعيين عضو متخصص من الفريق لمراقبة الالتزام بالمعايير القانونية والتنظيمية.', 'Appoint a dedicated team member to monitor compliance with the legal and regulatory standards.', false),
      (3, 'توثيق أي اختلافات بين الإرشادات السابقة والإرشادات المحدثة.', 'Document any differences between the previous guidelines and the updated guidelines.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 33, id FROM question;

-- 35
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يواجه مشروع إنشاءات تأخيرات بسبب نقص المعدات. وقد حدد مدير المخاطر موردين بديلين، لكن فريق المشروع يشعر بالقلق بشأن الجودة والتكلفة. ما الذي يجب على مدير المخاطر إعطاؤه الأولوية عند اختيار المورد لتقليل التأخير ومخاطر الجودة والميزانية؟', 'A construction project is facing delays because of an equipment shortage. The risk manager has identified alternative suppliers, but the project team is concerned about quality and cost. What should the risk manager prioritize when selecting the supplier in order to reduce the delay, quality, and budget risks?', 'التهديد الأساسي هو تأخر المشروع بسبب نقص المعدات؛ لذا ينبغي إعطاء الأولوية لقدرة المورد البديل على تسليم المعدات المطلوبة في الوقت المناسب وبمستوى جودة مقبول. يشمل التقييم موثوقية المورد وقدرته الإنتاجية ومواعيد التسليم المؤكدة وسجله في الالتزام بها وجودة المعدات والتزامها بالمواصفات وترتيبات الفحص والاختبار والضمان، إلى جانب الأثر الإجمالي على الجدول الزمني والتكلفة.', 'The primary threat is a delay to the project caused by the equipment shortage; priority should therefore be given to the alternative supplier''s ability to deliver the required equipment on time and at an acceptable level of quality. The evaluation covers the supplier''s reliability, production capacity, confirmed delivery dates and track record of meeting them, equipment quality and conformance to specifications, inspection, testing, and warranty arrangements, and the overall effect on the schedule and cost.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'اختيار المورد صاحب أفضل سجل أداء، حتى لو أدى ذلك إلى زيادة التكلفة.', 'Select the supplier with the best performance record, even if this increases the cost.', false),
      (1, 'تقييم تكلفة المورد ونظام ضمان الجودة لديه للتأكد من التزامه بمعايير المشروع.', 'Evaluate the supplier''s cost and quality assurance system to confirm compliance with the project standards.', false),
      (2, 'تقييم موثوقية المورد ومواعيد التسليم وتأثير الجودة في نجاح المشروع.', 'Evaluate the supplier''s reliability, delivery dates, and the impact of quality on project success.', true),
      (3, 'اختيار المورد الأقل تكلفة لتجنب تجاوز الميزانية.', 'Select the lowest-cost supplier to avoid exceeding the budget.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 34, id FROM question;

-- 36
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يهدف مشروع جديد لتطوير البرمجيات إلى دمج الذكاء الاصطناعي في منصة قائمة. وخلال الاجتماعات الأولية لتقييم المخاطر، أدرك مدير المخاطر أن فريق المشروع يتردد في طرح التهديدات المحتملة بسبب التسلسل الإداري وعدم حصوله على التمكين الكافي من القيادة. ما الأسلوب الذي يجب على مدير المخاطر اتباعه حتى يستمر المعنيون في عملية تحديد المخاطر؟', 'A new software development project aims to integrate artificial intelligence (AI) into an existing platform. During the initial risk assessment meetings, the risk manager realized that the project team is reluctant to raise potential threats because of the management hierarchy and a lack of sufficient empowerment from leadership. Which approach should the risk manager take so that the stakeholders continue to take part in the risk identification process?', 'لا تتمثل المشكلة الأساسية في ضعف معرفة الفريق بأساليب تحديد المخاطر، بل في تردد أعضائه في التحدث بسبب التسلسل الإداري وعدم وجود تمكين كافٍ من القيادة. يمكن لداعم المخاطر من فريق القيادة إظهار الدعم الواضح لإدارة المخاطر، وتشجيع المشاركة والمناقشة الصريحة، والتأكيد أن تحديد التهديدات سلوك إيجابي وليس انتقادًا للمشروع، وإزالة العوائق التنظيمية أمام المشاركة.', 'The underlying problem is not the team''s lack of knowledge of risk identification techniques, but the members'' reluctance to speak up because of the management hierarchy and the lack of sufficient empowerment from leadership. A risk champion from the leadership team can demonstrate visible support for risk management, encourage participation and open discussion, affirm that identifying threats is positive behavior rather than criticism of the project, and remove organizational barriers to participation.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'فرض اجتماعات أسبوعية لإدارة المخاطر مع الالتزام الصارم بالحضور.', 'Mandate weekly risk management meetings with strict attendance requirements.', false),
      (1, 'تعيين داعم مخصص لإدارة المخاطر من فريق القيادة.', 'Appoint a dedicated risk management champion from the leadership team.', true),
      (2, 'تقديم جلسات تدريب تركز على أساليب تحديد المخاطر.', 'Provide training sessions focused on risk identification techniques.', false),
      (3, 'الاعتماد على مستشارين خارجيين لإجراء تقييمات غير متحيزة للمخاطر.', 'Rely on external consultants to perform unbiased risk assessments.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 35, id FROM question;

-- 37
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنشأت منظمة وظيفة عملية جديدة لمراجعة العقود بهدف تحديد المخاطر قبل توقيع العقد. وتتضمن العملية قيام الفريق المالي بتقييم الشروط المالية، والفريق القانوني بمراجعة شروط حل النزاعات، والفريق الفني بمراجعة الشروط الخاصة بالنطاق. ما الأداة المستخدمة في هذا الموقف؟', 'An organization has established a new contract review process function to identify risks before a contract is signed. The process involves the finance team evaluating the financial terms, the legal team reviewing the dispute resolution clauses, and the technical team reviewing the scope-related terms. Which tool is being used in this situation?', 'تقوم المنظمة بمراجعة العقد قبل توقيعه لتحديد المخاطر الموجودة في أقسامه المختلفة؛ وهذا يمثل استخدام أداة مراجعة الوثائق. يراجع كل فريق الجزء المرتبط بخبرته: الشروط المالية وشروط الدفع، والالتزامات والمسؤوليات وشروط حل الخلافات، والنطاق والمتطلبات والمواصفات والمخرجات. وقد تكشف المراجعة عن شروط دفع غير مناسبة أو مسؤوليات غير واضحة أو نطاق غامض أو التزامات غير واقعية.', 'The organization is reviewing the contract before signing it to identify the risks contained in its various sections, which is a use of the document review tool. Each team reviews the part related to its expertise: financial and payment terms; obligations, liabilities, and dispute resolution clauses; and scope, requirements, specifications, and deliverables. The review may reveal unfavorable payment terms, unclear liabilities, ambiguous scope, or unrealistic obligations.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'مراجعة الوثائق.', 'Document review.', true),
      (1, 'الهيكل المصفوفي الضعيف.', 'Weak matrix structure.', false),
      (2, 'محاكاة مونت كارلو.', 'Monte Carlo simulation.', false),
      (3, 'الهيكل المصفوفي القوي.', 'Strong matrix structure.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 36, id FROM question;

-- 38
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مكتب إدارة المخاطر في شركة متعددة الجنسيات بمراجعة تقدم عدد من المشروعات الاستراتيجية الرئيسية داخل المحفظة. وقد واجه مشروع خاص بصيانة نظام رئيسي مخاطر غير متوقعة تراكمت آثارها على مستوى المؤسسة، مما أدى إلى تعرضها لنقاط ضعف مالية. ما الذي يجب على مدير المخاطر فعله؟', 'The risk management office of a multinational company is reviewing the progress of a number of key strategic projects within the portfolio. A maintenance project for a major system has encountered unexpected risks whose effects have accumulated at the enterprise level, exposing the organization to financial vulnerabilities. What should the risk manager do?', 'تجاوزت المخاطر حدود مشروع الصيانة، وأصبحت تؤدي إلى تعرض مالي على مستوى المؤسسة بالكامل. وهذا يعني أن الاستجابة قد تتجاوز صلاحيات مدير مخاطر المشروع، وتحتاج إلى قرارات على مستوى المحفظة أو المنظمة. يجب إشراك المعنيين التنفيذيين المناسبين لتوضيح إجمالي مستوى التعرض المالي، وتأثير المخاطر في المحفظة الاستراتيجية، ومواءمة الاستجابات مع شهية المنظمة للمخاطر وحدودها، وتنسيق إجراءات التخفيف بين المشروعات ووحدات الأعمال.', 'The risks have gone beyond the boundaries of the maintenance project and are now creating financial exposure across the entire enterprise. This means the response may exceed the authority of the project risk manager and requires decisions at the portfolio or organizational level. The appropriate executive stakeholders must be engaged to clarify the total level of financial exposure and the effect of the risks on the strategic portfolio, align the responses with the organization''s risk appetite and thresholds, and coordinate mitigation actions across projects and business units.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التفاوض مع الموردين لإدارة تكاليف المشروع والتحكم فيها بفاعلية.', 'Negotiate with the suppliers to effectively manage and control the project costs.', false),
      (1, 'التوصية بإيقاف المشروع مؤقتًا لمنع المزيد من التعرض المالي.', 'Recommend temporarily suspending the project to prevent further financial exposure.', false),
      (2, 'إجراء تحليل تفصيلي للسبب الجذري لفهم مصادر المخاطر.', 'Perform a detailed root cause analysis to understand the sources of the risks.', false),
      (3, 'إشراك المعنيين التنفيذيين للاتفاق على خطط تخفيف المخاطر.', 'Engage the executive stakeholders to agree on risk mitigation plans.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 37, id FROM question;

-- 39
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما المثال على المتطلبات و/أو القيود القانونية والتنظيمية عند تقييم بيئة المشروع لتحديد التهديدات والفرص؟', 'Which of the following is an example of legal and regulatory requirements and/or constraints when assessing the project environment to identify threats and opportunities?', 'قد تنشأ متطلبات السرية عن القوانين أو اللوائح أو العقود أو اتفاقيات عدم الإفصاح أو قواعد حماية البيانات أو متطلبات الالتزام الخاصة بالصناعة. وقد تشمل حماية البيانات الشخصية وبيانات العملاء، والمعلومات المالية والسجلات الطبية والملكية الفكرية والأسرار التجارية والمعلومات الحكومية السرية ووثائق المشروع الحساسة تجاريًا. قد يؤدي عدم الالتزام بهذه المتطلبات إلى تهديدات قانونية ومالية وتعاقدية وتشغيلية.', 'Confidentiality requirements may arise from laws, regulations, contracts, non-disclosure agreements, data protection rules, or industry-specific compliance requirements. They may cover the protection of personal and customer data, financial information, medical records, intellectual property, trade secrets, classified government information, and commercially sensitive project documents. Failure to comply with these requirements can lead to legal, financial, contractual, and operational threats.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'متطلبات التواصل الخاصة بالمنظمة.', 'The organization''s communication requirements.', false),
      (1, 'سرية معلومات المشروع.', 'Confidentiality of project information.', true),
      (2, 'السياسات والعمليات والإجراءات القياسية للمنظمة.', 'The organization''s standard policies, processes, and procedures.', false),
      (3, 'الإجراءات الرسمية لمشاركة المعرفة والمعلومات.', 'Formal procedures for sharing knowledge and information.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 38, id FROM question;

-- 40
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أكمل مدير المشروع أربعة مشروعات متشابهة في النطاق. وتم تعيينه مؤخرًا لبدء مشروع جديد، ويعتقد أن بعض مخاطر المشروعات السابقة قد تحدث مرة أخرى في المشروع الجديد. ما الذي يجب على مدير المخاطر فعله؟', 'A project manager has completed four projects with similar scopes. The project manager was recently assigned to start a new project and believes that some of the risks from the previous projects may occur again in the new project. What should the risk manager do?', 'تقدم مخاطر المشروعات السابقة معلومات تاريخية مفيدة، لكن لا يجب إضافتها تلقائيًا إلى سجل مخاطر المشروع الجديد، حتى لو كانت المشروعات متشابهة في النطاق؛ فقد تختلف في المعنيين والموارد وقدرات الفريق والتكنولوجيا والعقود والموردين والجدول الزمني والميزانية والافتراضات والقيود والظروف الخارجية والتنظيمية. يجب مناقشة المخاطر السابقة مع فريق المشروع والخبراء المناسبين لتحديد مدى ارتباطها بالمشروع الحالي وما إذا كانت أسبابها موجودة وما التغيرات في احتماليتها أو أثرها.', 'The risks from previous projects provide useful historical information, but they should not be added automatically to the new project''s risk register, even if the projects have similar scopes; the projects may differ in stakeholders, resources, team capabilities, technology, contracts, suppliers, schedule, budget, assumptions, constraints, and external and regulatory conditions. The previous risks must be discussed with the project team and the appropriate experts to determine how relevant they are to the current project, whether their causes are present, and how their probability or impact has changed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إضافة المخاطر إلى سجل المخاطر وتحديد احتياطي طوارئ.', 'Add the risks to the risk register and define a contingency reserve.', false),
      (1, 'إدراج استراتيجيات الاستجابة للمخاطر داخل خطة المخاطر وتنفيذها.', 'Include the risk response strategies in the risk plan and implement them.', false),
      (2, 'إبلاغ راعي المشروع بضرورة إضافة هذه المخاطر بناءً على الخبرة السابقة.', 'Inform the project sponsor that these risks need to be added based on previous experience.', false),
      (3, 'مناقشة المخاطر المحددة مع فريق المشروع وتقييمها.', 'Discuss the identified risks with the project team and assess them.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 39, id FROM question;

-- 41
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تقوم إحدى المؤسسات المالية بإنشاء قاعدة بيانات جديدة للمنتجات الخاصة بعملائها. ويشعر راعي المشروع بالقلق من احتمال فشل المنصة الرقمية التي ستستضيف قاعدة البيانات. ويوضح مدير المخاطر أن هذا الخطر لن يحدث إلا في حالة وقوع انقطاع كبير في الكهرباء، لكن المؤسسة المالية لديها مولدات كهرباء احتياطية. ما نوع الخطر المشار إليه في هذا الموقف؟', 'A financial institution is building a new product database for its customers. The project sponsor is concerned that the digital platform that will host the database could fail. The risk manager explains that this risk would occur only in the event of a major power outage, but the financial institution has backup power generators. What type of risk is being referred to in this situation?', 'الخطر المتبقي (Residual Risk) هو الخطر الذي يبقى بعد تنفيذ استجابة أو إجراء للتحكم في الخطر. هنا خُفف خطر انقطاع الكهرباء بتركيب مولدات احتياطية، لكن احتمال فشل المنصة لم يختفِ تمامًا؛ فقد يستمر الانقطاع أكثر من قدرة المولدات، أو تتعطل، أو ينفد وقودها.', 'A residual risk is the risk that remains after a response or control action has been implemented. Here, the risk of a power outage has been mitigated by installing backup generators, but the possibility of platform failure has not been eliminated entirely: the outage could last longer than the generators can sustain, the generators could fail, or they could run out of fuel.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'خطر متبقٍ.', 'Residual risk.', true),
      (1, 'خطر بيئي.', 'Environmental risk.', false),
      (2, 'خطر كبير.', 'Major risk.', false),
      (3, 'خطر ثانوي.', 'Secondary risk.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 40, id FROM question;

-- 42
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'في مشروع إنشاءات ضخم للبنية التحتية، يعقد مدير المخاطر ورش عمل مستمرة لتحديد المخاطر بمشاركة عدد من المعنيين. ولاحظ مدير المخاطر أن المعنيين يركزون فقط على المخاطر السلبية، مثل تجاوز التكلفة وحوادث الموقع وتأخير الجدول الزمني. ما الذي يجب على مدير المخاطر فعله؟', 'On a major infrastructure construction project, the risk manager holds ongoing risk identification workshops with a number of stakeholders. The risk manager has noticed that the stakeholders focus only on negative risks, such as cost overruns, site accidents, and schedule delays. What should the risk manager do?', 'يجب توضيح أن عدم التأكد قد يؤثر في أهداف المشروع سلبًا أو إيجابًا. تشمل الفرص وصول المواد مبكرًا، وتحسين أساليب الإنشاء، وانخفاض الأسعار أو تسريع الموافقات. ومن استجابات الفرص: الاستغلال، والتعزيز، والمشاركة، والقبول، والتصعيد. تساعد التوعية على جعل تحديد المخاطر أكثر توازنًا.', 'It must be made clear that uncertainty can affect project objectives either negatively or positively. Opportunities include the early arrival of materials, improved construction methods, lower prices, or accelerated approvals. The responses to opportunities include exploit, enhance, share, accept, and escalate. Raising awareness helps to make risk identification more balanced.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديث سجل المخاطر وحذف المخاطر الإيجابية ليتوافق مع اهتمام المعنيين.', 'Update the risk register and remove the positive risks to match the stakeholders'' interest.', false),
      (1, 'توعية المعنيين بالمخاطر الإيجابية واستراتيجيات الاستجابة للفرص.', 'Educate the stakeholders about positive risks and the response strategies for opportunities.', true),
      (2, 'تيسير ورشة عمل عن المخاطر الإيجابية للمعنيين المهتمين بها.', 'Facilitate a workshop on positive risks for the stakeholders who are interested in them.', false),
      (3, 'إسناد المخاطر الإيجابية إلى بعض أعضاء الفريق الأساسيين لتجنب الخلاف.', 'Assign the positive risks to some of the core team members to avoid disagreement.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 41, id FROM question;

-- 43
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'في مشروع اتصالات لتركيب شبكة جديدة من الألياف الضوئية، نفذ مدير المخاطر خطة استجابة لتخفيف التأخيرات المحتملة الناتجة عن نقص المعدات. وخلال اجتماع لمراجعة المشروع، لاحظ أحد أعضاء الفريق وجود تأخير غير متوقع من المورد، رغم الاستجابات التي تم تنفيذها. ما الذي يجب على مدير المخاطر فعله؟', 'On a telecommunications project to install a new fiber-optic network, the risk manager implemented a response plan to mitigate potential delays resulting from an equipment shortage. During a project review meeting, a team member noted an unexpected delay from the supplier, despite the responses that had been implemented. What should the risk manager do?', 'خطة الاستجابة نُفذت بالفعل، لكنها لم تعالج التأخير غير المتوقع بالكامل. لذلك ينبغي إعداد حل مؤقت (Workaround) للتعامل مع الحدث الجديد، بالتنسيق مع خبراء المشتريات والفريق الفني، وتقييم أثر التأخير والبدائل المتاحة، ثم تحديث سجلات المخاطر والخطط ذات الصلة.', 'The response plan has already been implemented, but it did not fully address the unexpected delay. A workaround should therefore be prepared to deal with the new event, in coordination with the procurement experts and the technical team, the impact of the delay and the available alternatives should be assessed, and the risk records and related plans should then be updated.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تقييم الوقت والمال اللذين تم استثمارهما في إعداد خطة الاستجابة الحالية.', 'Evaluate the time and money that were invested in preparing the current response plan.', false),
      (1, 'إعداد حل مؤقت مناسب للتعامل مع الموقف الجديد.', 'Prepare an appropriate workaround to deal with the new situation.', true),
      (2, 'إنهاء العقد واستبدال المورد بمورد آخر مشابه.', 'Terminate the contract and replace the supplier with another similar supplier.', false),
      (3, 'تسجيل درس مستفاد بضرورة إعداد عدة خطط استجابة دائمًا.', 'Record a lesson learned that multiple response plans should always be prepared.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 42, id FROM question;

-- 44
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'حدد مدير المخاطر ورش عمل لتحديد مخاطر مبادرة تشمل عدة وحدات أعمال، وتعيين موظفين في وظائف مختلفة، ومشتريات، وتطويرًا تقنيًا، وتدريبًا، وتغييرات في أساليب العمل. من الذي يجب أن يشارك في نشاط إدارة المخاطر؟', 'The risk manager has scheduled workshops to identify the risks of an initiative that involves several business units, the hiring of staff into different roles, procurement, technical development, training, and changes to working methods. Who should participate in the risk management activity?', 'تشمل المبادرة جوانب تنظيمية وفنية وتعاقدية وتشغيلية، وقد تؤثر في أطراف داخل المنظمة وخارجها. لذلك يلزم إشراك المعنيين الداخليين، مثل فرق المشروع والموارد البشرية والمشتريات والتقنية، والخارجيين، مثل الموردين والمقاولين والجهات التنظيمية، للحصول على صورة أشمل للمخاطر.', 'The initiative involves organizational, technical, contractual, and operational aspects and may affect parties both inside and outside the organization. It is therefore necessary to involve internal stakeholders, such as the project teams, human resources, procurement, and technology, as well as external stakeholders, such as suppliers, contractors, and regulatory authorities, to obtain a more comprehensive picture of the risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'المعنيون الرئيسيون من وحدات الأعمال.', 'Key stakeholders from the business units.', false),
      (1, 'المعنيون الداخليون فقط.', 'Internal stakeholders only.', false),
      (2, 'المعنيون الداخليون والخارجيون.', 'Internal and external stakeholders.', true),
      (3, 'فريق المشروع الأساسي.', 'The core project team.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 43, id FROM question;

-- 45
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أجرى مدير المخاطر استبيانًا للمخاطر قبل ورشة العمل القادمة. وشارك المدعوون إلى الورشة في الاستبيان، وقدموا عددًا كبيرًا من المخاطر التي تغطي جميع مراحل المشروع ومجالات المخاطر. ثم بدأ مدير المخاطر في ترتيب المخاطر وفقًا لأوجه التشابه والفئات. ما الذي يجب على مدير المخاطر فعله بعد ذلك لتنظيم المخاطر بشكل مرئي؟', 'The risk manager conducted a risk survey before the upcoming workshop. The workshop invitees took part in the survey and submitted a large number of risks covering all project phases and risk areas. The risk manager then began to arrange the risks according to similarities and categories. What should the risk manager do NEXT to organize the risks visually?', 'مخطط التقارب (Affinity Diagram) أداة بصرية لتنظيم عدد كبير من الأفكار أو المخاطر في مجموعات منطقية بحسب التشابه. يساعد على عرض المخاطر الفردية بصريًا، وتحديد الموضوعات والفئات المشتركة، واكتشاف المخاطر المكررة أو المتداخلة، وإظهار الأنماط والعلاقات تمهيدًا لمناقشتها في ورشة العمل.', 'An affinity diagram is a visual tool for organizing a large number of ideas or risks into logical groups based on similarity. It helps to display the individual risks visually, identify common themes and categories, detect duplicate or overlapping risks, and reveal patterns and relationships in preparation for discussion at the workshop.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إجراء عملية التحليل الهرمي.', 'Perform the analytic hierarchy process.', false),
      (1, 'إعداد مخطط التقارب.', 'Prepare an affinity diagram.', true),
      (2, 'إجراء تحليل نقاط القوة والضعف والفرص والتهديدات SWOT.', 'Perform a strengths, weaknesses, opportunities, and threats (SWOT) analysis.', false),
      (3, 'تحديد الاحتمالية والتأثير.', 'Determine probability and impact.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 44, id FROM question;

-- 46
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم تكليف مدير المخاطر بوضع استراتيجية لإدارة المخاطر في مشروع متعدد الجنسيات، مع وجود اختلاف في اللوائح وأولويات المعنيين. وينقسم الفريق حول طريقة إدارة المخاطر: فالبعض يقترح تطبيق إجراءات صارمة لضمان الاتساق بين المناطق، بينما يدعو آخرون إلى منهج مرن للتكيف مع الطبيعة المتغيرة للمخاطر المحلية. وفي الوقت نفسه، يؤكد راعي المشروع ضرورة مواءمة الاستراتيجية مع أهداف المشروع العامة. ما الذي يجب على مدير المخاطر فعله؟', 'The risk manager has been assigned to develop a risk management strategy for a multinational project in which regulations and stakeholder priorities differ. The team is divided over how to manage risks: some propose applying strict procedures to ensure consistency across regions, while others call for a flexible approach that adapts to the changing nature of local risks. At the same time, the project sponsor emphasizes that the strategy must be aligned with the overall project objectives. What should the risk manager do?', 'يحتاج المشروع متعدد الجنسيات إلى إطار مشترك للمخاطر يضمن اتساق المصطلحات والأدوار والتقارير ومعايير التقييم، مع مرونة تسمح بتكييف الاستجابات مع اللوائح والثقافات وأولويات المعنيين والمخاطر المحلية. يحقق هذا التوازن مواءمة إدارة المخاطر مع أهداف المشروع دون تجاهل اختلاف المناطق.', 'A multinational project needs a common risk framework that ensures consistent terminology, roles, reporting, and assessment criteria, together with the flexibility to adapt responses to local regulations, cultures, stakeholder priorities, and risks. This balance aligns risk management with the project objectives without ignoring the differences between regions.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
