    FROM question, (VALUES
      (0, 'استخدام إرشادات المنظمة لإعداد استراتيجية تعطي الأولوية للكفاءة على حساب القدرة على التكيف.', 'Use the organization''s guidelines to prepare a strategy that prioritizes efficiency over adaptability.', false),
      (1, 'تطبيق منهج صارم وموحد لضمان الاتساق بين جميع المناطق.', 'Apply a strict, standardized approach to ensure consistency across all regions.', false),
      (2, 'إعداد استراتيجية تجمع بين الهيكل المنظم والمرونة للتعامل مع حالات عدم التأكد العالمية والمحلية.', 'Prepare a strategy that combines structure and flexibility to deal with global and local uncertainties.', true),
      (3, 'تطبيق منهج مرن بالكامل يسمح للفرق بإدارة المشكلات وفقًا للظروف المحلية.', 'Apply a fully flexible approach that allows the teams to manage issues according to local conditions.', false)
    ) AS v (position, text_ar, text_en, is_correct)
