-- 47
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء تخطيط إدارة المخاطر، أوصى المعنيون الرئيسيون بإضافة عوامل أخرى غير الاحتمالية والتأثير لتحسين درجة ترتيب التهديدات حسب الأولوية في المرات التالية من التحليل النوعي للمخاطر. وطلبوا من مدير المخاطر إعداد قائمة لمناقشتها. ما العوامل الثلاثة الصحيحة التي يجب على مدير المخاطر إضافتها إلى القائمة؟ (اختر 3)', 'During risk management planning, the key stakeholders recommended adding factors other than probability and impact to improve the prioritization ranking of threats in subsequent rounds of qualitative risk analysis. They asked the risk manager to prepare a list for discussion. Which three factors are the correct ones for the risk manager to add to the list? (Choose three)', 'يمكن استخدام خصائص إضافية إلى جانب الاحتمالية والتأثير لتحسين ترتيب المخاطر الفردية. الإلحاح (Urgency) يوضح مدى سرعة الحاجة إلى الاستجابة؛ وقرب الحدوث (Proximity) يوضح المدة المتوقعة حتى وقوع الخطر؛ وقابلية الاكتشاف (Detectability) توضح مدى سهولة اكتشاف الخطر أو علاماته المبكرة.', 'Additional characteristics can be used alongside probability and impact to refine the prioritization of individual risks. Urgency indicates how quickly a response is needed; proximity indicates the expected time until the risk occurs; and detectability indicates how easily the risk or its early warning signs can be detected.', 3)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'قابلية الاكتشاف.', 'Detectability.', true),
      (1, 'قرب الحدوث.', 'Proximity.', true),
      (2, 'التوافق.', 'Compatibility.', false),
      (3, 'الإلحاح.', 'Urgency.', true),
      (4, 'سهولة الاستخدام.', 'Ease of use.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 46, id FROM question;

-- 48
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء إعداد خطة استجابة لخطر على مستوى البرنامج، قدّر مدير المخاطر تكلفة الإجراءات المحتملة لتخفيف الخطر. وتضمنت الميزانية المعتمدة احتياطيًا تم حسابه بناءً على القيمة الوسيطة لنطاق التكلفة. وتتم حاليًا متابعة الخطر بصورة نشطة، مع احتمال الحاجة إلى إجراء إضافي إذا كانت الميزانية المخصصة غير كافية. ما المعلومات الإضافية التي يجب على مدير المخاطر إدراجها في خطة الاستجابة؟', 'While preparing a response plan for a program-level risk, the risk manager estimated the cost of the possible actions to mitigate the risk. The approved budget included a reserve that was calculated based on the median value of the cost range. The risk is currently being actively monitored, and additional action may be needed if the allocated budget proves insufficient. What additional information should the risk manager include in the response plan?', 'احتساب الاحتياطي بالقيمة الوسيطة لا يضمن كفايته؛ فقد تكون التكلفة الفعلية للاستجابة أعلى منها. لذا يجب أن تحدد خطة الاستجابة ما سيحدث إذا لم يكفِ الاحتياطي، مثل حدود التكلفة التي تستدعي إجراءً إضافيًا، وإجراءات طلب التمويل والموافقات والتصعيد، والاستجابات البديلة عند الحاجة.', 'Calculating the reserve at the median value does not guarantee that it will be sufficient; the actual cost of the response may be higher. The response plan must therefore define what will happen if the reserve is not enough, such as the cost thresholds that call for additional action, the procedures for requesting funding, approvals, and escalation, and the alternative responses to be used when needed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحديد الشخص المسؤول عن مراقبة الخطر وتقييم نتائج الاستجابة.', 'The person responsible for monitoring the risk and evaluating the results of the response.', false),
      (1, 'تحديد الوقت المطلوب لتنفيذ الاستجابة المخططة بفاعلية.', 'The time required to implement the planned response effectively.', false),
      (2, 'توضيح أساس حساب الميزانية المخصصة لتخفيف الخطر.', 'The basis for calculating the budget allocated to mitigating the risk.', false),
      (3, 'توضيح الإجراء الذي سيتم اتباعه إذا ظهرت حاجة إلى تمويل إضافي.', 'The procedure to be followed if a need for additional funding arises.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 47, id FROM question;

-- 49
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال مرحلة تخطيط المشروع، حدد فريق المشروع بالتعاون مع مدير المشروع أربعة مخاطر مهمة قد تؤثر في المشروع. كما قام الفريق بتقييم احتياطي الطوارئ المخصص للتعامل مع هذه المخاطر. وخلال مرحلة التنفيذ، حدث الخطر R2 وأثر في المشروع. ما المبلغ المتبقي من احتياطي الطوارئ؟
بيانات المخاطر: R1 (40%، 30,000 دولار)؛ R2 (60%، 80,000 دولار)؛ R3 (30%، 150,000 دولار)؛ R4 (70%، 50,000 دولار).', 'During the project planning phase, the project team, in collaboration with the project manager, identified four significant risks that could affect the project. The team also evaluated the contingency reserve allocated to deal with these risks. During the execution phase, risk R2 occurred and affected the project. What is the remaining amount of the contingency reserve?
Risk data: R1 (40%, $30,000); R2 (60%, $80,000); R3 (30%, $150,000); R4 (70%, $50,000).', 'الاحتياطي الأولي وفق القيمة النقدية المتوقعة (EMV) يساوي مجموع حاصل ضرب احتمال كل خطر في أثر تكلفته: R1 = 40% × 30,000 = 12,000؛ وR2 = 60% × 80,000 = 48,000؛ وR3 = 30% × 150,000 = 45,000؛ وR4 = 70% × 50,000 = 35,000. الإجمالي = 140,000 دولار. بعد حدوث R2 بتكلفة 80,000 دولار، يصبح المتبقي = 140,000 − 80,000 = 60,000 دولار.', 'The initial reserve based on expected monetary value (EMV) equals the sum of each risk''s probability multiplied by its cost impact: R1 = 40% × 30,000 = 12,000; R2 = 60% × 80,000 = 48,000; R3 = 30% × 150,000 = 45,000; and R4 = 70% × 50,000 = 35,000. The total is $140,000. After R2 occurs at a cost of $80,000, the remaining reserve is 140,000 − 80,000 = $60,000.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, '60,000 دولار.', '$60,000.', true),
      (1, '-80,000 دولار.', '−$80,000.', false),
      (2, '80,000 دولار.', '$80,000.', false),
      (3, '140,000 دولار.', '$140,000.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 48, id FROM question;

-- 50
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء تنفيذ المشروع، طلب فريق المنتج إجراء تغيير في النطاق. وأوضح الفريق أن التغيير بسيط ولن يؤدي إلى أي مشكلات. ما الذي يجب على مدير المخاطر فعله بعد ذلك؟', 'During project execution, the product team requested a change to the scope. The team explained that the change is minor and will not cause any problems. What should the risk manager do NEXT?', 'حتى لو اعتبر فريق المنتج التغيير بسيطًا، يجب عدم افتراض أنه بلا أثر. قد يؤثر في التكلفة والجدول الزمني والاعتماديات والجودة والأداء الفني والموارد والعقود والالتزام والمخاطر المتبقية والثانوية. يبدأ مدير المخاطر بتحليل الأثر المحتمل وتقديم نتائجه ضمن إجراءات التحكم الرسمي في التغيير، ثم تُحدَّث الوثائق ذات الصلة حسب النتائج.', 'Even if the product team considers the change minor, it should not be assumed to have no effect. It could affect cost, schedule, dependencies, quality, technical performance, resources, contracts, compliance, and residual and secondary risks. The risk manager begins by analyzing the potential impact and presenting the findings through the formal change control procedures; the relevant documents are then updated according to the results.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل أي تأثير محتمل.', 'Analyze any potential impact.', true),
      (1, 'إضافة خطر جديد إلى سجل المخاطر.', 'Add a new risk to the risk register.', false),
      (2, 'تحديث هيكل تقسيم العمل.', 'Update the work breakdown structure.', false),
      (3, 'تصعيد الموضوع إلى الإدارة.', 'Escalate the matter to management.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 49, id FROM question;

-- 51
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تقوم إحدى شركات التكنولوجيا بتطوير منصة برمجية جديدة يُتوقع أن تُحدث تغييرًا كبيرًا في السوق. وحدد الفريق وجود خطر مرتفع يتمثل في مشكلات فنية محتملة قد تؤدي إلى تأخير التسليم. ما الإجراءان اللذان يجب على مدير المخاطر التركيز عليهما لإدارة هذه المخاطر؟ (اختر إجابتين)', 'A technology company is developing a new software platform that is expected to bring about a major change in the market. The team has identified a high risk of potential technical problems that could delay delivery. Which two actions should the risk manager focus on to manage this risk? (Choose two)', 'يواجه المشروع تهديدًا فنيًا مرتفعًا قد يؤدي إلى تأخير التسليم؛ لذا يلزم توفير الخبرة الفنية المناسبة ووضوح المسؤولية. يساعد الخبير الفني على تحليل أسباب الأعطال المحتملة ووضع إجراءات التخفيف ومراقبة العلامات التحذيرية، ويساعد تعيين الأدوار والمسؤوليات على ضمان تنفيذ الإجراءات ومتابعتها.', 'The project faces a high technical threat that could delay delivery; appropriate technical expertise and clear responsibility are therefore required. The technical expert helps to analyze the causes of potential failures, develop mitigation actions, and monitor the warning signs, while assigning roles and responsibilities helps to ensure that the actions are implemented and followed up.', 2)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التعاون مع المعنيين لإعادة تعريف أهداف المشروع مع مراعاة المخاطر.', 'Collaborate with the stakeholders to redefine the project objectives while taking the risks into account.', false),
      (1, 'تعيين خبير فني متخصص للإشراف على جهود تخفيف المخاطر.', 'Appoint a specialized technical expert to oversee the risk mitigation efforts.', true),
      (2, 'تحديد اجتماعات مراجعة متكررة مع الفريق بالكامل للمتابعة.', 'Schedule frequent review meetings with the entire team for follow-up.', false),
      (3, 'تنفيذ حل مؤقت بمساعدة الخبراء الفنيين لمعالجة التأخيرات المحتملة.', 'Implement a workaround with the help of the technical experts to address the potential delays.', false),
      (4, 'تحديد أدوار ومسؤوليات واضحة لأعضاء معينين في الفريق لإدارة المخاطر.', 'Define clear roles and responsibilities for specific team members to manage the risks.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 50, id FROM question;

-- 52
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يدير فريق المشروع مشروع بنية تحتية معقدًا يحتوي على مخاطر كبيرة. ولضمان عملية إدارة المخاطر، يجب على الفريق التأكد من استمرار فاعلية سجل المخاطر في متابعة المخاطر والتعامل معها طوال دورة حياة المشروع. كيف يجب الحفاظ على سجل المخاطر لضمان استمرار فاعليته طوال المشروع؟', 'The project team is managing a complex infrastructure project that involves significant risks. To ensure the risk management process, the team must make sure that the risk register remains effective in tracking and addressing risks throughout the project life cycle. How should the risk register be maintained to ensure that it remains effective throughout the project?', 'سجل المخاطر وثيقة حية يجب مراجعتها وتحديثها بانتظام طوال دورة حياة المشروع. ينبغي أن تعكس المراجعات تغير الاحتمالية والتأثير والإلحاح وقرب الحدوث، ومحفزات المخاطر وحدودها، وأولويات المخاطر وإجمالي مستوى التعرض، وملكية المخاطر، وتنفيذ الاستجابات وفاعليتها، والمخاطر المتبقية والثانوية والناشئة، والمخاطر التي انتهت صلاحيتها أو يمكن إغلاقها.', 'The risk register is a living document that must be reviewed and updated regularly throughout the project life cycle. The reviews should reflect changes in probability, impact, urgency, and proximity; risk triggers and thresholds; risk priorities and the overall level of exposure; risk ownership; the implementation and effectiveness of responses; residual, secondary, and emerging risks; and risks that have expired or can be closed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تعديل السجل كلما حدث خطر جديد أو ظهرت مخاطر جديدة.', 'Modify the register whenever a new risk occurs or new risks emerge.', false),
      (1, 'إدخال التغييرات خلال المراجعات المنتظمة لتعكس تطور ظروف المخاطر.', 'Enter changes during regular reviews to reflect the evolution of the risk conditions.', true),
      (2, 'اعتماد السجل بصورة نهائية بعد إعداده أول مرة واستخدامه كوثيقة مرجعية.', 'Approve the register as final after it is first prepared and use it as a reference document.', false),
      (3, 'إعداد خط أساس أولي للمخاطر المحددة أثناء بدء المشروع.', 'Prepare an initial baseline of the risks identified during project initiation.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
