-- 53
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال إحدى المراجعات، اكتشف مدير المخاطر خطرًا ثانويًا ذا احتمالية مرتفعة، ويريد تحديد ما إذا كان يجب تغيير استجابة الخطر الأصلي أم أنها ما زالت مناسبة. ما الأداة التي يجب أن تدعم قرار مدير المخاطر؟', 'During a review, the risk manager discovered a secondary risk with a high probability and wants to determine whether the response to the original risk should be changed or is still appropriate. Which tool should support the risk manager''s decision?', 'تساعد شجرة القرار على مقارنة الاستجابة الأصلية بالبدائل، مع تمثيل احتمالات النتائج وتكاليفها أو منافعها، بما فيها أثر الخطر الثانوي. وبذلك يمكن تحديد ما إذا كانت الاستجابة الأصلية لا تزال مناسبة أو ينبغي تعديلها.', 'A decision tree helps to compare the original response with the alternatives by representing the probabilities of the outcomes and their costs or benefits, including the effect of the secondary risk. In this way, it can be determined whether the original response is still appropriate or should be modified.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل نقاط القوة والضعف والفرص والتهديدات SWOT.', 'Strengths, weaknesses, opportunities, and threats (SWOT) analysis.', false),
      (1, 'تحليل شجرة القرار.', 'Decision tree analysis.', true),
      (2, 'مخططات التقارب.', 'Affinity diagrams.', false),
      (3, 'مخطط عظم السمكة.', 'Fishbone diagram.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
