-- 54
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'في أثناء إعداد خطة إدارة المخاطر أجرى مدير المخاطر جلسة عصف ذهني لتحديد مخاطر المؤسسة باستخدام أسلوب هيكل تقسيم المخاطر RBS. ما الذي يجب على مدير المخاطر فعله بعد ذلك في تطوير هيكل تقسيم المخاطر؟', 'While preparing the risk management plan, the risk manager held a brainstorming session to identify the organization''s risks using the risk breakdown structure (RBS) technique. What should the risk manager do NEXT in developing the risk breakdown structure?', 'ينظم هيكل تقسيم المخاطر مصادر المخاطر في فئات ومكونات هرمية. بعد تحديد هذه المكونات، ينبغي استخدام النتائج لدعم التحليل وتخطيط الاستجابات المناسبة للمخاطر القابلة للإدارة، مع تحديد المالكين والإجراءات المطلوبة.', 'The risk breakdown structure organizes the sources of risk into hierarchical categories and components. Once these components have been identified, the results should be used to support the analysis and the planning of appropriate responses for the manageable risks, with the owners and the required actions defined.', 1)
  RETURNING id
), choices AS (
