  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تبرير زيادة ميزانية المشروع لتغطية المخاطر المحتملة.', 'Justify an increase in the project budget to cover the potential risks.', false),
