-- 55
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'في مشروع حكومي لتحديث أحد الأنظمة، يريد مدير المخاطر إشراك جميع المعنيين المناسبين في ورشة عمل تهدف إلى دراسة وتحديد التهديدات والفرص المحتملة. ويواجه المشروع تحديات بسبب التغييرات المتكررة في اللوائح والتطورات التكنولوجية. ما الذي يجب على مدير المخاطر فعله لتمكين المعنيين من تحديد التهديدات والفرص بشكل مستقل؟', 'On a government project to modernize a system, the risk manager wants to involve all of the appropriate stakeholders in a workshop aimed at examining and identifying potential threats and opportunities. The project faces challenges because of frequent regulatory changes and technological developments. What should the risk manager do to enable the stakeholders to identify threats and opportunities independently?', 'تسمح الاستبيانات المجهولة للمعنيين بتحديد التهديدات والفرص بصورة مستقلة قبل المناقشة الجماعية، وتقلل التفكير الجماعي وضغط الزملاء وتأثير الشخصيات المسيطرة، وتشجع المشاركين الأقل ميلًا إلى الكلام على عرض آرائهم. يمكن استخدام الإجابات المجمعة بعد ذلك في ورشة العمل.', 'Anonymous questionnaires allow stakeholders to identify threats and opportunities independently before the group discussion. They reduce groupthink, peer pressure, and the influence of dominant personalities, and they encourage participants who are less inclined to speak up to present their views. The collected responses can then be used in the workshop.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تطبيق نظام مكافآت يعتمد على النقاط مقابل تحديد المخاطر والفرص.', 'Apply a points-based reward system for identifying risks and opportunities.', false),
      (1, 'استخدام استبيانات دون ذكر الأسماء لجمع آراء المعنيين الأولية قبل ورشة العمل.', 'Use anonymous questionnaires to collect the stakeholders'' initial views before the workshop.', true),
      (2, 'توزيع تقارير تفصيلية عن الاتجاهات التكنولوجية قبل ورشة العمل للحصول على رؤى فردية.', 'Distribute detailed reports on technology trends before the workshop to obtain individual insights.', false),
      (3, 'قصر ورشة العمل على المعنيين من المستوى الإداري فقط لتسريع اتخاذ القرار.', 'Limit the workshop to management-level stakeholders only in order to speed up decision-making.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 54, id FROM question;

-- 56
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يدير مدير المشروع مشروعًا في بيئة هجينة. ولضمان فاعلية تحديد المخاطر طوال دورة حياة المشروع، طلب من مدير المخاطر اختيار نشاط أو عملية تتوافق مع النهج الهجين. ما الذي يجب على مدير المخاطر فعله؟', 'A project manager is managing a project in a hybrid environment. To ensure effective risk identification throughout the project life cycle, the project manager asked the risk manager to select an activity or process that is compatible with the hybrid approach. What should the risk manager do?', 'يجمع المشروع الهجين بين الممارسات التنبؤية والتكيفية؛ لذا ينبغي أن تكون عملية تحديد المخاطر تكرارية ومستمرة طوال دورة الحياة، خلال التخطيط والمراجعات وبوابات المراحل، مع مراعاة المخاطر الناشئة عند تغير المتطلبات أو ظهور معلومات جديدة.', 'A hybrid project combines predictive and adaptive practices; the risk identification process should therefore be iterative and continuous throughout the life cycle, during planning, reviews, and phase gates, with attention to emerging risks whenever requirements change or new information appears.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إجراء تقييم شامل للمخاطر عند بدء المشروع.', 'Perform a comprehensive risk assessment at the start of the project.', false),
      (1, 'تحديد المخاطر بصورة منتظمة أثناء التخطيط ومراجعات بوابات المراحل.', 'Identify risks regularly during planning and phase-gate reviews.', true),
      (2, 'جمع الدروس المستفادة المتعلقة بالمخاطر من كل مرحلة في المشروع.', 'Collect risk-related lessons learned from each phase of the project.', false),
      (3, 'استخدام قائمة تحقق موحدة لتحديد المخاطر طوال المشروع.', 'Use a standardized checklist to identify risks throughout the project.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 55, id FROM question;

-- 57
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم إبلاغ مدير المشروع ذي تصنيف مخاطر مرتفع بأن أحد الموارد الرئيسية قرر مغادرة المنظمة. وطلب مدير المشروع توصيات مدير المخاطر. كان مدير المخاطر قد حدد هذا الاحتمال مسبقًا باعتباره خطرًا، وأعد خطة انتقال تسمح لمورد آخر بتنفيذ المهام نفسها. لكن نقل المسؤوليات إلى المورد الجديد أدى إلى ظهور مخاطر جديدة قد تؤثر في مواعيد إنجاز مهام أخرى مرتبطة بالمشروع. بماذا يجب على مدير المخاطر أن ينصح مدير المشروع؟', 'The manager of a project with a high risk rating has been informed that one of the key resources has decided to leave the organization. The project manager has asked the risk manager for recommendations. The risk manager had previously identified this possibility as a risk and had prepared a transition plan that allows another resource to carry out the same tasks. However, transferring the responsibilities to the new resource has led to new risks that could affect the completion dates of other project-related tasks. What should the risk manager advise the project manager to do?', 'كانت مغادرة المورد خطرًا محددًا، وكانت خطة الانتقال استجابة مخططة له. أما المخاطر الجديدة التي نتجت عن نقل المسؤوليات فهي مخاطر ثانوية، وينبغي تسجيلها وتحليلها وتعيين مالكيها وتخطيط استجاباتها ومراقبتها وفقًا لعملية إدارة المخاطر المعتمدة.', 'The departure of the resource was an identified risk, and the transition plan was its planned response. The new risks that resulted from transferring the responsibilities are secondary risks, and they should be logged, analyzed, assigned to owners, planned for, and monitored in accordance with the approved risk management process.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التعامل مع هذه المخاطر الثانوية وفقًا لخطة إدارة المخاطر.', 'Handle these secondary risks in accordance with the risk management plan.', true),
      (1, 'تحديث خطة إدارة المخاطر بالاحتمالية والتأثير الجديدين وتغيير الاستجابة.', 'Update the risk management plan with the new probability and impact and change the response.', false),
      (2, 'تطبيق استراتيجية قبول المخاطر الجديدة لعدم وجود خطة استجابة لها.', 'Apply the accept strategy to the new risks because there is no response plan for them.', false),
      (3, 'تصعيد المخاطر الجديدة فورًا إلى المعنيين بالمشروع لضمان وجود تواصل مناسب بشأن المخاطر.', 'Immediately escalate the new risks to the project stakeholders to ensure appropriate risk communication.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 56, id FROM question;

-- 58
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال مراجعة في منتصف مشروع دولي لتحديث البنية التحتية لتكنولوجيا المعلومات، حدد مدير المخاطر احتمال تأخر عمليات نقل البيانات الرئيسية بسبب عدم التأكد من توافق البيانات بين الأنظمة القديمة والمنصة الجديدة. ونظرًا لضيق الجدول الزمني واحتمال تأثر مخرجات المشروع، توجد حاجة إلى اتخاذ إجراء فوري. ما الذي يجب على مدير المخاطر فعله للتعامل مع الخطر المحدد؟', 'During a mid-project review of an international IT infrastructure modernization project, the risk manager identified the possibility that key data migrations could be delayed because of uncertainty about data compatibility between the legacy systems and the new platform. Given the tight schedule and the potential effect on the project deliverables, immediate action is needed. What should the risk manager do to address the identified risk?', 'تأخر نقل البيانات ما زال حدثًا مستقبليًا غير مؤكد؛ لذا فهو خطر يحتاج إلى خطة استباقية للتخفيف، لا إلى حل مؤقت لمشكلة حدثت بالفعل. يساعد متخصصو البيانات على تقييم التوافق بين الأنظمة، واكتشاف اختلافات التنسيقات والهياكل، وإجراء اختبارات نقل تجريبية وتحديد إجراءات التحويل والتحقق.', 'The delay to the data migration is still an uncertain future event; it is therefore a risk that requires a proactive mitigation plan, not a workaround for a problem that has already occurred. Data specialists help to assess compatibility between the systems, detect differences in formats and structures, run pilot migration tests, and define the conversion and validation procedures.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إعادة تقييم سجل مخاطر المشروع بالكامل لإضافة المخاطر الجديدة والناشئة.', 'Reassess the entire project risk register to add the new and emerging risks.', false),
      (1, 'إعداد خطة تخفيف بمشاركة متخصصي البيانات لتقييم التوافق وضمانه.', 'Prepare a mitigation plan with the participation of data specialists to assess and ensure compatibility.', true),
      (2, 'تنفيذ حل مؤقت باستخدام حلول مؤقتة للبيانات لحين الوصول إلى حل دائم.', 'Implement a workaround using temporary data solutions until a permanent solution is reached.', false),
      (3, 'إبلاغ جميع المعنيين بالتأثير المحتمل وإعداد تقرير تفصيلي.', 'Inform all stakeholders of the potential impact and prepare a detailed report.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 57, id FROM question;

-- 59
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'قدم مستثمرو مشروع بنية تحتية ضخم لراعي المشروع قائمة بالتحديات المحتملة. ونتيجة لذلك، طلب راعي المشروع من مدير المخاطر إعداد خطة شاملة للتعامل مع عدة مخاطر تم تحديدها خلال مرحلة التخطيط. ما الذي يجب على مدير المخاطر فعله؟', 'The investors in a major infrastructure project have presented the project sponsor with a list of potential challenges. As a result, the project sponsor has asked the risk manager to prepare a comprehensive plan for dealing with several risks that were identified during the planning phase. What should the risk manager do?', 'يطلب الراعي نهجًا شاملًا لإدارة المخاطر طوال المشروع؛ لذا يجب وضع استراتيجية تحدد كيفية تحديد المخاطر وتحليلها والاستجابة لها ومراقبتها والتواصل بشأنها، والأدوار والمسؤوليات وفئات المخاطر وشهيتها وحدودها ومعايير الأولوية وطرق التحليل والتصعيد والحوكمة.', 'The sponsor is requesting a comprehensive approach to managing risk throughout the project; a strategy must therefore be developed that defines how risks will be identified, analyzed, responded to, monitored, and communicated, together with the roles and responsibilities, risk categories, risk appetite and thresholds, prioritization criteria, analysis methods, escalation, and governance.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إعداد هيكل تقسيم المخاطر.', 'Prepare a risk breakdown structure (RBS).', false),
      (1, 'مراجعة دورة حياة إدارة المخاطر.', 'Review the risk management life cycle.', false),
      (2, 'تحليل قائمة مراقبة المخاطر الحالية.', 'Analyze the current risk watch list.', false),
      (3, 'وضع استراتيجية لإدارة المخاطر.', 'Develop a risk management strategy.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 58, id FROM question;

-- 60
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أكمل مدير المخاطر تقييمًا شاملًا للمخاطر وعمل مع مالكي المخاطر على تنفيذ استراتيجيات الاستجابة في مشروع مؤسسي مهم. ويوجد المشروع الآن في مرحلته النهائية. ما الذي يجب على مدير المخاطر فعله؟', 'The risk manager has completed a comprehensive risk assessment and has worked with the risk owners to implement the response strategies on an important enterprise project. The project is now in its final phase. What should the risk manager do?', 'في المرحلة النهائية وبعد تنفيذ الاستجابات، يجب مراجعة الحالة الحالية والنهائية لكل خطر مع مالكه وتحديث سجل المخاطر: هل وقع الخطر؟ هل نُفذت الاستجابة وكانت فعالة؟ هل بقيت مخاطر متبقية أو ثانوية؟ هل يمكن إغلاق الخطر أو ينبغي نقل مسؤوليته؟ يضمن ذلك دقة معلومات المخاطر قبل إغلاق المشروع.', 'In the final phase, after the responses have been implemented, the current and final status of each risk must be reviewed with its owner and the risk register updated: Did the risk occur? Was the response implemented, and was it effective? Do any residual or secondary risks remain? Can the risk be closed, or should responsibility for it be transferred? This ensures that the risk information is accurate before the project is closed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التنسيق مع مالكي المخاطر وتحديث ميثاق المشروع.', 'Coordinate with the risk owners and update the project charter.', false),
      (1, 'توثيق استراتيجيات الاستجابة للمخاطر داخل قاعدة الدروس المستفادة.', 'Document the risk response strategies in the lessons learned repository.', false),
      (2, 'التنسيق مع مالكي المخاطر لتحديث حالة المخاطر في سجل المخاطر.', 'Coordinate with the risk owners to update the status of the risks in the risk register.', true),
      (3, 'تحديث الجدول الزمني للمشروع بالمخاطر المتوقعة والمخاطر التي حدثت.', 'Update the project schedule with the forecasted risks and the risks that have occurred.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 59, id FROM question;

-- 61
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال الاجتماع الأسبوعي للمشروع، حدد مدير المخاطر مخاطر جديدة ظهرت في السبرنت الأخير، وقد تؤثر هذه المخاطر في تكلفة المشروع عند تنفيذ خطط التخفيف. لكن راعي المشروع وبعض أعضاء الفريق لا يتفقون على أن هذه المخاطر يمكن أن تؤثر في التكلفة. ما الذي يجب على مدير المخاطر فعله لمعالجة مخاوف راعي المشروع وأعضاء الفريق بشأن تحديد المخاطر؟', 'During the weekly project meeting, the risk manager identified new risks that emerged in the last sprint, and these risks could affect the project cost when the mitigation plans are implemented. However, the project sponsor and some team members do not agree that these risks could affect the cost. What should the risk manager do to address the concerns of the project sponsor and the team members about the risk identification?', 'لا يتفق راعي المشروع وبعض أعضاء الفريق على أن المخاطر الجديدة وخطط تخفيفها قد تؤثر في تكلفة المشروع. لذلك ينبغي عرض تحليل تحديد المخاطر في اجتماع منفصل لمعالجة المخاوف بشفافية. ويمكن خلال الاجتماع توضيح البيانات والمعلومات المستخدمة، والافتراضات، والأسباب والأحداث غير المؤكدة، واحتمالية التأثير في التكلفة، والتقديرات وأدوات التحليل والقيود، ثم مناقشة الأسئلة للوصول إلى فهم مشترك.', 'The project sponsor and some team members do not agree that the new risks and their mitigation plans could affect the project cost. The risk identification analysis should therefore be presented in a separate meeting to address the concerns transparently. During the meeting, the data and information used, the assumptions, the causes and uncertain events, the likelihood of a cost impact, the estimates, the analysis tools, and the constraints can be explained, and questions can then be discussed to reach a shared understanding.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التأكد من قيام أعضاء الفريق الأكثر معرفة بالتحقق من صحة عمليات تحديد المخاطر.', 'Ensure that the most knowledgeable team members validate the risk identification processes.', false),
      (1, 'عقد اجتماع منفصل لعرض تحليل تحديد المخاطر على المعنيين.', 'Hold a separate meeting to present the risk identification analysis to the stakeholders.', true),
      (2, 'توضيح أهمية الاتفاق على المخاطر المحددة لتجنب المزيد من التأخير.', 'Explain the importance of agreeing on the identified risks to avoid further delays.', false),
      (3, 'التأكيد للمعنيين أن عملية تحديد المخاطر تمت بصورة صحيحة خلال السبرنت الأخير.', 'Assure the stakeholders that the risk identification process was performed correctly during the last sprint.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 60, id FROM question;

-- 62
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يستعد فريق إنشاءات مدنية لبدء العمل في مشروع بنية تحتية حضري متعدد المراحل. وخلال مراحل التخطيط الأولى، حدد الفريق بعض الافتراضات، مثل مواعيد توريد المواد والظروف الجوية، وبعض القيود، مثل الحد الأقصى للميزانية وتوافر العمالة. وقد أعد الفريق الآن قائمة شاملة بهذه الافتراضات والقيود. ما الذي يجب على مدير المخاطر فعله؟', 'A civil construction team is preparing to begin work on a multi-phase urban infrastructure project. During the early planning stages, the team identified some assumptions, such as material delivery dates and weather conditions, and some constraints, such as the maximum budget and labor availability. The team has now prepared a comprehensive list of these assumptions and constraints. What should the risk manager do?', 'بعد إعداد القائمة، ينبغي تحليل الافتراضات والقيود وتصنيفها لتحديد ما قد ينشئ عدم تأكد يؤثر في أهداف المشروع. يشمل ذلك اختبار صحة الافتراضات، وتحديد ما إذا كانت القيود قد تتغير أو تزيد التعرض، وتصنيف العناصر، وتقييم أثرها المحتمل في التكلفة والجدول الزمني والنطاق والجودة والموارد والسلامة. تُحوَّل حالات عدم التأكد المهمة إلى مخاطر واضحة وتُسجَّل في سجل المخاطر.', 'Once the list has been prepared, the assumptions and constraints should be analyzed and categorized to determine which of them could create uncertainty that affects the project objectives. This includes testing the validity of the assumptions, determining whether the constraints could change or increase exposure, classifying the items, and assessing their potential effect on cost, schedule, scope, quality, resources, and safety. Significant uncertainties are converted into clearly defined risks and recorded in the risk register.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إجراء تحليل نوعي وكمي للافتراضات والقيود.', 'Perform qualitative and quantitative analysis of the assumptions and constraints.', false),
      (1, 'أرشفة قائمة الافتراضات والقيود للرجوع إليها مستقبلًا.', 'Archive the list of assumptions and constraints for future reference.', false),
      (2, 'تحليل الافتراضات والقيود وتصنيفها.', 'Analyze and categorize the assumptions and constraints.', true),
      (3, 'إضافة قائمة الافتراضات والقيود إلى ملحق ميثاق المشروع.', 'Add the list of assumptions and constraints to an appendix of the project charter.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 61, id FROM question;

-- 63
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال مشروع لتطوير تطبيق برمجي جديد، لاحظ مدير المخاطر زيادة عدد المخاطر المحددة ذات المستوى المرتفع. ويوجد المشروع حاليًا في مرحلة التنفيذ، ويريد مدير المخاطر التأكد من استمرار فاعلية خطة إدارة المخاطر. ما الذي يجب على مدير المخاطر فعله لمراقبة هذه المخاطر والتحكم فيها؟', 'During a project to develop a new software application, the risk manager noticed an increase in the number of identified high-level risks. The project is currently in the execution phase, and the risk manager wants to ensure that the risk management plan remains effective. What should the risk manager do to monitor and control these risks?', 'تشير زيادة المخاطر ذات المستوى المرتفع إلى تغير ملف مخاطر المشروع. ينبغي تحديث سجل المخاطر بإضافة المخاطر الجديدة، والتحقق من وصفها وتصنيفها، وإعادة تقييم احتمالية وتأثير المخاطر الحالية، ومراجعة قرب الحدوث والمحفزات والحدود، وإعادة ترتيب الأولويات، ومراجعة ملكية المخاطر وفاعلية الاستجابات وتحديثها عند الحاجة. إدارة المخاطر عملية تكرارية تتطلب تحديث التقييمات والاستجابات عند تغير ظروف المشروع.', 'An increase in high-level risks indicates that the project''s risk profile has changed. The risk register should be updated by adding the new risks, verifying their descriptions and categories, reassessing the probability and impact of the existing risks, reviewing proximity, triggers, and thresholds, re-prioritizing, and reviewing risk ownership and the effectiveness of the responses, updating them where needed. Risk management is an iterative process that requires assessments and responses to be updated as project conditions change.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'الاستمرار في خطط الاستجابة الحالية وزيادة عدد مرات مراجعة المخاطر.', 'Continue with the current response plans and increase the frequency of risk reviews.', false),
      (1, 'تحديث سجل المخاطر بالمخاطر الجديدة وإعادة تقييم تأثير واحتمالية المخاطر الحالية.', 'Update the risk register with the new risks and reassess the impact and probability of the existing risks.', true),
      (2, 'تعيين مالك خطر لإدارة المخاطر الجديدة وإبلاغ راعي المشروع بها.', 'Assign a risk owner to manage the new risks and inform the project sponsor about them.', false),
      (3, 'إعادة تقييم جميع المخاطر من خلال إجراء تحليل كمي كامل لتحديد خطط الاستجابة.', 'Reassess all risks by performing a full quantitative analysis to determine the response plans.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 62, id FROM question;

-- 64
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يعمل فريق من الخبراء على مشروع معقد. ما هي الأدوات الثلاثة التي يمكن أن تساعد مدير المخاطر في اكتشاف مدى تعقيد المخاطر الإجمالية للمشروع؟ (اختر 3)', 'A team of experts is working on a complex project. Which three tools can help the risk manager to discover the complexity of the project''s overall risk? (Choose three)', 'الأدوات الثلاث المحددة في المصدر هي مخطط إيشيكاوا، ومخطط شجرة القرارات، وتحليل SWOT. يساعد مخطط إيشيكاوا في استكشاف الأسباب المحتملة، وشجرة القرارات في عرض البدائل والنتائج الممكنة، وتحليل SWOT في استكشاف نقاط القوة والضعف والفرص والتهديدات.', 'The three tools identified in the source are the Ishikawa diagram, the decision tree diagram, and SWOT analysis. The Ishikawa diagram helps to explore potential causes, the decision tree helps to display the alternatives and possible outcomes, and SWOT analysis helps to explore strengths, weaknesses, opportunities, and threats.', 3)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'مخطط إيشيكاوا.', 'Ishikawa diagram.', true),
      (1, 'مخطط شجرة القرارات.', 'Decision tree diagram.', true),
      (2, 'مخطط المسؤول والمحاسب والمستشار والمطلع (RACI).', 'Responsible, accountable, consulted, and informed (RACI) chart.', false),
      (3, 'تحليل نقاط القوة والضعف والفرص والتهديدات (SWOT).', 'Strengths, weaknesses, opportunities, and threats (SWOT) analysis.', true),
      (4, 'سجل المخاطر.', 'Risk register.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 63, id FROM question;

-- 65
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'لا يفهم فريق المشروع سبب حدوث خطر كان احتمال وقوعه منخفضًا جدًا أثناء تنفيذ المشروع، خصوصًا أن الفريق اهتم جيدًا بالتخطيط لهذا النوع من المخاطر خلال مرحلة تخطيط المخاطر. تأخر المشروع شهرين، ويفكر المعنيون في إلغاء المشروع. ويحتاج مدير المخاطر إلى إثبات إمكانية استكمال المشروع حتى نهايته. ما التحليل الذي يجب على مدير المخاطر إجراؤه لإثبات ذلك للمعنيين؟', 'The project team does not understand why a risk that had a very low probability of occurring materialized during project execution, especially since the team paid careful attention to planning for this type of risk during the risk planning phase. The project has been delayed by two months, and the stakeholders are considering canceling the project. The risk manager needs to demonstrate that the project can be completed to the end. Which analysis should the risk manager perform to demonstrate this to the stakeholders?', 'تأخر المشروع بالفعل شهرين، ويريد المعنيون دليلًا كميًا يوضح ما إذا كان لا يزال من الممكن استكماله. ينبغي تحديث النموذج بالجدول الزمني الحالي والتعرض الراهن للمخاطر، ثم إجراء تحليل مونت كارلو لمحاكاة سيناريوهات المدد المتبقية وتأثيرات المخاطر، وتقدير احتمالية الانتهاء في تواريخ مختلفة، وعرض مستويات ثقة مثل P50 وP70 وP80 والاحتياطي الزمني المطلوب.', 'The project has already been delayed by two months, and the stakeholders want quantitative evidence showing whether it can still be completed. The model should be updated with the current schedule and the present risk exposure, and then Monte Carlo analysis should be performed to simulate scenarios of the remaining durations and risk impacts, estimate the probability of finishing on different dates, and present confidence levels such as P50, P70, and P80 along with the schedule reserve required.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل إيشيكاوا.', 'Ishikawa analysis.', false),
      (1, 'التحليل النوعي للمخاطر.', 'Qualitative risk analysis.', false),
      (2, 'تحليل مونت كارلو.', 'Monte Carlo analysis.', true),
      (3, 'تحليل باريتو.', 'Pareto analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 64, id FROM question;

-- 66
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يمكن تنفيذ اختبار المنتج بعدة طرق. يقترح بعض أعضاء فريق المشروع إجراء الاختبار داخل بيئة معملية، بينما يوصي آخرون بإجراء التحليل باستخدام أساليب المحاكاة. واستشار مدير الاختبارات أحد زملائه، الذي أوصى بإجراء الاختبار من خلال تجارب ميدانية. ثم استشار مدير الاختبارات مدير المخاطر لتقييم المخاطر المرتبطة بعملية الاختبار. ما الأداة التي يجب على مدير المخاطر التفكير في استخدامها لتقييم مخاطر الاختبار؟', 'Product testing can be carried out in several ways. Some project team members propose conducting the testing in a laboratory environment, while others recommend performing the analysis using simulation techniques. The test manager consulted a colleague, who recommended conducting the testing through field trials. The test manager then consulted the risk manager to assess the risks associated with the testing process. Which tool should the risk manager consider using to assess the testing risks?', 'يمثل كل أسلوب للاختبار سيناريو مختلفًا له افتراضاته وقيوده ومخاطره. لذلك يساعد تحليل السيناريوهات على دراسة ما قد يحدث عند اختيار الاختبار المعملي أو المحاكاة أو التجارب الميدانية، ومقارنة مخاطر السلامة والبيئة، ودقة النتائج وموثوقيتها، والتكلفة والمدة، والموارد والمعدات المطلوبة والمتطلبات التنظيمية والقيود الفنية.', 'Each testing method represents a different scenario with its own assumptions, constraints, and risks. Scenario analysis therefore helps to examine what could happen if laboratory testing, simulation, or field trials are chosen, and to compare the safety and environmental risks, the accuracy and reliability of the results, the cost and duration, the resources and equipment required, the regulatory requirements, and the technical constraints.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل السيناريوهات.', 'Scenario analysis.', true),
      (1, 'محاكاة مونت كارلو.', 'Monte Carlo simulation.', false),
      (2, 'مصفوفة الاحتمالية والتأثير.', 'Probability and impact matrix.', false),
      (3, 'تحليل الحساسية.', 'Sensitivity analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 65, id FROM question;

-- 67
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يتعاون مدير المخاطر مع المعنيين في المشروع وفريق المشروع لتحديد المخاطر في مشروع البناء. يعتزم مدير المخاطر استخدام نهج يشرك المعنيين بناءً على المعلومات، مثل خط الأساس للنطاق وتقديرات المشروع، مع تحديد تأثيرات المخاطر أيضًا بناءً على هذا النهج. ما هو نهج تحديد المخاطر الذي يجب أن يستخدمه مدير المخاطر لتحقيق هذا الهدف؟', 'The risk manager is collaborating with the project stakeholders and the project team to identify risks on a construction project. The risk manager intends to use an approach that engages the stakeholders based on information such as the scope baseline and the project estimates, and also to determine the risk impacts based on this approach. Which risk identification approach should the risk manager use to achieve this objective?', 'يُستخدم العصف الذهني لإشراك فريق المشروع والمعنيين بصورة مباشرة في تحديد أكبر عدد ممكن من المخاطر. يمكن للمشاركين مراجعة خط الأساس للنطاق، وتقديرات التكلفة والمدة، ومتطلبات المشروع والوثائق الفنية والدروس المستفادة والافتراضات والقيود، ثم توليد الأفكار بشأن أحداث المخاطر وأسبابها ومصادرها وتأثيراتها المحتملة وتنظيمها لتوثيقها وتحليلها لاحقًا.', 'Brainstorming is used to engage the project team and stakeholders directly in identifying as many risks as possible. The participants can review the scope baseline, the cost and duration estimates, the project requirements, the technical documents, the lessons learned, and the assumptions and constraints, and then generate ideas about risk events, their causes, sources, and potential impacts, and organize them for later documentation and analysis.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'أسلوب دلفي.', 'Delphi technique.', false),
      (1, 'تحليل نقاط القوة والضعف والفرص والتهديدات (SWOT).', 'Strengths, weaknesses, opportunities, and threats (SWOT) analysis.', false),
      (2, 'العصف الذهني.', 'Brainstorming.', true),
      (3, 'تحليل الافتراضات والقيود.', 'Assumption and constraint analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 66, id FROM question;

-- 68
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يطلب المستثمر الرئيسي في مشروع إنشاء طريق باستمرار من أعضاء فريق المشروع معلومات عن تنفيذ المشروع. وقد أدى ذلك إلى قضاء الفريق 20% من يوم العمل في إعداد تقارير للمعنيين. ما الذي ينبغي على مدير المخاطر فعله لتحسين أسلوب الفريق في إعداد تقارير المخاطر؟', 'The main investor in a road construction project constantly asks the project team members for information about the project''s execution. As a result, the team spends 20% of its working day preparing reports for stakeholders. What should the risk manager do to improve the team''s approach to risk reporting?', 'تكرار طلب المستثمر للمعلومات يدل على أن التقارير الحالية لا تلبي احتياجاته بصورة كافية. ينبغي التعاون مع الفريق لتحسين تقارير المخاطر لتتضمن أهم المخاطر، ومستوى التعرض العام، وحالة تنفيذ الاستجابات، والمخاطر الناشئة والقريبة، واتجاهات المخاطر والتغييرات المهمة، في صيغة واضحة وموجزة تناسب احتياجات المستثمر. بذلك تقل الطلبات الفردية والوقت الذي يقضيه الفريق في إعداد تقارير إضافية.', 'The investor''s repeated requests for information indicate that the current reports do not adequately meet the investor''s needs. The risk manager should collaborate with the team to improve the risk reports so that they include the most important risks, the overall level of exposure, the implementation status of the responses, emerging and near-term risks, and risk trends and significant changes, in a clear and concise format that suits the investor''s needs. This reduces individual requests and the time the team spends preparing additional reports.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التعاون مع الفريق لتحسين تقارير مخاطر المشروع المرسلة إلى المعنيين.', 'Collaborate with the team to improve the project risk reports sent to the stakeholders.', true),
      (1, 'العمل مع راعي المشروع لضمان عدم تأثير المعنيين بصورة مباشرة على فريق المشروع.', 'Work with the project sponsor to ensure that the stakeholders do not directly influence the project team.', false),
      (2, 'توضيح معدل إصدار تقارير المخاطر المتفق عليه مسبقًا للمعنيين.', 'Explain the previously agreed frequency of risk reporting to the stakeholders.', false),
      (3, 'التحدث مع فريق المشروع والتأكد من تجنبه التواصل المباشر مع هذا المعني.', 'Speak with the project team and ensure that it avoids direct communication with this stakeholder.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 67, id FROM question;

