WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يشتمل المشروع على خمسة معنيين أساسيين. وبعد بضعة أشهر من بدء المشروع، حدث حدث سلبي متعلق بالمخاطر في المشروع، مما استلزم إبلاغ المعنيين الأساسيين. ما الذي ينبغي لمدير المخاطر أن يفعله بعد ذلك؟', 'The project involves five key stakeholders. A few months after the project started, a negative risk event occurred on the project, which required the key stakeholders to be informed. What should the risk manager do NEXT?', 'اتباع الإرشادات والقواعد المخططة لإبلاغ الأحداث الخطرة للمعنيين.', 'Follow the planned guidelines and rules for communicating risk events to the stakeholders.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'دعوة إلى عقد اجتماع مشترك مع المعنيين لطلب التوجيهات.', 'Call a joint meeting with the stakeholders to request guidance.', false),
      (1, 'دعوة إلى اجتماع إداري لشرح تفاصيل الحدث المحفوف بالمخاطر وتأثيره على المعنيين.', 'Call a management meeting to explain the details of the risk event and its effect on the stakeholders.', false),
      (2, 'اتباع الإرشادات والقواعد المخططة لإبلاغ الأحداث الخطرة للمعنيين.', 'Follow the planned guidelines and rules for communicating risk events to the stakeholders.', true),
      (3, 'تطوير إجراءات التخفيف لتقليل آثار المخاطر السلبية.', 'Develop mitigation actions to reduce the effects of the negative risk.', false)
    ) AS v (position, text_ar, text_en, is_correct)
