-- 71
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يدير هو مدير مشروع بناء. لقد حدد هو وفريق المشروع خطرًا في المشروع مع احتمال كبير لحدوثه وله تأثير عالٍ على تكلفة المشروع. تناقش بيل المخاطرة مع فيرجينيا، العميل الأساسي للمشروع، وتقرر إزالة المتطلبات المحيطة بالخطر من المشروع. لا تؤثر إزالة المتطلبات على نطاق المشروع، ولكن يمكن أن تحرر المشروع من التعرض لمخاطر عالية. ما هي الاستجابة للمخاطر التي تم تفعيلها في هذا المشروع؟', 'Bill is the manager of a construction project. He and the project team have identified a risk in the project with a high probability of occurring and a high impact on the project cost. Bill discusses the risk with Virginia, the primary customer of the project, and the decision is made to remove the requirements surrounding the risk from the project. Removing the requirements does not affect the project scope, but it can release the project from the high-risk exposure. Which risk response has been enacted in this project?', 'يحدث تجنب المخاطر عندما يعمل فريق المشروع على إزالة التهديد أو حماية المشروع من تأثير المخاطر. وقد يشمل ذلك تغيير بعض جوانب خطة الإدارة أو تغيير الهدف المعرض للخطر للقضاء على تأثير التهديد تمامًا.', 'Risk avoidance occurs when the project team acts to eliminate the threat or protect the project from the impact of the risk. This may involve changing some aspects of the management plan or changing the objective that is in jeopardy in order to eliminate the threat''s impact entirely.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'التجنب', 'Avoid', true),
      (1, 'القبول', 'Accept', false),
      (2, 'التحويل', 'Transfer', false),
      (3, 'التخفيف', 'Mitigate', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 70, id FROM question;

-- 72
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أثناء تنفيذ المشروع، يعلم مدير المشروع أن هناك العديد من المشكلات غير المتوقعة. العميل غير راضٍ لأن التسليمات تستغرق وقتًا أطول من المخطط لها وتتأثر جودة المخرجات. ما هي العملية التي يجب على مدير المشروع تنفيذها بتركيز أكبر أثناء تخطيط المشروع؟', 'During project execution, the project manager learns that there are many unexpected problems. The customer is dissatisfied because the deliverables are taking longer than planned and the quality of the outputs is being affected. Which process should the project manager have performed with greater focus during project planning?', 'الكلمات المفتاحية: العديد من المشكلات غير المتوقعة. أثناء مرحلة التخطيط، كان ينبغي تحديد جميع مخاطر المشروع التي قد تؤثر عليه، ثم تحليلها ووضع استراتيجيات للتعامل معها عند حدوثها.', 'Key words: many unexpected problems. During the planning phase, all of the project risks that could affect the project should have been identified, then analyzed, and strategies developed for dealing with them if they occur.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'وضع خطط الاستجابة للمخاطر', 'Plan Risk Responses', false),
      (1, 'مراقبة المخاطر', 'Monitor Risks', false),
      (2, 'وضع خطة إدارة المخاطر', 'Plan Risk Management', false),
      (3, 'تحديد المخاطر', 'Identify Risks', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 71, id FROM question;

-- 73
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم تكليف مدير مخاطر بمشروع قادم. وكان أحد كبار مديري المخاطر في المنظمة قد أنهى مؤخرًا مشروعًا مشابهًا، وقدم وثيقة للدروس المستفادة للمساعدة في التخطيط للمشروع الجديد. عند مراجعة الوثيقة، اكتشف مدير المخاطر أن المشروع السابق انتهى متأخرًا عدة أشهر وتجاوز الميزانية بعدة آلاف من الدولارات. وكان السبب الجذري محفز خطر غير متوقع أدى إلى إعادة تنفيذ عدة أعمال، مما تسبب في تأخيرات متتابعة في الجدول الزمني واستنزاف احتياطي الإدارة. ما الذي ينبغي على مدير المخاطر فعله لتقليل احتمال تكرار المشكلات نفسها؟', 'A risk manager has been assigned to an upcoming project. One of the organization''s senior risk managers recently completed a similar project and provided a lessons learned document to help with planning the new project. While reviewing the document, the risk manager discovered that the previous project finished several months late and exceeded its budget by several thousand dollars. The root cause was an unexpected risk trigger that led to several pieces of work being redone, causing cascading schedule delays and depleting the management reserve. What should the risk manager do to reduce the likelihood of the same problems recurring?', 'الدروس المستفادة من المشروع السابق كشفت محفز الخطر وتأثيراته في التكلفة والجدول الزمني؛ لذلك لم يعد الأمر مجهولًا في المشروع الجديد. يجب توثيق الأسباب ومحفزاتها وتأثيراتها في سجل المخاطر، وتعيين مالكي المخاطر ووضع استجابات ومراقبة محفزاتها.', 'The lessons learned from the previous project revealed the risk trigger and its effects on cost and schedule; it is therefore no longer an unknown on the new project. The causes, their triggers, and their effects must be documented in the risk register, risk owners assigned, responses developed, and the triggers monitored.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'زيادة احتياطيات الإدارة وإبلاغ المعنيين بما هو متاح لتغطية أي نفقات غير متوقعة.', 'Increase the management reserves and inform the stakeholders of what is available to cover any unexpected expenses.', false),
      (1, 'تأكد من أن جميع المعنيين في المشروع لديهم نسخة من خطة إدارة المخاطر الخاصة بالمشروع ويفهمونها.', 'Ensure that all project stakeholders have a copy of the project''s risk management plan and understand it.', false),
      (2, 'توثيق مسببات الخطر المعروفة كالتكلفة المحددة ومخاطر الجدول الزمني في سجل المخاطر.', 'Document the known risk causes, such as the identified cost and schedule risks, in the risk register.', true),
      (3, 'توزيع وثيقة الدروس المستفادة على المعنيين، مع افتراض أن احتمال تكرار المشكلة منخفض.', 'Distribute the lessons learned document to the stakeholders, assuming that the likelihood of the problem recurring is low.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 72, id FROM question;

-- 74
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مدير المخاطر بتيسير ورشة عمل لتحديد المخاطر المتعلقة بمنتج جديد مع خبراء فنيين. لا يوجد إجماع بين الخبراء الفنيين حول معظم المخاطر التي تم تحديدها وخصائصها. يقرر مدير المخاطر حل هذا الاختلاف باستخدام تقنية أخرى. ما هي التقنية التي يجب أن يستخدمها مدير المخاطر في هذا الموقف؟', 'The risk manager is facilitating a workshop with technical experts to identify the risks related to a new product. There is no consensus among the technical experts about most of the identified risks and their characteristics. The risk manager decides to resolve this disagreement using another technique. Which technique should the risk manager use in this situation?', 'يوجد اختلاف بين الخبراء الفنيين بشأن المخاطر وخصائصها، والمطلوب الوصول إلى توافق بينهم؛ لذلك يُستخدم أسلوب دلفي، الذي يجمع آراء الخبراء بصورة مجهولة عبر جولات متكررة، ثم يلخص الإجابات ويعيدها إلى الخبراء للمراجعة حتى الوصول إلى توافق.', 'There is disagreement among the technical experts about the risks and their characteristics, and consensus among them is required. The Delphi technique is therefore used; it collects the experts'' opinions anonymously over repeated rounds, then summarizes the responses and returns them to the experts for review until consensus is reached.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل قوائم المراجعة', 'Checklist analysis', false),
      (1, 'المجموعات التخصصية', 'Focus groups', false),
      (2, 'طريقة دلفي', 'Delphi technique', true),
      (3, 'العصف الذهني', 'Brainstorming', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 73, id FROM question;

-- 75
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'لدى مدير المخاطر عملية إدارة مخاطر منظمة جيدًا لمشروع معقد بجدول زمني ضيق. وعلى الرغم من تنفيذ الإجراءات الوقائية، فإن أحد المخاطر التي تم تحديدها في المراحل المبكرة من المشروع لا يزال يحدث ويشكل الآن مشكلة. ماذا يجب أن يفعل مدير المخاطر بعد ذلك؟', 'The risk manager has a well-structured risk management process for a complex project with a tight schedule. Despite the preventive actions that were implemented, one of the risks identified in the early stages of the project is still occurring and has now become an issue. What should the risk manager do NEXT?', 'لأن الخطر المحدد وقع بالفعل، يجب على مدير المخاطر تنفيذ خطة الاستجابة لمعالجة الحدث في أقرب وقت ممكن.', 'Because the identified risk has already occurred, the risk manager must implement the response plan to address the event as soon as possible.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'الاجتماع مع فريق المشروع لمناقشة الحلول المحتملة للمشكلة.', 'Meet with the project team to discuss possible solutions to the issue.', false),
      (1, 'تصعيد المشكلة إلى راعي المشروع للاتفاق على أفضل مسار للعمل.', 'Escalate the issue to the project sponsor to agree on the best course of action.', false),
      (2, 'بدء المناقشات مع مدير المشروع لتحديد كيفية إدارة المشكلة.', 'Start discussions with the project manager to determine how to manage the issue.', false),
      (3, 'تنفيذ خطة الاستجابة للمخاطر لمعالجة المشكلة في أقرب وقت ممكن.', 'Implement the risk response plan to address the issue as soon as possible.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 74, id FROM question;

-- 76
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم تعيين مدير مخاطر ليحل محل مدير مخاطر في إجازة مرضية. لاحظ مدير المخاطر الجديد أن سجل المخاطر يفتقر إلى البيانات الأساسية لعملية إدارة المخاطر. ما هي البيانات التي سيحتاجها مدير المخاطر أولًا؟', 'A risk manager has been appointed to replace a risk manager who is on sick leave. The new risk manager noticed that the risk register lacks the basic data for the risk management process. Which data will the risk manager need FIRST?', 'وصف المخاطر واحتمالية المخاطر وتأثير المخاطر.', 'Risk description, risk probability, and risk impact.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'وصف المخاطر والاستجابة للمخاطر والبيانات الكمية', 'Risk description, risk response, and quantitative data', false),
      (1, 'خطة المشروع، وتعقيد المخاطر والمخاطر الثانوية', 'Project plan, risk complexity, and secondary risks', false),
      (2, 'وصف المخاطر واحتمالية المخاطر وتأثير المخاطر', 'Risk description, risk probability, and risk impact', true),
      (3, 'خطة المشروع، وأولوية المخاطر وتوافر الأدوات', 'Project plan, risk priority, and tool availability', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
