WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يطلب أحد المعنيين من فريق المشروع توظيف بائع خارجي يتمتع بخبرة وقدرة أكبر على تسريع خطة التسليم. لدى الفريق بعض المخاوف بشأن هذا الطلب. ما الذي يجب أن يفعله مدير المخاطر أولًا؟', 'A stakeholder asks the project team to hire an external vendor with greater expertise and capacity to accelerate the delivery plan. The team has some concerns about this request. What should the risk manager do FIRST?', 'إجراء تحليل نقاط القوة والضعف والفرص والتهديدات (SWOT).', 'Perform a strengths, weaknesses, opportunities, and threats (SWOT) analysis.', 1)
  RETURNING id
