-- 78
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يريد مدير المخاطر تحديد ما يجب قياسه، وكيفية قياسه، ونتائج المشروع التي سيتم قياسها. في أي من العمليات التالية يجب إنشاء ذلك؟', 'The risk manager wants to define what should be measured, how it should be measured, and which project outcomes will be measured. In which of the following process groups should this be established?', 'الكلمة المفتاحية (ماذا - كيف)، لذلك الجواب الصحيح هو عمليات التخطيط.', 'The key words are "what" and "how"; therefore, the correct answer is the Planning processes.', 1)
