-- 79
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما يُعرَّف بأنه «حدث أو حالة غير مؤكدة يكون لها، في حالة حدوثها، تأثير إيجابي أو سلبي على هدف أو أكثر من أهداف المشروع» وثانيًا، ما هو الميل العقلي المختار تجاه عدم اليقين، المعتمد صراحة أو ضمنيًا من قبل الأفراد والجماعات؟', 'First, what is defined as "an uncertain event or condition that, if it occurs, has a positive or negative effect on one or more project objectives"? And second, what is the chosen mental disposition toward uncertainty, adopted explicitly or implicitly by individuals and groups?', 'الجزء الأول من التعريف هو تعريف الخطر؛ والجزء الثاني هو تعريف الموقف تجاه المخاطر. الموقف تجاه المخاطر هو تصرف تجاه عدم اليقين يتبناه الأفراد والجماعات بشكل صريح أو ضمني، يحركه الإدراك ويرتبط بسلوك يمكن ملاحظته.', 'The first part of the definition is the definition of risk; the second part is the definition of risk attitude. Risk attitude is a disposition toward uncertainty adopted explicitly or implicitly by individuals and groups, driven by perception and associated with observable behavior.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'الفرص / استراتيجية الاستجابة للخطر', 'Opportunity / Risk response strategy', false),
      (1, 'التهديدات / الموقف تجاه المخاطر', 'Threat / Risk attitude', false),
      (2, 'الخطر / الموقف تجاه المخاطر', 'Risk / Risk attitude', true),
      (3, 'الخطر / التعرض للخطر', 'Risk / Risk exposure', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 78, id FROM question;

-- 80
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت تدير مشروع بناء. أثناء مرحلة التنفيذ، أخبرك أحد أعضاء الفريق بحدوث أحد المخاطر التي تم تحديدها مسبقًا. بصفتك مدير مشروع، ماذا يجب أن تفعل بعد ذلك؟', 'You are managing a construction project. During the execution phase, a team member informs you that one of the previously identified risks has occurred. As the project manager, what should you do NEXT?', 'عند حدوث خطر تم تحديده مسبقًا، يجب عليك تحديث حالته في سجل المخاطر.', 'When a previously identified risk occurs, you must update its status in the risk register.', 1)
