-- 83
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت مدير لمشروع حكومي شديد السرية، وكان يسير كما هو مخطط له حتى وقت قريب. فجأة، يتصل بك أحد أعضاء الفريق ويعلمك أن المشروع واجه مشكلة كبيرة غير متوقعة لم يتم تصنيفها في سجل المخاطر. ما هو أول إجراء يجب عليك فعله؟', 'You are the manager of a highly confidential government project that was proceeding as planned until recently. Suddenly, a team member calls you and informs you that the project has encountered a major unexpected problem that was not categorized in the risk register. What is the FIRST action you should take?', 'عند حدوث خطر غير متوقع، فإن أول شيء يجب عليك فعله كمدير للمشروع هو معالجة الأمر من خلال إنشاء حل وإجراء سريع.', 'When an unforeseen risk occurs, the first thing you should do as the project manager is to address the matter by creating a workaround and taking prompt action.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'اتخاذ الإجراءات التصحيحية والوقائية', 'Take corrective and preventive actions', false),
      (1, 'وضع خطة احتياطية', 'Develop a fallback plan', false),
