-- 84
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت مدير مشروع في مشروع تطوير برمجيات. أنت تقوم حاليًا بإنشاء خطة لإدارة المخاطر لدعم هذه العملية. تحتاج إلى تحديد المستوى المقبول للتعرض العام لمخاطر المشروع. ما الذي ينبغي عليك فعله أولًا؟', 'You are the project manager on a software development project. You are currently creating a risk management plan to support this process. You need to determine the acceptable level of overall project risk exposure. What should you do FIRST?', 'يتم تسجيل الرغبة في المخاطر للمعنيين الرئيسيين في المشروع في خطة إدارة المخاطر على وجه الخصوص. يجب التعبير عن قابلية المعنيين للمخاطر على أنها عتبات مخاطر قابلة للقياس حول كل هدف من أهداف المشروع. ستحدد هذه العتبات المستوى المقبول للتعرض العام لمخاطر المشروع.', 'The risk appetite of the project''s key stakeholders is recorded specifically in the risk management plan. The stakeholders'' risk appetite should be expressed as measurable risk thresholds around each project objective. These thresholds determine the acceptable level of overall project risk exposure.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'مراجعة سجل التعرض للمخاطر ضمن أصول العملية التنظيمية', 'Review the risk exposure log in the organizational process assets', false),
      (1, 'تحديد الرغبة في المخاطرة للمعنيين الرئيسيين في المشروع', 'Determine the risk appetite of the project''s key stakeholders', true),
      (2, 'تسهيل اجتماع العصف الذهني لوضع قائمة شاملة بمخاطر المشروع', 'Facilitate a brainstorming meeting to develop a comprehensive list of project risks', false),
      (3, 'تطوير مجموعة من الاستجابات لمخاطر المشروع الفردية للتخفيف من مخاطر المشروع الإجمالية', 'Develop a set of responses to the individual project risks to mitigate the overall project risk', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
