-- 86
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'إذا تم استنفاد احتياطيات الطوارئ قبل اكتمال المشروع، ما هي التوصيات التي يمكن تنفيذها لمنع تكرار ذلك؟', 'If the contingency reserves are depleted before the project is completed, which recommendation could be implemented to prevent this from happening again?', 'تحليل الاحتياطي هو أسلوب تحليلي لتحديد السمات الأساسية وعلاقات المكونات في خطة إدارة العمل لإنشاء احتياطي لمدة الجدول الزمني أو الموازنة أو التكلفة المقدرة أو الأموال. يوفر تتبع حالة الاحتياطي من خلال التنفيذ معلومات موجزة عن تطور حالة المخاطر المتبقية. يمكن أن تكون هذه المعلومات مفيدة عند إبلاغ غيرهم من إدارة المنظمة. بالإضافة إلى ذلك، بمجرد حدوث الخطر أو توقعه، يمكن حدوث حالات أخرى أو يعود بإمكانية للتأثير، يجب مراجعة التخطيط بالمقابل لتقييم ما إذا كان لا يزال يوفر مستوى الثقة المتفق عليه.', 'Reserve analysis is an analytical technique used to determine the essential features and relationships of the components in the project management plan in order to establish a reserve for the schedule duration, budget, estimated cost, or funds. Tracking the status of the reserve throughout execution provides summary information about the evolving status of the residual risks. This information can be useful when reporting to others in the organization''s management. In addition, once a risk has occurred or is anticipated, or other conditions arise that could have an impact, the reserve planning should be reviewed to assess whether it still provides the agreed level of confidence.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'زيادة احتياطي الطوارئ', 'Increase the contingency reserve', false),
      (1, 'زيادة الخط المرجعي للتكلفة والجدول الزمني', 'Increase the cost and schedule baselines', false),
      (2, 'تنفيذ عملية تحليل الاحتياط', 'Perform the reserve analysis process', true),
      (3, 'استخدم محاكاة مونت كارلو', 'Use Monte Carlo simulation', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 85, id FROM question;

-- 87
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت تدير مشروعًا جديدًا لمؤسسة تسعى إلى المخاطرة. يحتوي مشروعك على مخاطر عامة تتجاوز مستويات المخاطر الموثقة في خطة إدارة المخاطر. ما هو إجراء يمكن للمؤسسة اتخاذه مع المشروع بناءً على نطاقه الحالي؟', 'You are managing a new project for a risk-seeking organization. Your project has an overall risk that exceeds the risk levels documented in the risk management plan. What action can the organization take with the project based on its current scope?', 'نظرًا لأن المشروع ينطوي على مخاطر عامة تتجاوز مستويات المخاطر الموثقة في خطة إدارة المخاطر، فإن أفضل مسار عمل للمنظمة هو إلغاء المشروع، حيث لا يزال المستوى العام للمخاطر غير مقبول.', 'Since the project involves an overall risk that exceeds the risk levels documented in the risk management plan, the best course of action for the organization is to cancel the project, as the overall level of risk remains unacceptable.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إجراء محاكاة مونت كارلو لفهم نتائج المخاطر المحتملة', 'Perform a Monte Carlo simulation to understand the possible risk outcomes', false),
      (1, 'إجراء تحليل احتياطي للتحقق من الاحتياطيات المتبقية', 'Perform a reserve analysis to verify the remaining reserves', false),
      (2, 'إلغاء المشروع، حيث يظل المستوى العام للمخاطر غير مقبول', 'Cancel the project, as the overall level of risk remains unacceptable', true),
      (3, 'مراقبة المخاطر المستمرة عن قرب بأية تغييرات كبيرة', 'Closely monitor the ongoing risks for any significant changes', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
