WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت مدير مشروع مسؤول عن مشروع مهم لشركتك. يقدم لك قسم الهندسة بعض الموارد الموهوبة بنفس التكلفة. بصفتك مدير مشروع، ماذا يجب أن تفعل بعد ذلك؟', 'You are the project manager responsible for an important project for your company. The engineering department offers you some talented resources at the same cost. As the project manager, what should you do NEXT?', 'يجب أن يكون مدير المشروع استباقيًا والخطوة الأولى هي تحليل تأثير استبدال الموارد واستغلال الفرصة.', 'The project manager must be proactive, and the first step is to analyze the impact of replacing the resources and exploit the opportunity.', 1)
  RETURNING id
), choices AS (
