  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'إذا أراد مدير المشروع مراجعة فعالية الاستجابة للمخاطر من المشاريع السابقة، أي مما يلي يحتاج إلى مراجعته؟', 'If the project manager wants to review the effectiveness of the risk responses from previous projects, which of the following needs to be reviewed?', 'يجد مدير المشروع فعالية الاستجابة للمخاطر من المشاريع السابقة في الدروس المستفادة وتدقيق المخاطر ضمن أصول عمليات المؤسسة.', 'The project manager finds the effectiveness of the risk responses from previous projects in the lessons learned and the risk audits within the organizational process assets.', 1)
