-- 90
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت مدير مخاطر لمشروع كبير في شركتك. أثناء عملية المراقبة والتحكم، أي مما يلي ينبغي عليك فعله؟', 'You are the risk manager of a large project at your company. During the monitoring and controlling process, which of the following should you do?', 'أثناء عملية المراقبة والتحكم، يجب على مدير المخاطر مراجعة المخاطر المحددة، والانتباه لأحداث المخاطر، وتذكير أعضاء الفريق بإبقاء مدير المخاطر على علم بمحفزات المخاطر. الخيارات الأخرى غير صحيحة لأن إنشاء خطة إدارة المخاطر هو عملية التخطيط لإدارة المخاطر وليس في عملية المراقبة والتحكم.', 'During the monitoring and controlling process, the risk manager should review the identified risks, watch for risk events, and remind team members to keep the risk manager informed of risk triggers. The other options are incorrect because creating the risk management plan belongs to the Plan Risk Management process, not to the monitoring and controlling process.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'الانتباه لأحداث المخاطر، وتذكير أعضاء الفريق بإبقاء مدير المخاطر على اطلاع دائم بمحفزات المخاطر، وإنشاء خطة إدارة المخاطر', 'Watch for risk events, remind team members to keep the risk manager continuously informed of risk triggers, and create the risk management plan', false),
      (1, 'وضع خطة لإدارة المخاطر، وتطوير الاستجابات للمخاطر، وتحديد المخاطر', 'Develop the risk management plan, develop the risk responses, and identify the risks', false),
      (2, 'مراجعة المخاطر المحددة، وتحديث وثائق الدروس المستفادة، وإنشاء خطة إدارة المخاطر', 'Review the identified risks, update the lessons learned documents, and create the risk management plan', false),
      (3, 'مراجعة المخاطر التي تم تحديدها، الانتباه لأحداث المخاطر، وتذكير أعضاء الفريق بإبقاء مدير المخاطر على علم بمحفزات المخاطر', 'Review the identified risks, watch for risk events, and remind team members to keep the risk manager informed of risk triggers', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
