-- 91
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما هو الفرق بين التحليل النوعي والكمي للمخاطر؟', 'What is the difference between qualitative and quantitative risk analysis?', 'يعالج التحليل النوعي للمخاطر المخاطر الفردية، ويتنبأ التحليل الكمي للمخاطر بالنتائج المحتملة للمشروع بناءً على التأثيرات المشتركة للمخاطر.', 'Qualitative risk analysis addresses individual risks, and quantitative risk analysis predicts likely project outcomes based on the combined effects of risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'يعالج التحليل النوعي للمخاطر المخاطر الفردية بشكل وصفي، ويتنبأ التحليل الكمي للمخاطر بالنتائج المحتملة للمشروع بناءً على التأثيرات المركبة للمخاطر.', 'Qualitative risk analysis addresses individual risks descriptively, and quantitative risk analysis predicts likely project outcomes based on the combined effects of risks.', true),
      (1, 'التحليل الكمي للمخاطر والتحليل النوعي للمخاطر متماثلان.', 'Quantitative risk analysis and qualitative risk analysis are the same.', false),
      (2, 'يعطي التحليل الكمي للمخاطر الأولوية للمخاطر الفردية للمعالجة اللاحقة، ويؤدي التحليل النوعي للمخاطر إلى التحليل الكمي للمخاطر.', 'Quantitative risk analysis prioritizes individual risks for subsequent treatment, and qualitative risk analysis leads to quantitative risk analysis.', false),
      (3, 'يتناول التحليل الكمي للمخاطر المخاطر الفردية بشكل وصفي، ويتنبأ التحليل النوعي للمخاطر بالنتائج المحتملة للمشروع بناءً على التأثيرات المجمعة للمخاطر.', 'Quantitative risk analysis addresses individual risks descriptively, and qualitative risk analysis predicts likely project outcomes based on the aggregated effects of risks.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 90, id FROM question;

-- 92
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أي مما يلي يصف موقف أحد المعنيين إذا كان غير راغب في اتخاذ قرارات من شأنها أن تؤدي إلى تأثير سلبي على المشروع؟', 'Which of the following describes the attitude of a stakeholder who is unwilling to make decisions that could lead to a negative impact on the project?', 'الكلمة الرئيسية «غير راغب»: الشخص أو المنظمة التي تتجنب المخاطرة غير متاحة لتقبل المخاطر؛ إنهم ليسوا مبدعين أو داعمين لها، ويحاولون عادةً تجنب المخاطر وعدم الرغبة في اتخاذ قرارات من شأنها أن تؤدي إلى تأثير سلبي على المشروع.', 'The key word is "unwilling": a risk-averse person or organization is not open to accepting risk; they are not creative or supportive of it, and they usually try to avoid risk and are unwilling to make decisions that could lead to a negative impact on the project.', 1)
  RETURNING id
), choices AS (
