      (2, 'باحث عن المخاطر', 'Risk-seeking', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 91, id FROM question;

-- 93
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أنت تدير مشروع بناء مركز تسوق. أي مما يلي يوفر النتائج لتحديث وثائق مخاطر المشروع كنتيجة لعملية مراقبة المخاطر؟', 'You are managing a shopping mall construction project. Which of the following provides the results for updating the project risk documents as an outcome of the Monitor Risks process?', 'تتضمن مستندات المشروع التي قد يتم تحديثها نتيجة لعملية التحكم في المخاطر نتائج إعادة تقييم المخاطر، وتدقيق المخاطر، ومراجعات المخاطر الدورية. قد تشمل هذه النتائج تحديد المخاطر الجديدة، والتحديثات على الاحتمالية، والأثر، والأولوية، وخطط الاستجابة، والملكية، وعناصر أخرى في سجل المخاطر. يمكن أن تشمل النتائج أيضًا إغلاق المخاطر التي لم تعد قابلة للتطبيق والإفراج عن الاحتياطيات المرتبطة بها.', 'The project documents that may be updated as a result of the risk control process include the results of risk reassessments, risk audits, and periodic risk reviews. These results may include the identification of new risks and updates to probability, impact, priority, response plans, ownership, and other elements of the risk register. The results may also include closing risks that are no longer applicable and releasing the reserves associated with them.', 1)
  RETURNING id
