      (1, 'احتياطي المخاطر والباحث عن المخاطر.', 'Risk reserve and risk-seeker.', false),
      (2, 'تحليل احتياطي المخاطر وموقف المخاطر.', 'Risk reserve analysis and risk attitude.', false),
      (3, 'استراتيجيات الاستجابة للمخاطر وتحليل المعنيين.', 'Risk response strategies and stakeholder analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
