-- 94
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مدير المشروع والمعنيين بمراجعة وثائق المشروع لتحديد الفرص التي سيتم تحقيقها إذا تم الانتهاء من المشروع في وقت مبكر. في نهاية المراجعة، ما هي الوثيقة التي ينبغي تحديثها؟', 'The project manager and the stakeholders are reviewing the project documents to identify the opportunities that would be realized if the project is completed early. At the end of the review, which document should be updated?', 'المخرج الأساسي من عملية تحديد المخاطر هو سجل المخاطر. جميع الفرص والتهديدات التي تم تحديدها يتم توثيقها في سجل المخاطر.', 'The primary output of the Identify Risks process is the risk register. All identified opportunities and threats are documented in the risk register.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
