      (1, 'سجل المخاطر', 'Risk register', true),
      (2, 'الوصف الهرمي للمخاطر', 'Risk breakdown structure', false),
      (3, 'خطة إدارة المخاطر', 'Risk management plan', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 93, id FROM question;

-- 95
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'جاك هو مدير المخاطر لمشروع ما زال في منتصف الطريق من تنفيذه. يحدد جاك المخاطر المتبقية التي لم يتم أخذها في الاعتبار أثناء عملية الاستجابة للمخاطر في الخطة ولكنها قد تؤثر على خط الأساس للجدول الزمني للمشروع. ما الذي يجب أن يفعله جاك للتعامل مع هذه المخاطر المتبقية؟', 'Jack is the risk manager of a project that is still midway through its execution. Jack identifies residual risks that were not taken into account during the risk response process in the plan but that could affect the project''s schedule baseline. What should Jack do to deal with these residual risks?', 'قد تكون هناك مخاطر متبقية ستبقى بعد تنفيذ الاستجابات. يجب تحديد هذه المخاطر المتبقية بوضوح وتحليلها وتوثيقها وإبلاغها لجميع المعنيين.', 'There may be residual risks that remain after the responses have been implemented. These residual risks must be clearly identified, analyzed, documented, and communicated to all stakeholders.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تقبل المخاطر، لأنها مخاطر ذات أولوية منخفضة.', 'Accept the risks, as they are low-priority risks.', false),
      (1, 'إصدار طلب تغيير لزيادة الاحتياطي الإداري.', 'Issue a change request to increase the management reserve.', false),
      (2, 'تحليل هذه المخاطر ثم تنفيذ الاستجابة للمخاطر.', 'Analyze these risks and then implement the risk response.', false),
      (3, 'تحليل هذه المخاطر وتحديث سجل المخاطر.', 'Analyze these risks and update the risk register.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 94, id FROM question;

-- 96
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'خلال تدقيق الشركة، وجدت أنه لا توجد معلومات عن إدارة المخاطر في قاعدة بيانات الدروس المستفادة. ما الذي يمكن أن تفعله الشركة لدعم أصول عمليات المؤسسة لإدارة المخاطر؟', 'During a company audit, you found that there is no information about risk management in the lessons learned database. What can the company do to support the organizational process assets for risk management?', 'اطلب من مدير المشروع تسجيل معلومات مهمة عن إدارة المخاطر، لتوفير بيانات ملموسة في قاعدة بيانات الدروس المستفادة للمشاريع المستقبلية.', 'Ask the project manager to record important risk management information to provide tangible data in the lessons learned database for future projects.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'مطالبة مدير المشروع بتحديث سياسة وإجراءات مكتب إدارة المشاريع PMO على أساس تكراري لضمان ملاءمتها للمشروع الحالي.', 'Ask the project manager to update the project management office (PMO) policy and procedures on an iterative basis to ensure that they are suitable for the current project.', false),
      (1, 'مطالبة مكتب إدارة المشاريع بجمع سجلات المخاطر وتوزيعها على جميع المعنيين الرئيسيين المرتبطين بإدارة المخاطر.', 'Ask the PMO to collect the risk registers and distribute them to all key stakeholders associated with risk management.', false),
      (2, 'مطالبة مكتب إدارة المشاريع بإجراء عمليات تدقيق الجودة في جميع المشاريع النشطة، لضمان التوافق مع معايير صناعة الاتصالات.', 'Ask the PMO to conduct quality audits on all active projects to ensure alignment with the telecommunications industry standards.', false),
      (3, 'اطلب من مدير المشروع تسجيل معلومات مهمة عن إدارة المخاطر، لتوفير بيانات ملموسة في قاعدة بيانات الدروس المستفادة للمشاريع المستقبلية.', 'Ask the project manager to record important risk management information to provide tangible data in the lessons learned database for future projects.', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 95, id FROM question;

-- 97
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما هي عوامل النجاح الرئيسية لعملية تحديد المخاطر؟', 'What are the critical success factors for the risk identification process?', 'عوامل النجاح الرئيسية لتحديد المخاطر تشمل التحديد المبكر، والتحديد المتكرر، والتحديد المتطور، والتحديد الشامل، والتحديد الصريح للفرص، ووجهات النظر المتعددة، والمخاطر المرتبطة بالأهداف، والتوثيق الكامل للخطر، والملكية ومستوى التفاصيل، والاتصال المتكرر والفعال، والموضوعية لتقليل التحيز. المصدر يذكر معيار إدارة المخاطر في محافظ المشاريع والبرامج والمشاريع، صفحة 33.', 'The critical success factors for risk identification include early identification, iterative identification, emergent identification, comprehensive identification, explicit identification of opportunities, multiple perspectives, risks linked to objectives, complete risk statements, ownership and level of detail, frequent and effective communication, and objectivity to reduce bias. The source cites The Standard for Risk Management in Portfolios, Programs, and Projects, page 33.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'يجب إجراء تحديد المخاطر في وقت مبكر من دورة حياة المشروع قدر الإمكان، ويجب وصف المخاطر بوضوح وربطها بأهداف المشروع.', 'Risk identification should be performed as early as possible in the project life cycle, and risks should be clearly described and linked to the project objectives.', true),
      (1, 'يجب إجراء تحديد المخاطر في وقت مبكر من دورة حياة المشروع قدر الإمكان، ويجب وصف المخاطر بوضوح، والعلاقات المتبادلة بين المخاطر في التحليل الكمي للمخاطر.', 'Risk identification should be performed as early as possible in the project life cycle, risks should be clearly described, and the interrelationships between risks should be addressed in quantitative risk analysis.', false),
      (2, 'يجب إجراء تحديد المخاطر في وقت مبكر من دورة حياة المشروع قدر الإمكان، ويجب وصف المخاطر بوضوح، واستخدام نموذج مشروع خاص.', 'Risk identification should be performed as early as possible in the project life cycle, risks should be clearly described, and a custom project template should be used.', false),
      (3, 'يجب أن يستند تحديد المخاطر إلى تعريفات متفق عليها، وجمع معلومات عالية الجودة حول المخاطر، واستخدامها بشكل دوري في جميع أنحاء المشروع.', 'Risk identification should be based on agreed definitions, the collection of high-quality information about risks, and its periodic use throughout the project.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 96, id FROM question;

-- 98
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما هو أفضل مصدر لمعلومات المشروع التي يمكن أن تؤدي إلى تقليل المخاطر؟', 'What is the BEST source of project information that can lead to a reduction in risk?', 'الكلمة المفتاحية «أفضل مصدر لمعلومات المشروع»: مراجعة أصول عمليات المؤسسة والدروس المستفادة من المشاريع السابقة المماثلة تساعد على معرفة وتقليل المخاطر.', 'The key phrase is "BEST source of project information": reviewing the organizational process assets and the lessons learned from similar previous projects helps to understand and reduce risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل الحساسية.', 'Sensitivity analysis.', false),
      (1, 'تحديد المخاطر باستخدام تقنيات العصف الذهني.', 'Identifying risks using brainstorming techniques.', false),
      (2, 'مراجعة أصول عمليات المؤسسة والدروس المستفادة من المشاريع السابقة مماثلة في طبيعتها.', 'Reviewing the organizational process assets and the lessons learned from previous projects that are similar in nature.', true),
      (3, 'قم بعمل ملاحظات / مدونات حول المشروع الحالي.', 'Taking notes and keeping journals about the current project.', false)
    ) AS v (position, text_ar, text_en, is_correct)
