-- 99
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم مدير المشروع بتطوير عملية إدارة المخاطر ويقوم بجدولة ورشة عمل لتخطيط المخاطر في بداية المشروع. عند تلقي الدعوة، يقوم أحد كبار المعنيين بإرسال بريد إلكتروني إلى مدير المشروع موضحًا أن خطة إدارة المخاطر ليست ضرورية نظرًا لأن هذا مشروع صغير، وسيؤدي عدم وجود خطة إلى تقليل التكاليف. أي مما يلي يجب على مدير المشروع فعله؟', 'The project manager is developing the risk management process and schedules a risk planning workshop at the beginning of the project. On receiving the invitation, a senior stakeholder sends an email to the project manager stating that a risk management plan is not necessary because this is a small project, and that not having a plan will reduce costs. Which of the following should the project manager do?', 'إبلاغ المعنيين بأن إدارة المخاطر يجب أن تطبق على جميع المشاريع لأنها ذات قيمة.', 'Inform the stakeholder that risk management must be applied to all projects because it adds value.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إبلاغ المعنيين بأن إدارة المخاطر مهمة وذات قيمة ويجب تطبيقها على جميع المشاريع.', 'Inform the stakeholder that risk management is important and valuable and should be applied to all projects.', true),
      (1, 'الاستمرار في ورشة العمل، ولكن قم بإزالة هذا المعني من قائمة الحاضرين.', 'Proceed with the workshop, but remove this stakeholder from the attendee list.', false),
      (2, 'مراجعة نطاق المشروع في محاولة لتوفير المال في مجالات أخرى من المشروع لتوفير التمويل لأنشطة إدارة المخاطر.', 'Review the project scope in an attempt to save money in other areas of the project to fund the risk management activities.', false),
      (3, 'إلغاء ورشة العمل، حيث أن هذا المعني خبير وأن إدارة المخاطر هي عملية اختيارية، خاصة في المشاريع الصغيرة.', 'Cancel the workshop, since this stakeholder is an expert and risk management is an optional process, especially on small projects.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 98, id FROM question;

-- 100
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يقوم بعض المهندسين بإكمال نشاط من شأنه تنبيه فريق المشروع في حالة وجود خطر يتطلب بذل جهد إضافي لإكمال المشروع. ماذا ينبغي لمدير المخاطر أن يفعل في حالة ظهور العلامة التحذيرية؟', 'Some engineers are completing an activity that would alert the project team in the event of a risk that requires additional effort to complete the project. What should the risk manager do if the warning sign appears?', 'ينفذ المهندسون نشاطًا يوفر تنبيهًا عند احتمال الحاجة إلى مجهود إضافي. يمثل هذا التنبيه محفز خطر (Risk Trigger) أو علامة تحذيرية محددة مسبقًا. عند حدوث المحفز، يجب على مدير المخاطر تفعيل خطة الطوارئ المعتمدة والمرتبطة بهذا الخطر، وتتضمن خطة الطوارئ الإجراءات التي يجب تنفيذها عند تحقق شروط محددة. ويجب أيضًا التأكد من حدوث المحفز، وإبلاغ مالك الخطر والمسؤولين عن إجراءات الاستجابة، وتنفيذ إجراءات الطوارئ المخططة، ومراقبة مدى فاعليتها، وتحديث سجل المخاطر ووثائق المشروع المرتبطة، وتقييم أي مخاطر متبقية أو ثانوية.', 'The engineers are performing an activity that provides an alert when additional effort may be needed. This alert represents a risk trigger, or a predefined warning sign. When the trigger occurs, the risk manager must activate the approved contingency plan associated with this risk; the contingency plan contains the actions to be taken when specific conditions are met. The risk manager must also confirm that the trigger has occurred, inform the risk owner and the risk action owners, implement the planned contingency actions, monitor their effectiveness, update the risk register and the associated project documents, and assess any residual or secondary risks.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تفعيل خطة الطوارئ', 'Activate the contingency plan', true),
      (1, 'تحديث خطة الاستجابة للمخاطر', 'Update the risk response plan', false),
      (2, 'إضافة التنبيه إلى سجل المخاطر', 'Add the alert to the risk register', false),
      (3, 'طلب زيادة الاحتياطيات', 'Request an increase in the reserves', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 99, id FROM question;

-- 101
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'بعد الانتهاء من سجل المخاطر، يشعر العديد من أعضاء الفريق بعدم وجود أولوية زمنية لأحد المخاطر التي تم تحديدها. ما الذي يشير إليه أعضاء الفريق؟', 'After the risk register has been completed, several team members feel that there is no time priority for one of the identified risks. What are the team members referring to?', 'العلامة التحذيرية للخطر: حدث أو موقف يشير إلى أن الخطر على وشك الحدوث.', 'Risk warning sign (trigger): an event or situation that indicates that a risk is about to occur.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'إلحاح المخاطر', 'Risk urgency', false),
      (1, 'تصعيد المخاطر', 'Risk escalation', false),
      (2, 'العلامة التحذيرية للخطر', 'Risk warning sign', true),
      (3, 'تأثير المخاطرة على الوقت', 'Risk impact on time', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
