-- 102
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'في بداية أي مشروع صغير، يقوم مدير المخاطر بتيسير عقد ورش عمل لتحديد المخاطر وتحليلها. وفي نهاية الجلسات، يقول أحد المعنيين إنه لا ينبغي أن تكون هناك حاجة للقاء مرة أخرى بشأن سجل المخاطر الآن بعد اكتماله نظرًا لأنه مشروع قصير وبسيط. كيف ينبغي لمدير المخاطر الرد على هذا التعليق؟', 'At the start of a small project, the risk manager facilitates workshops to identify and analyze the risks. At the end of the sessions, a stakeholder says that there should be no need to meet again about the risk register now that it is complete, since it is a short and simple project. How should the risk manager respond to this comment?', 'الإصرار على المراجعة المستمرة وتحديث سجل المخاطر أثناء تنفيذ المشروع.', 'Insist on continuous review and updating of the risk register during project execution.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'يجب تحديث سجل المخاطر فقط إذا تمت الموافقة على التغيير أثناء المشروع.', 'The risk register should be updated only if a change is approved during the project.', false),
      (1, 'الإصرار على المراجعة المستمرة وتحديث سجل المخاطر أثناء تنفيذ المشروع.', 'Insist on continuous review and updating of the risk register during project execution.', true),
      (2, 'التسوية عن طريق تحديث سجل المخاطر في نهاية كل مرحلة فقط.', 'Compromise by updating the risk register only at the end of each phase.', false),
      (3, 'الاتفاق على شرط تحديث سجل المخاطر في حالة تغير بيئة المشروع.', 'Agree on a condition that the risk register will be updated if the project environment changes.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 101, id FROM question;

-- 103
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'لا يفهم فريق المشروع سبب حدوث مخاطر ذات احتمالية منخفضة للغاية أثناء تنفيذ المشروع. كان الفريق يقظًا بشكل خاص بشأن التخطيط لهذا النوع من المخاطر أثناء مرحلة تخطيط المخاطر. تأخر المشروع لمدة شهرين ويفكر المعنيون في إلغاء المشروع. يحتاج مدير المخاطر إلى إثبات إمكانية الانتهاء من المشروع. ما التحليل الذي يجب أن يقوم به مدير المخاطر لإثبات ذلك للمعنيين؟', 'The project team does not understand why a risk with an extremely low probability occurred during project execution. The team was especially vigilant about planning for this type of risk during the risk planning phase. The project has been delayed by two months, and the stakeholders are considering canceling the project. The risk manager needs to demonstrate that the project can be completed. Which analysis should the risk manager perform to demonstrate this to the stakeholders?', 'تحليل مونت كارلو. المخرج من هذا التحليل يوضح احتمالية تحقيق أهداف محددة، ومن خلاله يكون قادرًا على إثبات إمكانية إنهاء المشروع.', 'Monte Carlo analysis. The output of this analysis shows the probability of achieving specific objectives, and through it the risk manager is able to demonstrate that the project can be completed.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'تحليل السبب الجذري', 'Root cause analysis', false),
      (1, 'تحليل مونت كارلو', 'Monte Carlo analysis', true),
      (2, 'التحليل النوعي للمخاطر', 'Qualitative risk analysis', false),
      (3, 'تحليل باريتو', 'Pareto analysis', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 102, id FROM question;

-- 104
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'تم تكليف مدير المخاطر بإعداد خطة إدارة المخاطر لمشروع جديد. ما هو العامل الذي ينبغي لمدير المخاطر أن يعطيه الأولوية عند تصميم عمليات إدارة المخاطر للمشروع الجديد؟', 'The risk manager has been assigned to prepare the risk management plan for a new project. Which factor should the risk manager prioritize when designing the risk management processes for the new project?', 'نضج عمليات إدارة المخاطر في المنظمة. تتضمن خطة إدارة المخاطر عمليات إدارة مخاطر مصممة خصيصًا، والتي تعتمد على نضج عملية المنظمة.', 'The maturity of the organization''s risk management processes. The risk management plan includes tailored risk management processes, which depend on the maturity of the organization''s processes.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'نضج عمليات إدارة المخاطر في المنظمة', 'The maturity of the organization''s risk management processes', true),
      (1, 'حجم ومدة المشروع', 'The size and duration of the project', false),
      (2, 'عدد المعنيين المرتبطين بالمشروع', 'The number of stakeholders associated with the project', false),
      (3, 'الأموال المتاحة لأنشطة إدارة المخاطر', 'The funds available for risk management activities', false)
