-- 107
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'إجمالي احتياطي الطوارئ = 213,000 دولار أمريكي. إذا تم تخفيض احتمالية الخطر 4 إلى 40%، فما هو إجمالي احتياطي الطوارئ الجديد؟
جدول المصدر (الخطر | الاحتمالية | المتفائل | الأكثر احتمالًا | المتشائم | احتياطي الطوارئ):
1 | 10% | 20,000 | 30,000 | 80,000 | 3,000
2 | 40% | 10,000 | 20,000 | 40,000 | 8,000
3 | 30% | 40,000 | 60,000 | 90,000 | 90,000
4 | 80% | 30,000 | 40,000 | 60,000 | 112,000', 'Total contingency reserve = US$213,000. If the probability of Risk 4 is reduced to 40%, what is the new total contingency reserve?
Source table (Risk | Probability | Optimistic | Most Likely | Pessimistic | Contingency Reserve):
1 | 10% | 20,000 | 30,000 | 80,000 | 3,000
2 | 40% | 10,000 | 20,000 | 40,000 | 8,000
3 | 30% | 40,000 | 60,000 | 90,000 | 90,000
4 | 80% | 30,000 | 40,000 | 60,000 | 112,000', 'وفق تفسير المصدر: احتياطي الطوارئ للخطر 4 = 112,000؛ وعند تخفيض احتماليته إلى النصف يصبح 56,000؛ ولذلك إجمالي احتياطي الطوارئ الجديد = 213,000 − 56,000 = 157,000 دولار. ملاحظة تحريرية: نص السؤال يذكر تخفيض الاحتمالية إلى 40%، والجدول يذكر للخطر 4 احتمال 80%، لكن بيانات الجدول نفسها لا تفسر بصورة متسقة قيمة احتياطي الخطر 4 البالغة 112,000؛ لذا نُقلت الإجابة والحساب كما وردا في المصدر دون تصحيح افتراضي.', 'According to the source explanation: the contingency reserve for Risk 4 = 112,000; when its probability is halved, it becomes 56,000; therefore, the new total contingency reserve = 213,000 − 56,000 = US$157,000. Editorial note: the question text states that the probability is reduced to 40%, and the table lists a probability of 80% for Risk 4, but the table data itself does not consistently explain the Risk 4 reserve value of 112,000; the answer and calculation have therefore been reproduced exactly as given in the source, without any assumed correction.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, '92,400 دولار أمريكي', 'US$92,400', false),
      (1, '157,000 دولار أمريكي', 'US$157,000', true),
      (2, '145,800 دولار أمريكي', 'US$145,800', false),
      (3, '39,000 دولار أمريكي', 'US$39,000', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 106, id FROM question;

