WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'يستخدم مشروعك قطعة من المعدات التي إذا تجاوزت درجة حرارة الجهاز 450 درجة فهرنهايت، فسوف ترتفع درجة حرارة الجهاز وسيتعين إيقاف تشغيله لمدة 48 ساعة. في حالة ارتفاع درجة حرارة هذا الجهاز حتى مرة واحدة، فسيؤدي ذلك إلى تأخير تاريخ انتهاء المشروع. أنت تعمل مع مشروعك لإنشاء استجابة لأنه في حالة وصول درجة حرارة الماكينة إلى 430، ستتوقف الماكينة مؤقتًا لمدة ساعة على الأقل لتبريدها. درجة حرارة 430 ماذا تسمى؟', 'Your project uses a piece of equipment that, if its temperature exceeds 450 degrees Fahrenheit, will overheat and will have to be shut down for 48 hours. If this equipment overheats even once, it will delay the project finish date. You are working with your project to create a response so that if the machine''s temperature reaches 430 degrees, the machine will be paused for at least one hour to cool down. What is the 430-degree temperature called?', 'درجة الحرارة 430 تسمى محفز الخطر. محفزات المخاطر هي حدث أو موقف أو علامة تحذيرية تشير إلى أن هناك خطرًا على وشك الحدوث.', 'The 430-degree temperature is called a risk trigger. Risk triggers are an event, situation, or warning sign that indicates that a risk is about to occur.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'استجابة الخطر', 'Risk response', false),
      (1, 'حدث الخطر', 'Risk event', false),
      (2, 'تعريف الخطر', 'Risk definition', false),
      (3, 'محفزات الخطر', 'Risk trigger', true)
    ) AS v (position, text_ar, text_en, is_correct)
)
