-- 113
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'أي من العبارات التالية يصف بشكل أفضل متطلبات نوع البيانات المستخدمة في التحليل النوعي للمخاطر؟', 'Which of the following statements BEST describes the requirements for the type of data used in qualitative risk analysis?', 'يتطلب التحليل النوعي للمخاطر بيانات دقيقة وغير متحيزة وأن تكون ذات مصداقية. عوامل النجاح الرئيسية لإجراء التحليل النوعي للمخاطر: استخدام المنهج المتفق عليه؛ استخدام التعاريف المتفق عليها لمصطلحات المخاطر؛ جمع المعلومات الموثوقة حول المخاطر؛ وإجراء التحليل النوعي المتكرر للمخاطر. معيار إدارة المخاطر في محافظ المشاريع والبرامج والمشاريع، صفحة 34.', 'Qualitative risk analysis requires data that is accurate, unbiased, and credible. The critical success factors for performing qualitative risk analysis are: using the agreed approach; using agreed definitions of risk terms; collecting reliable information about risks; and performing qualitative risk analysis iteratively. The Standard for Risk Management in Portfolios, Programs, and Projects, page 34.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'يتطلب التحليل النوعي للمخاطر بيانات دقيقة وغير متحيزة وأن تكون ذات مصداقية.', 'Qualitative risk analysis requires data that is accurate, unbiased, and credible.', true),
      (1, 'يتطلب التحليل النوعي للمخاطر المحللين غير المتحيزين مع تحمل المخاطر المتحيزة.', 'Qualitative risk analysis requires unbiased analysts with biased risk tolerance.', false),
      (2, 'يشجع التحليل النوعي للمخاطر البيانات المتحيزة للكشف عن تحمل المخاطر.', 'Qualitative risk analysis encourages biased data to reveal risk tolerance.', false),
      (3, 'يتطلب التحليل النوعي للمخاطر بيانات سريعة وبسيطة لإكمال التحليل.', 'Qualitative risk analysis requires quick and simple data to complete the analysis.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
