-- 114
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'ما هو الفرق الأساسي بين تدقيق المخاطر وإعادة تقييم المخاطر؟', 'What is the fundamental difference between a risk audit and a risk reassessment?', 'إعادة تقييم المخاطر هو نشاط مستمر من قبل فريق المشروع، يجب مناقشة المخاطر في كل اجتماع. يتم إجراء عمليات تدقيق المخاطر خلال دورة حياة المشروع لفحص وتوثيق فعالية استجابات المخاطر. يتم إجراؤها على الترددات المناسبة على النحو المحدد في خطة إدارة المخاطر.', 'Risk reassessment is an ongoing activity performed by the project team; risks should be discussed at every meeting. Risk audits are conducted during the project life cycle to examine and document the effectiveness of the risk responses. They are performed at the appropriate frequency as defined in the risk management plan.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'المعنيين في المشروع يقوموا بإجراء عمليات تدقيق المخاطر. تجري الإدارة عمليات إعادة تقييم.', 'The project stakeholders conduct the risk audits; management conducts the reassessments.', false),
      (1, 'تتم جدولة عمليات إعادة تقييم المخاطر بانتظام؛ يتم إجراء عمليات تدقيق المخاطر على النحو المحدد في خطة إدارة مخاطر المشروع.', 'Risk reassessments are scheduled regularly; risk audits are conducted as defined in the project risk management plan.', true),
      (2, 'ليس هناك فرق؛ هم تقريبًا نفس الشيء.', 'There is no difference; they are essentially the same thing.', false),
      (3, 'يتم إجراء إعادة تقييم للمخاطر عند الانتهاء من مرحلة رئيسية؛ يتم إجراء عمليات التدقيق بعد اكتمال المشروع.', 'A risk reassessment is conducted at the completion of a major phase; audits are conducted after the project is complete.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 113, id FROM question;

-- 115
WITH question AS (
  INSERT INTO public.questions (type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
  VALUES ('multiple-choice', 'عند الانتهاء من مشروع صغير، يقوم مدير المخاطر بإجراء تدقيق للمخاطر ووجد أن العديد من المخاطر المحددة قد حدثت، وكان التأثير أكبر بكثير مما كان متوقعًا. بينما ظل المشروع في الموعد المحدد، زادت ميزانية المشروع بنسبة 50٪. حقق المشروع جميع مراحل الاستجابة للمخاطر ولم تحدث مخاطر إضافية لم يتم تحديدها من قبل في المشروع. بناءً على هذه المعلومات، ما هو تحسين عملية إدارة المخاطر الذي يجب أن يوصي به مدير المخاطر للمشاريع المماثلة في المستقبل؟', 'At the completion of a small project, the risk manager conducts a risk audit and finds that several of the identified risks occurred, and their impact was much greater than expected. While the project remained on schedule, the project budget increased by 50%. The project achieved all of its risk response milestones, and no additional, previously unidentified risks occurred on the project. Based on this information, which risk management process improvement should the risk manager recommend for similar projects in the future?', 'يجب أن يوصي مدير المخاطر بتوثيق تقرير تدقيق المخاطر وتسجيله في قاعدة بيانات الدروس المستفادة لمشاريع مماثلة في المستقبل.', 'The risk manager should recommend documenting the risk audit report and recording it in the lessons learned database for similar projects in the future.', 1)
  RETURNING id
), choices AS (
  INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  SELECT question.id, v.position, v.text_ar, v.text_en, v.is_correct
    FROM question, (VALUES
      (0, 'توثيق تقرير تدقيق المخاطر والاحتفاظ به في قاعدة بيانات الدروس المستفادة.', 'Document the risk audit report and keep it in the lessons learned database.', true),
      (1, 'زيادة وتيرة اجتماعات إدارة المخاطر مع مدير المشروع.', 'Increase the frequency of risk management meetings with the project manager.', false),
      (2, 'مراجعة مستوى دقة درجات الاحتمالية والتأثير.', 'Review the level of accuracy of the probability and impact scores.', false),
      (3, 'التوسع في استخدام تقنيات تحديد المخاطر.', 'Expand the use of risk identification techniques.', false)
    ) AS v (position, text_ar, text_en, is_correct)
)
INSERT INTO public.exam_questions (exam_id, question_index, question_id)
SELECT 48, 114, id FROM question;


-- ---------------------------------------------------------------------------
-- Assertions against what landed, mirroring 017's.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_bad INTEGER;
BEGIN
  SELECT count(*) INTO v_bad
    FROM public.exams x
   WHERE x.id = 48
     AND x.question_count <> (SELECT count(*) FROM public.exam_questions q WHERE q.exam_id = x.id);
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'Migration 018: exam 48 disagrees with its exam_questions count';
  END IF;

  SELECT count(*) INTO v_bad
    FROM public.exam_questions eq
   WHERE eq.exam_id = 48
     AND NOT EXISTS (SELECT 1 FROM public.choices c WHERE c.question_id = eq.question_id AND c.is_correct);
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'Migration 018: % question(s) have no correct choice', v_bad;
  END IF;

  SELECT count(*) INTO v_bad
    FROM public.exam_questions eq
    JOIN public.questions q ON q.id = eq.question_id
   WHERE eq.exam_id = 48
     AND q.answer_count <> (SELECT count(*) FROM public.choices c WHERE c.question_id = q.id AND c.is_correct);
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'Migration 018: % question(s) have a stale answer_count', v_bad;
  END IF;
END $$;
